window.DEEPWOKEN_DATA = window.DEEPWOKEN_DATA || {};
window.DEEPWOKEN_DATA.ru = {"translations":{"against-all-odds":{"description":"За каждую боевую метку (Combat Tag) на вашем персонаже ваш урон увеличивается на 2% (максимум 14%).","info":["Работает в PvE: каждый моб считается отдельной боевой меткой."],"stats":""},"emergency-reserves":{"description":"Когда вас бьют и здоровье падает ниже 20%, вы мгновенно получаете 20% Темпа (Tempo).","info":["Даёт 20% от максимального Темпа при срабатывании.","Перезарядка 3 минуты.","Пока здоровье ниже порога в 20%, талант срабатывает при каждом попадании по вам. Если он на перезарядке, перезарядка обновляется, и больше ничего не происходит."],"stats":""},"unswayed":{"description":"Эффекты провокации (Taunt) и Encore на вас больше не действуют.","info":["Мантра Taunt и талант Cornered Fool больше не накладывают на вас провокацию.","Мантра Sing больше не может активировать талант Encore на вас, что убирает эффект оглушения.","Sing по-прежнему может наложить на вас очарование (Charm) и сверхочарование (Overcharm)."],"stats":"+20 к Рассудку"},"kick-off":{"description":"Вы легко переносите небольшие падения и не получаете урона. Первый прыжок от стены всегда поднимает вас выше обычного. После прыжка через стену вы получаете ускорение (Speed Boost).","info":["Все падения считаются на 10 студов «короче»: урон от больших падений снижается, а небольшие падения полностью нивелируются.","Увеличивает дистанцию лазания примерно на 15%, если талант не на перезарядке. Перезарядка 3 секунды.","Прыжок в скольжении теперь тоже немного увеличивает дистанцию лазания."],"stats":"+6 к пассивной Ловкости"},"steady-footing":{"description":"Вас гораздо труднее сдвинуть с места.","info":["Снижает получаемое отбрасывание на 20% (суммируется с другими источниками сопротивления отбрасыванию, включая Anchor Pips).","Из-за этого противникам проще продолжать комбо после ударов, отбрасывающих вас, поэтому вне PvE талант брать не рекомендуется.","Убирает бонусную дистанцию скольжения по льду, но не влияет на сниженное трение при движении по льду.","Для игроков Frostdraw это серьёзный минус без каких-либо плюсов, поэтому брать талант не рекомендуется."],"stats":"+5 к грузоподъёмности (Carry Load), +2 к пассивной Ловкости"},"time-to-go":{"description":"Убийство даёт ускорение на 10 секунд. Убийство игрока удваивает ускорение и его длительность.","info":["Даёт ускорение на 25%, которое удваивается до 50% при убийстве игрока.","Активирует все таланты, связанные с ускорением.","Длительность визуально показывает красное свечение у глаз игрока.","Эффект суммируется, поэтому, убивая несколько целей сразу, можно набрать огромную скорость."],"stats":"+1 к пассивной Ловкости"},"an-ironsinger-s-instinct":{"description":"Успешное уклонение покрывает вас металлом и снижает урон от следующей полученной атаки.","info":["После уклонения вы получаете на 2 секунды эффект Ironsinger's Instinct, снижающий урон от следующего удара на 60%.","Пока эффект активен, вы визуально покрываетесь серым металлическим блеском, который пропадает при получении удара.","Перезарядка 18 секунд, начинается сразу после уклонения."],"stats":""},"exposed-durability":{"description":"Вы наносите на 10% больше урона противникам, у которых не осталось прочности брони (Armor Durability).","info":["Также действует на игроков в наряде Stranded Outfit.","Отлично сочетается со способностями, истощающими прочность брони противника, например Corrosive Touch у Arachnid's Weave и зачарованием Metal Enchantment."],"stats":""},"phantom-edge":{"description":"Дальность ваших обычных атак (M1) с оружием увеличивается на 0,25.","info":["Брать этот талант не рекомендуется: его эффект объективно ничтожен и незаметен.","Суммируется с другими источниками увеличения дальности оружия, например Duelist's Lunge."],"stats":""},"everchanging-aegis":{"description":"Вы получаете на 20% меньше урона от атак той же стихии, что и последняя атака, попавшая по вам, но на 10% больше урона от атак другой стихии.","info":["Попадание другой стихии сразу меняет вашу сопротивляемость на эту стихию. Например, если у вас было сопротивление Galebreathe и вас задела мантра Shadowcast, сопротивление тут же сменится на Shadowcast, и наоборот.","Из-за этого мантры с несколькими попаданиями гораздо слабее, даже если ваш Everchanging Aegis не был настроен на этот тип урона.","Тип Aegis может смениться при блоке, уклонении и парировании. Чтобы смена произошла, не обязательно получать удар, что в значительной мере смягчает недостаток.","Горение (Burn) и урон по себе не активируют Everchanging Aegis.","Стихию, к которой у вас сопротивление, показывает цветной щит; непрерывный урон той же стихии даёт цветной контур.","Flamecharm: оранжевый / Frostdraw: синий / Thundercall: жёлтый / Galebreathe: зелёный / Shadowcast: фиолетовый / Ironsing: серый / Bloodrend: красный","Не влияет на атаки, не наносящие стихийный урон."],"stats":""},"overflowing-dam":{"description":"Если ваш Эфир (Ether) полон 2 секунды или дольше, ваши атаки получают ауру, дающую им на 10% больше урона.","info":["За каждое очко Интеллекта ниже 40 бонус к урону от Overflowing Dam снижается на 0,125%; минимальный бонус составляет 6,875% при 15 Интеллекта.","Для Warlock и Ether Refined Mantle бонус составит 5,625% при 5 Интеллекта; для Khan с этим снаряжением: 5,25% при 2 Интеллекта или 5% при 0 Интеллекта."],"stats":""},"perfect-flash":{"description":"Если у вас больше 95% здоровья, ваши мантры наносят на 25% больше урона. Бонус снижается до 10%, если противники далеко.","info":[],"stats":""},"wyvern-s-claw":{"description":"Пока вы в воздухе, вы наносите на 10% больше урона. Для мантр бонус составляет 5%.","info":["Срабатывает, если вы около 0,75 секунды не касались земли.","Очень хорошо сочетается с аперкотами."],"stats":""},"aerogliding":{"description":"При падении с высоты удерживайте пробел, чтобы создавать воздушные потоки до приземления. Также увеличивает время полёта на планёрах (Gliders).","info":["Подготовка занимает 1 секунду.","Пока активно, создаёт ауру, которая замедляет падение и останавливает урон от падения.","Не отменяет уже начавшийся урон от падения: если вы уже падали, Aerogliding при активации всё равно может нанести вам урон.","Автоматически заканчивается через 5 секунд, но его можно активировать заново в воздухе до 3 раз; при этом подготовка заставит вас получить урон от падения.","Зависая в воздухе, можно постоянно повторно активировать Aerogliding и не получать урона от падения.","Пока активно, слегка подталкивает вас вперёд, давая контроль над движением.","Значительно снижает потерю высоты на планёре, позволяя пролетать намного большие расстояния. (Суммируется с Feathered Glider)","Старый талант «The Old Wind» был объединён с этим."],"stats":"+2 к пассивной Ловкости"},"gale-trap":{"description":"Если вы повергаете игрока в нокаут, создаётся воздушная ловушка: любой, кто поднимет это тело, будет отброшен в воздух. Если тело поднимете вы сами, вы получите ускорение. Убийство PvE-противников вместо этого даёт вам Gale Reflection.","info":["Если вы ищете мантру Galebreathe, смотрите Galetrap.","Отмечает игроков, поверженных вами в нокаут, на 6 секунд меткой «Gale Trap».","Если вы поднимаете отмеченную цель, вы получаете ускорение на 35% на 20 секунд.","Если отмеченную цель пытается поднять кто-то другой, он падает в ragdoll и подбрасывается вверх. Это относится и к союзникам.","Gale Reflection срабатывает, когда вас бьёт враг: он снижает урон атаки и ставит на врага Gale Trap. Урон Gale Trap зависит от силы убитого вами противника."],"stats":""},"stifled-jump":{"description":"Удушье (Suffocation) теперь накладывает оглушение (Dazed), если противники прыгают. Удушаемые PvE-противники также получают Sluggish.","info":["Эффект оглушения длится 1 секунду.","Статус Sluggish снижает урон поражённых целей на 15%."],"stats":"+2 к пассивной Ловкости"},"suffocating-impact":{"description":"Flourish-атака, отбросившая противника в стену, накладывает на него одышку (Winded) и удушье (Suffocating) на короткое время.","info":[],"stats":"+2 к пассивной Ловкости"},"vacuum-punch":{"description":"Ваш Gale Punch притягивает врагов до удара.","info":["Gale Punch теперь притягивает игроков к вам во время подготовки мантры. (Нельзя отменить финтом)","Увеличивает подготовку Gale Punch на 0,1 с, до 0,65 с в сумме."],"stats":""},"apothecary":{"description":"Приготовленные вами зелья усиливают положительные эффекты при употреблении и отрицательные при броске.","info":["Аддитивно увеличивает силу (Potency) зелья на 125%. В характеристиках приготовленных зелий это не отображается. (Подробнее на странице зелий.)","Бонус работает как ингредиент зелья, поэтому после варки Apothecary больше ничего не делает.","Старый талант Exterminator был объединён с этим."],"stats":""},"chain-reaction":{"description":"Если применить эффект зелья к тому, на ком уже есть эффект, новый эффект усиливается. При питье зелий есть 25% шанс не расходовать их.","info":["Срабатывает, когда брошенное зелье заменяет эффект другого зелья. (На выпитые зелья не действует)","Увеличивает эффективность зелья на 40%, бонус применяется мультипликативно к силе.","Старый талант Taste Test был объединён с этим."],"stats":""},"chemistry-kit":{"description":"Вы больше не роняете зелья при смерти. С шансом 25% вы варите дополнительное зелье.","info":["Соли Saltchemist по умолчанию тоже не дают зельям выпадать при смерти, но их нельзя выбросить вручную.","При варке зелий с шансом 25% вы получите 2 зелья вместо 1.","Таланты Wild Alchemy и Chemist's Bag были объединены с этим талантом."],"stats":""},"placebo-effect":{"description":"Если пить зелья рядом с союзниками, эффект зелья делится и на них.","info":["Также вызывает зельную болезнь (potion sickness): союзников вырвет при использовании, если они недавно пили зелье.","Эффективный радиус ровно 30 студов."],"stats":""},"potion-quaffer":{"description":"Вы привыкли быстро пить токсичные жидкости и легко найдёте общий язык с посетителями таверны. Питьё зелий меньше замедляет вас и даёт вам более сильные восстанавливающие эффекты.","info":["Зелья пьются на 30% быстрее: 1,645 с вместо базовых 2,35 с. В бою зелья с восстановлением здоровья (мгновенным или постепенным), положительным или отрицательным, пьются 2,85 с вместо базовых 3,55 с.","Повышенная эффективность зелий применяется мультипликативно после силы (Potency).","Увеличивает эффективность зелий регенерации здоровья на 15%. Действует только если зелье выпито.","Увеличивает эффективность зелий восстановления Рассудка и регенерации Эфира на 30%. Действует только если зелье выпито.","Убирает врождённый штраф -25% к эффективности зелий мгновенного лечения и повышает их эффективность в бою с -75% до -50%. Действует только если зелье выпито.","Старый талант Subsistence был объединён с этим."],"stats":""},"approaching-singularity":{"description":"Вы получаете +1% к пробиванию брони мантр (PEN) за каждые 10 очков Интеллекта.","info":["Даёт 0,1% PEN мантр за каждое очко Интеллекта.","Даёт +8% PEN при требовании, +5,5% PEN при минимальном требовании и +10% PEN при 100 Интеллекта."],"stats":""},"endurance-runner":{"description":"Низкое здоровье меньше снижает вашу скорость.","info":["Вдвое уменьшает штраф к скорости от потерянного здоровья.","Сейчас не работает."],"stats":"+2 к пассивной Ловкости"},"scaredy-cat":{"description":"Если враги первыми начинают бой, вы получаете ускорение.","info":["Даёт ускорение на 42,5% на 5 секунд.","Чтобы эффект сработал, враг не должен находиться в бою."],"stats":"+2 к пассивной Ловкости"},"composite-path-alloyblood":{"description":"Сплавляет стержни Ironsing из мантр Ironsing и отравление кровью (Blood Poisoning) из мантр Bloodrend в композитную плазму, текущую в крови противников. Ваши мантры Bloodrend становятся серебряными.","info":["Накопление Metal Rod и Blood Poison заменяется накоплением Composite Alloy. Чтобы применять мантры Alloyblood, нужно накопить определённый порог Composite Alloy."],"stats":""},"hypoferritinemia":{"description":"Rising Plasma теперь призывает ваш Metal Greatsword. У Metal Greatsword появляется врождённый урон сквозь блок (chip) 75%, который растёт тем больше, чем больше композитной плазмы в противнике.","info":["Мантра Rising Plasma теперь призывает Metal Greatsword вместо Alloyblood Axe."],"stats":""},"plasma-refresh":{"description":"При применении гибридной мантры alloyblood перезарядка вашей критической атаки обновляется. Ваши критические удары оружием alloyblood теперь добавляют противнику композитную плазму.","info":["Помните, что у всего оружия Alloyblood (Alloyblood Axe, Alloyblood Daggers и Alloyblood Spear) критические атаки такие же, как по умолчанию у их типа оружия."],"stats":""},"plasma-signal":{"description":"Противник теперь издаёт звук и подсвечивается, когда в нём достаточно плазмы для вашей мантры Rising Plasma. При этом плазма противника увеличивается на 10%.","info":[],"stats":""},"retained-hemoglobin":{"description":"Использование мантры alloyblood снижает стоимость композитной плазмы следующей мантры alloyblood на 20%. Эффект длится 10 секунд и суммируется.","info":[],"stats":""},"stored-plasma":{"description":"Финт мантрой alloyblood увеличивает на 33% длительность следующего оружия, призванного мантрой alloyblood.","info":[],"stats":""},"ultrafiltration":{"description":"Отфильтровывает композитную плазму из ваших гибридных мантр bloodalloy, позволяя им снова накладывать стихийные эффекты ironsing/bloodrend.","info":["Ваши мантры Alloyblood (Infused Slash, Rising Plasma и Spinning Serum) теперь при попадании накладывают Blood Poisoning и Metal Rods."],"stats":""},"flame-within":{"description":"Применение концепции Pleeksty о внутреннем пламени, также известном как душа человека. Подожгите себя, чтобы получить больше скорости передвижения и +10% к урону.","info":["Стоит 25 Эфира для активации.","В отличие от обычного горения, горение от Flame Within не снимается перекатом или скольжением. Оно длится 30 секунд или до повторного использования Flame Within.","Перезарядка Flame Within 8 секунд и начинается при активации. То есть если дать ему гореть достаточно долго, перезарядка фактически сводится на нет (кроме иммунитета к горению). Инструмент таланта показывает это неверно.","Flame Within даёт бонус к мобильности, а НЕ ускорение (Speed Boost), поэтому он не активирует таланты, зависящие от ускорения.","Даёт общий бонус к урону, поэтому влияет на все источники урона, которые можно изменить.","Flame Within можно включить в бессознательном состоянии (Unconscious). Это задумано для синергии с другим талантом, но при этом сила того таланта уменьшается вдвое.","Наносит вам урон при использовании, отдельно от урона горения. Этот урон можно снизить талантом Already Dead у Deepscorn Casque, сопротивлением Flamecharm и общими сопротивлениями.","Урон от горения снижают сопротивление Flamecharm, Immolation, Flame Wisp, Grotesque Resilience у Parasol Planter (снижение урона на 25%), Intrepid Flame у Flame Worshipper Armor, Worshipper Tolerance у Worshipper's Shield и источники общего снижения урона. Для билдов с Flame Within рекомендуется малое вложение во Flamecharm, чтобы получать меньше урона.","Deepfire Ring сокращает длительность Flame Within до 25 с, не уменьшая получаемый урон от горения. Это прямой штраф для Flame Within.","Старый талант Last Laugh был объединён с Flame Within."],"stats":""},"carnivore":{"description":"В обмен на потерю возможности есть растительную пищу вы утоляете голод, убивая других.","info":["Вас теперь тошнит от растительной еды (Food). Обычная и мясная еда по-прежнему съедобны.","Вы получаете сытость и утоляете жажду при казни монстра, NPC или игрока. Количество зависит от силы цели.","Не работает на некоторых мобов, например Servants of Enmity, и на Lightning Clones, призванных игроками."],"stats":""},"grand-feast":{"description":"Восстанавливает Темп (Tempo), Эфир (Ether), кровь и здоровье, когда вы получаете сытость за убийство.","info":["Лечение отключено в PvP-бою.","При срабатывании другого таланта восстанавливается 40% максимального Темпа, 55% максимального Эфира, 3% максимальной крови и 5% максимального здоровья."],"stats":"+1 к пассивной Ловкости"},"sunken-predator":{"description":"У врагов, которых вы бьёте в воде или в Глубинах, пропадают бонусы к скорости, и они замедляются.","info":["Монстры сильно замедляются на несколько секунд и при достаточном числе ударов могут быть заморожены на месте.","Игроки замедляются лишь слегка и на меньшее время."],"stats":"+1 к пассивной Ловкости"},"master-craftsman":{"description":"Ваших навыков достаточно, чтобы обойтись без станции крафта.","info":["Игрок постоянно получает эффекты Crafting Station и может создавать рецепты станции крафта прямо из инвентаря (например, Gliders)."],"stats":"+5 к здоровью"},"deep-wound":{"description":"Убийство из тени (assassination) накладывает анти-лечение (Anti-Heal) на 20 с и даёт вам ускорение на 6 с. Урон убийства из тени теперь растёт с уровнем против мобов.","info":["Бонус к урону от этого таланта в PvE очень высок и позволяет убивать с одного удара очень прочных врагов, например Authority Commander, несмотря на их 5000 здоровья.","Накладывает 60% анти-лечения, что показывают красные частицы облака."],"stats":""},"lights-out":{"description":"Убийства из тени теперь дают вам 30% PEN и ослепляют цель на 5 с. Тем, кого вы несёте, теперь завязывают глаза.","info":["У носимых целей появляется визуальный эффект ослепления, сильно мешающий обзору."],"stats":"+1 к пассивной Ловкости"},"lowstride":{"description":"Когда вы приседаете, ваша скрытность и дальность переката увеличиваются. Скорость в приседе падает меньше. Вы достаёте оружие бесшумно.","info":["Удваивает бонусы скрытности от приседания.","Обычно приседание увеличивает скрытность в 1,5 раза и затем добавляет +50, а с Lowstride приседание увеличивает скрытность в 2 раза и добавляет +100.","Скрытность × 1,5 + 50 -> Скрытность × 2 + 100.","Убирает звуки убирания и доставания оружия.","Ускоряет приседание до скорости ходьбы.","Увеличивает дальность переката на 15% в приседе.","Очень сильная синергия с «Murmur: Tacet», который требует приседания."],"stats":"+1 к пассивной Ловкости"},"unseen-threat":{"description":"Вы можете совершать убийство из тени над теми, у кого в руках оружие, если вы сами не в бою. Те, кого вы убили из тени, замедляются и получают Grounded на 5 с.","info":["Этот талант позволяет совершать убийство из тени над врагами, которые в бою и держат оружие.","Статус Grounded не даёт прыгать.","Старый талант Low Blow был объединён с этим."],"stats":""},"authority-intimidation":{"description":"Молниеносные приёмы сильнее замедляют противника.","info":["Работает с Surge Path."],"stats":""},"first-interrogation":{"description":"Атаки противников под Electrified дают вам Эфир, пропорциональный их исходному урону.","info":["Срабатывает только на атаки оружием от противников под Electrified.","Количество Эфира равно половине масштабированного урона атаки.","Эфир даётся, даже если вы заблокировали, парировали или уклонились от их атаки."],"stats":""},"resolve-crusher":{"description":"Молниеносные приёмы теперь накладывают стаки «Resolve Crusher». При 4 стаках на противника накладывается «Electrified». Атаки противников под Electrified превращаются в урон молнией, но наносят вам на 10% меньше урона.","info":["Не путайте с талантом Electrify: у целей под Electrified урон оружием меняется на урон Thundercall.","Electrified снижает урон только от атак оружием.","Electrified срабатывает при попадании атаки, которая наложила бы пятый стак, а не четвёртый.","Стаки набирают только мантры Thundercall. Урон молнией из любых других источников стаки не накапливает.","Стаки держатся 5 секунд. У стаков нет независимой длительности: новый стак обновляет длительность всех стаков, но если 5 секунд не накладывать новый, все стаки пропадут.","Сработавший Electrified длится 4 секунды.","Визуальный эффект этого таланта сейчас работает с ошибкой."],"stats":""},"second-interrogation":{"description":"Противники под Electrified наносят вам на 50% меньше урона и на 50% меньше урона по Стойке (Posture).","info":["Не суммируется со снижением урона от Resolve Crusher: вместо него действует этот, более сильный эффект.","Как и Resolve Crusher, действует только на атаки оружием."],"stats":""},"battle-tendency":{"description":"Вам легче дышать: Стойка (Posture) восстанавливается на 20% быстрее.","info":["В бою, когда вы не бежите и не блокируете, Стойка восстанавливается пассивно. Battle Tendency увеличивает это восстановление на 20%."],"stats":"+2 к Стойке, +10 к Рассудку"},"braced-collapse":{"description":"После пробития вашего блока следующая атака по вам наносит сниженный урон.","info":["После пробития блока следующий урон снижается на 20%. Перезарядки нет."],"stats":""},"moving-fortress":{"description":"Блок меньше замедляет вас.","info":["Увеличивает скорость передвижения при блоке на 6,6%: с -25% до -18,4%."],"stats":""},"perseverance":{"description":"Сокращает на 25% время, которое вы проводите в ragdoll и без сознания (Unconscious).","info":["Может суммироваться с другими талантами, ещё сильнее сокращая время без сознания."],"stats":"+5 к Рассудку"},"berserk":{"description":"Тому, кому нечего терять, есть что приобрести. Поддайтесь пылающей внутри ярости и войдите в состояние Berserk.","info":["В состоянии Berserk ваши обычные атаки (M1) получают повышенный PEN, который растёт тем сильнее, чем меньше у вас здоровья. Без нужного таланта этот бонус ограничен 50%. Кроме того, ваши критические атаки получают +10% PEN. В обмен весь получаемый вами урон на время эффекта становится чистым (true damage).","В PvE ваши M1 всегда получают +100% PEN независимо от здоровья.","Длится 20 секунд, а если вы не выполняете требование таланта по Силе, то 10 секунд.","Berserk можно отключить через 10 секунд повторным использованием инструмента таланта.","При активации ваши глаза и волосы краснеют, а за глазами тянется красный след. Цвет можно красить. (Сейчас с ошибкой: цвет волос не меняется)"],"stats":""},"heavy-cannonball":{"description":"Удваивает перезарядку вашей критической атаки, но увеличивает урон ядра на 50%.","info":["Усиливает именно урон снаряда у критических атак Greatcannon.","Это даёт примерно +29% итогового урона у стандартной критической атаки Greatcannon и примерно +33% у критической атаки Smouldering Hallow, если все попадания достигают цели.","Не работает на Edenbrand Hellcoil, так как он не выпускает снаряд.","Critical Engine с Blessed Gem может вернуть перезарядку критической атаки к исходному значению. Также талант Max Ammo у Summer Hullwrecker может полностью сбросить перезарядку, когда ядро попадает в цель."],"stats":""},"mortar-mystery":{"description":"Критическая атака Greatcannon, попавшая в цель, призывает сверху загадочные ядра, которые целятся в противника.","info":["На каждую попавшую критическую атаку создаётся 3 снаряда миномёта на каждую пораженную сущность.","Каждый снаряд миномёта наносит 30 урона при попадании.","Перезарядка 10 секунд на каждую цель."],"stats":""},"sticky-flames":{"description":"Ядро базовой критической атаки Greatcannon оставляет при попадании липкое пламя на 3 секунды.","info":["Базовое горение (Burn) стандартной критической атаки Greatcannon улучшается до Sticky Burn: его нельзя снять в течение 3 секунд после наложения."],"stats":""},"bloodwarden-s-sense":{"description":"Враги, которых вы атакуете мантрой при отравлении кровью (Blood Poisoning) выше 60%, получают на 5 с метку Bloodwarden's Mark.","info":["Под Bloodwarden's Mark ваш персонаж подсвечивается красным, и вы получаете на 20% больше Blood Poisoning."],"stats":""},"smell-of-blood":{"description":"Враги, которые заходят в ваши лужи крови или чей блок пробили вы, получают Bloodscent на 6 с.","info":["Bloodscent показывает процент крови противника (или процент кровоизлияния в PvE) красным числом, а процент Blood Poisoning розовым."],"stats":""},"blood-bag":{"description":"Вы получаете дополнительную кровь за нокаут врага.","info":[],"stats":""},"blood-transfusion":{"description":"Успешная критическая атака под негативным статус-эффектом переносит этот эффект на цель и восстанавливает небольшую часть вашей шкалы крови. (Перезарядка 20 секунд)","info":[],"stats":""},"crimson-fountain":{"description":"Пробитие блока или Flourish против врага теперь проливает под ним лужу крови. Мантры крови, применённые в лужах крови, стоят меньше крови.","info":[],"stats":""},"first-blood":{"description":"Ваша первая мантра крови в бою не тратит кровь и наносит дополнительный кровавый урон.","info":[],"stats":""},"hemorrhaging-blow":{"description":"Пробитие блока противника мантрой крови превращает его лечение в бою в урон на 8 секунд.","info":["Перезарядка 55 секунд, отсчёт начинается с пробития блока.","Лечение превращается в урон 1:1: 20 лечения = 20 урона.","Работает на любое (непассивное) лечение: можно пробить блок, а затем использовать то, что вылечило бы противника, и нанести урон. Не работает на Health Regen Potions и другие виды пассивного лечения.","Работает с Mindsoothe, колоколом Blood Scourge, Revitalizing Hair Spray у Fadetrimmer и т. д."],"stats":""},"just-a-taste":{"description":"Первая мантра Bloodrend, попавшая по цели в бою, имеет повышенное кровопускание.","info":["Сейчас не работает."],"stats":""},"open-wound":{"description":"Пробитие блока делает врагов более уязвимыми к потере крови от мантр Bloodrend.","info":[],"stats":""},"rush-hour":{"description":"Ударьте себя ножом, чтобы стать сильнее, быстрее и наносить больше урона по шкале крови.","info":["Даёт инструмент Rush Hour. Его можно отключить в любой момент, использовав инструмент повторно.","Тратит 4,5 здоровья и 2% крови в секунду.","Поскольку это тратит ваше здоровье, а не наносит урон, на него не действуют источники снижения урона (если не указано явно), он игнорирует Temporary Health и не активирует условия «при уроне».","Deepscorn Casque и талант Enhanced Flow единственные два эффекта в игре, которые могут снизить трату здоровья от Rush Hour.","Даёт бонус к урону 15%, ограниченный потолком модификаторов урона.","Увеличивает потерю крови на +35% (аддитивно).","Даёт ускорение (Speed Boost) 30%. Это учитывается талантами, зависящими от ускорения.","Восстанавливает 5% крови при нанесении урона (перезарядка 0,35 с). Урон от горения не активирует этот эффект.","Если у вас есть талант Enhanced Flow, обычные атаки во время Rush Hour дают Temporary Health в размере 30% масштабированного урона оружия.","Активный Rush Hour удваивает длительность статус-эффекта Torture Mastery.","Падение в ragdoll автоматически отменяет Rush Hour. (Brick Wall не проверен.)"],"stats":""},"sanguine-siphon":{"description":"Критическая атака, нанесённая в луже крови, поглощает эту лужу и усиливает вашу следующую мантру крови.","info":["Усиливает урон следующей мантры на 25% при срабатывании, о чём говорит кровь, текущая из ваших рук.","Эффект длится 15 секунд, затем исчезает."],"stats":""},"blood-and-iron":{"description":"Вытягивание стержней из противника теперь восстанавливает равное количество крови.","info":[],"stats":""},"brain-death":{"description":"У врагов, которые уже задыхаются (suffocated), при попадании мантры Bloodrend увеличивается длительность удушья.","info":["При срабатывании накладывает новый стак удушья на 2,5 с."],"stats":""},"cold-blooded":{"description":"Охлаждённые (Chilled) враги пассивно накапливают отравление кровью, а при взрыве кристаллов накладывается отравление кровью. (НЕ СУММИРУЕТСЯ)","info":["Перезарядка 0,5 с.","Накладывает 25% отравления кровью при взрыве кристаллов.","Талант не срабатывает на взрывы кристаллов от пробития блока цели или Temperature Shock. Все взрывы кристаллов должны вызываться наложением достаточного количества кристаллов или Golden Age, чтобы талант сработал."],"stats":""},"electrolyte":{"description":"Попадание мантрами Bloodrend при наличии временного здоровья накладывает Shocked и убирает часть временного здоровья.","info":["Вместо этого накладывает Surge Rod, если у вас есть Surge Path: Unstable Capacitor.","Тратит 4 временного здоровья за срабатывание."],"stats":""},"malevolent-sapper":{"description":"Чем больше отравление кровью у противника, тем больше Эфира крадут у него ваши мантры Shadowcast.","info":[],"stats":""},"scorchblood":{"description":"Пробитие блока противника мантрой Bloodrend вызывает кровавый взрыв: противник загорается, а его кровь отравляется.","info":["Наносит 16,5 урона по области при срабатывании.","Накладывает горение до того, как Scorched Peak проверяет, горит ли противник, то есть Scorched Peak сработает мгновенно, если вы пробили блок мантрой Bloodrend."],"stats":""},"bruiser-s-mixup":{"description":"Смена стиля кулачного боя (Fist Style) посреди боя временно заставляет ваши обычные атаки кулаками накладывать кровотечение.","info":["Длится 4 секунды.","Срабатывает по нажатию Y (работает, даже если у вас только один стиль кулачного боя).","Между сменами стиля перезарядка 8 секунд.","Талант не работает с Jus Karita."],"stats":""},"brazen-blow":{"description":"Атака по врагу, замедленному вашей секирой (Greataxe), даёт вам временную гиперброню (Hyperarmor).","info":["Гиперброня длится 1 секунду. Перезарядка 20 секунд.","Срабатывает только на атаки оружием.","Не срабатывает на аперкот."],"stats":""},"heavy-fatigue":{"description":"Удар по врагу, замедленному вашей секирой, временно уменьшает дальность его переката, а PvE-врагам на несколько секунд накладывает Sluggish.","info":["Снижает дальность переката противника на 25% на 2,5 с.","Статус Sluggish снижает урон поражённых целей на 15%.","Не срабатывает на аперкот."],"stats":""},"impairing-blow":{"description":"Обычные атаки слегка замедляют врага на 2 секунды. Атаки на бегу замедляют врага на 3 секунды. Вы получаете +20% урона по Стойке (Posture) против врагов с бонусами к скорости.","info":["Не срабатывает на аперкот.","Снижает скорость противника на фиксированное значение 5."],"stats":""},"rending-impact":{"description":"Пробитие блока врага сбивает его с ног (Knockdown).","info":["Срабатывает только на пробитие блока атаками оружием.","Сбивание с ног длится 1,2 секунды.","Стандартное оглушение от пробития блока 1,05 с, поэтому это фактически увеличивает время оглушения после пробития блока на 0,15 с.","Перезарядка срабатывания 30 секунд."],"stats":""},"dancing-guard":{"description":"Парирование противника, а затем быстрое парирование другого врага накладывает замедление на 7 с.","info":["Длительность Dancing Guard уменьшается на 0,086 с за каждое очко Телосложения ниже требования; минимум 4,86 с при 30 Телосложения."],"stats":""},"defensive-reprisal":{"description":"Если вас бьют Flourish-атакой, вы получаете 10% сопротивления Стойке (Posture) на 20 с.","info":["Длительность Defensive Reprisal уменьшается на 0,177 с за каждое очко Телосложения ниже требования; минимум 15,55 с при 40 Телосложения."],"stats":""},"down-to-your-level":{"description":"Пока на вас есть штраф к скорости, ваши обычные атаки замедляют врагов на 5 с.","info":["Длительность Down to your Level уменьшается на 0,05 с за каждое очко Телосложения ниже 60; минимум 3,75 с при 35 Телосложения.","Замедление срабатывает только на M1 и критические атаки с тегом M1.","Срабатывает от Entaglement, оглушения (Daze), охлаждения (Chill) и большинства других эффектов, замедляющих вас.","Не срабатывает от Grand Fisher Plate и Wormwarder Lantern, хотя они снижают вашу скорость передвижения."],"stats":""},"knuckle-guard":{"description":"Удары по оглушённым (Dazed) врагам дают вам 10% сопротивления Стойке (Posture) на 15 с.","info":["Длительность Knuckle Guard уменьшается на 0,1 с за каждое очко Телосложения и Силы ниже требований; минимально возможная длительность 10,4 с при 30 Телосложения и 4 Силы, хотя это не очень реалистично."],"stats":""},"evasive-expert":{"description":"Ускорение от уклонения увеличивается.","info":["Увеличивает ускорение от Swift Rebound с 30% до 50%."],"stats":"+1 к пассивной Ловкости"},"risky-moves":{"description":"Когда вы успешно уклоняетесь, вы автоматически уклоняетесь и от следующей атаки.","info":["Пока эффект активен, игрока покрывает синяя подсветка.","Визуальный эффект может не совпадать с длительностью.","Атака отменяет эффект досрочно.","Приоритетнее блока, поэтому можно «автоуклоняться» одновременно с блоком.","Перезарядка 20 секунд."],"stats":"+1 к пассивной Ловкости"},"swift-rebound":{"description":"Вы двигаетесь быстрее после успешного уклонения от атаки.","info":["Даёт ускорение 30% на 2 с."],"stats":"+1 к пассивной Ловкости"},"champion-s-regalia":{"description":"Flourish против противника даёт вам +50% урона по Стойке (Posture) обычными атаками на 10 секунд.","info":["Обозначается золотым контуром вокруг персонажа.","Не работает на нечеловекоподобных NPC."],"stats":""},"defiance":{"description":"Негативные статус-эффекты вдвое слабее, когда у вас меньше 35% здоровья.","info":["Эффективность Defiance снижается, если вы не выполняете требование таланта по Силе воли.","Сейчас Defiance вдвое уменьшает только:","урон от горения (Burn) Flamecharm","длительность охлаждения (Chill) и стаки кристаллов Frostdraw","длительность одышки (Winded) и удушья Galebreathe","стаки Surge Thundercall","длительность Sightless Still Shadowcast","отравление кровью (Blood Poisoning)","накопление увядания (Wither)","длительность Ring of Pestilence","силу зелий","время без сознания (уменьшается на 50% мультипликативно после остальных модификаторов)"],"stats":""},"underdog":{"description":"Вы наносите на 2,5% больше урона тем, у кого здоровья больше, чем у вас (растёт до 4% при 60 Силы воли). Кроме того, вы наносите на 10% больше урона физически более крупным противникам.","info":["Урон Underdog по врагам с большим здоровьем растёт с вложением в Силу воли.","Underdog даёт бонус 2,5% к урону при 20 Силы воли и увеличивает его на 0,0375% за каждое очко Силы воли выше 20; максимум 4% при 60 Силы воли.","При выполнении требований Underdog даёт бонус 2,875% к урону.","«Больше здоровья» означает текущее здоровье.","«Более крупные враги» это NPC, которые действительно большого размера (например, работает на Megalodaunts, но не на Threshers).","Крупных врагов нельзя схватить приёмами захвата.","Объединён со старым талантом Giantslayer."],"stats":""},"chaotic-charm":{"description":"Очаровывает ближайших врагов, когда вас атакуют при низком здоровье. Очарованные враги наносят больше урона всем, кроме вас, и меньше урона вам.","info":["Срабатывает при получении урона, когда у вас не более 25% максимального здоровья.","Накладывает уникальный статус-эффект Chaotic Charm на 15 секунд, отдельный от очарования (Charm) в целом. Именно он даёт дополнительное снижение урона и повышенный урон по всем, кроме вас. Длительность этого эффекта нельзя сократить с помощью Disbelief.","Дополнительное снижение урона от Chaotic Charm растёт с вложением в Харизму: 0,15% снижения урона за каждое очко Харизмы.","Это снижение урона перемножается с Charm, так как это отдельные статус-эффекты.","Наложение Charm может активировать Narcissist.","При каждом срабатывании наносит 0,1 безтипового урона по области и накладывает на цели боевую метку (Combat Tag) и Charm. Перезарядка 0,25 с.","Можно заблокировать: тогда урон и срабатывание Charm предотвращаются.","Безтиповой урон по себе не активирует Chaotic Charm, но, например, Flame Within активирует."],"stats":""},"charismatic-cast":{"description":"Попадание мантрой по врагу накладывает Charmed. Союзники приходят в себя после нокаута вдвое быстрее, если вы их очаровали.","info":["Это очарование длится 10 с.","Цели, которых вы очаровали, наносят вам на 10% меньше урона.","Если накладывать Charm на уже очарованную цель и общая длительность нового Charm больше оставшейся длительности текущего, исходный Charm заменяется. Иначе ничего не происходит. Если вы хотите извлекать пользу из Charismatic Cast в ганках и командных боях, настоятельно рекомендуется Lasting Charisma."],"stats":""},"lasting-charisma":{"description":"Враги, очарованные вашими мантрами, остаются очарованными дольше.","info":["Lasting Charisma увеличивает длительность Charm от Charismatic Cast с 10 до 20 с.","Если вы не выполняете требование таланта по вложениям, дополнительная длительность Charm уменьшается на 0,166 с за каждое очко Харизмы ниже 55; минимум 15,83 с Charm при 30 Харизмы."],"stats":""},"tough-love":{"description":"Вы наносите на 10% больше урона врагам, очарованным вами. Для мантр бонус +5%. Если вас бьёт кто-то с тем же Аспектом (Aspect) или Клятвой (Oath), что и у вас, на него ненадолго накладывается Charmed.","info":["Очаровывает на 2 секунды, перезарядка 1 секунда.","Если вас атакуют во время перезарядки, таймер сбрасывается, и нужно ждать ещё секунду, чтобы Charm от Tough Love снова сработал.","Бонус к урону действует на все источники Charm, а не только на Tough Love.","Charm срабатывает и при блоке, парировании и уклонении.","Бонус к урону применяется, только если ваш Charm наложен на цель. Из-за особенностей Charm настоятельно рекомендуется большая длительность Charm от Lasting Charisma, если вы хотите, чтобы талант работал в массовых ганках.","Вместо того чтобы ослаблять очарованных игроков и заставлять их получать больше урона, талант даёт бонус при ударе по очарованному вами противнику: эта атака получает бонус к урону. Поэтому на Tough Love действует потолок модификаторов урона."],"stats":""},"freezing-wight":{"description":"Ваш Haunted Gale теперь накладывает Chilled.","info":["Также работает с Apparitions у Specter Path, окрашивая их в светло-голубой.","Накладывает 7 секунд охлаждения (Chill) или 1 кристалл.","Меняет тип урона призраков Haunted Gale и Apparitions Specter с чистого Galebreathe на Galebreathe и Frostdraw, из-за чего их проще сопротивляться, но они могут активировать эффекты, требующие типа урона Frostdraw (например, Flashboil)."],"stats":""},"destructive-recovery":{"description":"Враги восстанавливают на 20% меньше Стойки (Posture) при парировании.","info":["Не путайте с Devastating Recovery, талантом оружия Zweihander."],"stats":"+1 к Стойке"},"heavy-hitter":{"description":"Ваш урон по Стойке (Posture) увеличивается на 5%.","info":[],"stats":""},"unstoppable-force":{"description":"Вы получаете на 15% меньше урона по Стойке (Posture), когда вас парируют.","info":[],"stats":"+1 к Стойке"},"grand-support":{"description":"Все, кого вы усиливаете с помощью Reinforce, слегка лечатся. Вы немного лечитесь, если лечите других.","info":["Лечит других на 3% от максимального здоровья.","Лечит вас на 2% от максимального здоровья плюс ещё 1% за каждого дополнительно вылеченного. Срабатывает, только если вы усилили через Reinforce хотя бы одного союзника.","Срабатывает только на союзников.","Примечание: хотя этот талант требует 40 Телосложения, мантра Reinforce требует 50."],"stats":""},"lord-s-tithe":{"description":"У всех, кого вы усилили через Reinforce, пока действует Reinforce, высасывается Эфир. Высасывание растёт с вашим Shadowcast. У PvE-противников вы высасываете и здоровье.","info":["Пока эффект активен, жертвы могут удерживать блок, чтобы остановить утечку Эфира.","Lord's Tithe прекращает действовать на жертвах, когда их Эфир опускается ниже 5%.","Получение удара или блок атаки полностью отменяет эффект.","Примечание: хотя этот талант требует 40 Телосложения, мантра Reinforce требует 50."],"stats":""},"pressure-detonation":{"description":"Пробитие блока противника мантрой Shadow создаёт небольшой вакуум, который душит попавших в него и крадёт их Темп (Tempo).","info":["Если у игрока есть талант Apparitions, удушье может активировать Apparitions."],"stats":""},"decisive-blow":{"description":"Критическая атака по врагу сразу после его уклонения (или в любой момент против мобов) теперь активирует Knife's Journey. Срабатывания Knife's Journey наносят двойной урон броне.","info":["Пока эффект активен, на вашем оружии появляется красный след. Он будет и у не-кинжалов, но эффекта не даст без нужного таланта.","Совместим с другим талантом, хотя формально не является талантом кинжала."],"stats":""},"finishing-touch":{"description":"Мгновенно казните врагов, добитых критической атакой вашего кинжала.","info":["Для срабатывания таланта ваша критическая атака должна отправить противника в бессознательное состояние (Unconscious)."],"stats":""},"knife-s-journey":{"description":"Прерывание подготовки мантры врага вашими обычными атаками теперь наносит на 15% больше урона.","info":["После срабатывания на цели появляется красная частица.","Хотя в описании таланта это не сказано, у кинжалов в PvE есть 15% шанс критически попасть обычной атакой, нанося 5-кратный урон. Перезарядка 15 секунд.","Не работает на оружии, не являющемся кинжалом, через другой талант. Кроме того, критическая атака Moppet не может критически попасть.","Критические попадания не активируют таланты «при критической атаке»."],"stats":""},"successive-throw":{"description":"Когда вы успешно применяете Flourish против врага, после этого вы бросаете кинжал.","info":["Если после Flourish курсор не на враге, кинжал полетит в ближайшего к курсору врага. Если курсор на другом игроке, а не на том, кого вы применили Flourish, кинжал полетит в него.","Снаряд вылетает с задержкой 1,5 секунды.","Если цель слишком близко, брошенный кинжал будет невидим; в остальных случаях снаряд выглядит похоже на снаряд Ice Daggers.","Наносит 5 урона при срабатывании."],"stats":""},"chilling-flourish":{"description":"Когда вы применяете Flourish против врага, он оставляет за собой ледяной след в направлении, куда вы его отправили.","info":["Оставляет на земле 3-4 ледяных участка."],"stats":""},"condensation-drip":{"description":"Пассивно собирает конденсат из воздуха, сильно уменьшая вашу жажду.","info":["Замедляет расход жажды примерно в 3 раза."],"stats":""},"cool-head":{"description":"Если вас подожгли, пока вы на льду, огонь тут же гаснет, и вы получаете статус Cool Head на 30 с. Пока действует Cool Head, вас нельзя поджечь.","info":["Перезарядка 15 секунд, начинается с окончания эффекта.","Пока эффект активен, игрок дышит холодным воздухом."],"stats":""},"fragile-freeze":{"description":"Ваши обычные и критические атаки теперь накладывают Frozen на охлаждённых (Chilled) противников при пробитии блока.","info":["Пробитие блока охлаждённого противника атакой оружием заключает его в лёд, лишая возможности двигаться, парировать, блокировать и уклоняться на короткое время.","Получение урона из любого источника (включая урон со временем) досрочно прерывает заморозку.","Чтобы быстрее выбраться из заморозки, можно спамить парирование, пробел или уклонение."],"stats":""},"preceding-chill":{"description":"Враги, пораженные в последние мгновения вашего ледяного луча, замораживаются.","info":["Если у игрока есть Crystallization, этот талант не замораживает, а вызывает взрыв кристаллов.","Чтобы быстрее выбраться изо льда, можно спамить парирование, пробел или уклонение."],"stats":""},"spike-traps":{"description":"Нажмите парирование во время подготовки Ice Spikes, чтобы создать ловушки вокруг себя вместо появления шипа в обычном месте.","info":["Активирует шип, когда на него наступают.","Небольшие синие прозрачные «ловушки» обозначают хитбоксы и расставляются случайно вокруг игрока.","Можно накладывать несколько раз, получая очень много ловушек в одном месте.","Увеличивает перезарядку Ice Spike на 5 с, до 20 с в сумме.","Spike Traps больше нельзя получить. У игроков, у которых он уже есть, активация поставит только 1 ловушку, сколько бы Cloud/Stratus Stones ни было у мантры."],"stats":""},"golden-age":{"description":"Ваш Iron Pull теперь взрывает кристаллы и перегружает Surge.","info":["Кристаллы не всегда взрываются при притягивании (баг)."],"stats":""},"blood-thirsty":{"description":"Вы получаете ускорение после того, как нанесли противнику сильную кровопотерю.","info":["«Сильная кровопотеря» означает около одной полоски крови.","«Очень короткая длительность» (по описанию ютубера Agamatsu)."],"stats":"+1 к пассивной Ловкости"},"in-a-hurry":{"description":"Вы быстрее хватаете, а скорость передвижения увеличивается.","info":["Сокращает время казни на 0,5 секунды (на 16,67% быстрее)."],"stats":"+1 к пассивной Ловкости"},"muffled-screams":{"description":"Вы приглушаете крики о помощи тех, кого казните: расстояние, на котором их союзники слышат крик и приходят на помощь, сокращается, а эффективность талантов, замедляющих ваши казни, снижается.","info":["У NPC сокращается дальность агро от казни их союзников поблизости.","Stay of Execution больше не влияет на скорость вашего захвата."],"stats":"+1 к пассивной Ловкости"},"blighted-song":{"description":"Присоединение ваших Shadow Chains к врагам лишает и вас, и врага возможности применять мантры. Пока это действует, вы получаете сниженный урон от врагов.","info":["Даёт 20% снижения урона от атак существ, которые не являются заклинателем или тем, на кого действует Blighted Song."],"stats":""},"dark-god":{"description":"Если мантра Shadowcast должна опустить Эфир противника до 0, она вместо этого забирает его Темп (Tempo) и увеличивает ваш. Мантры Shadowcast теперь повышают ваш Темп, если ваш Эфир полон.","info":[],"stats":""},"dark-hours":{"description":"Ваши мантры Shadowcast наносят на 15% больше урона ночью и в областях, куда не достаёт Солнце.","info":["Ночной цикл идёт с XX:50 до XX:10 по реальному времени.","В Глубинах всегда активно."],"stats":""},"dark-replenishment":{"description":"Нокаут врага в бою восстанавливает часть вашего Эфира.","info":[],"stats":""},"dark-rift":{"description":"При успешном уклонении вы входите в состояние разлома, в котором вас нельзя ранить до конца его действия. Можно прервать досрочно атакой.","info":["Блок, парирование, уклонение или скольжение также отменяют эффект.","Во время эффекта нельзя использовать мантры.","Пока Dark Rift активен, вы парите в тёмном контуре.","Способность длится 1,8 секунды и уходит на перезарядку 20 секунд при активации."],"stats":""},"dark-synergy":{"description":"Окутывает врага тенями, когда вы применяете против него Flourish.","info":["Наносит 5 урона Shadowcast при срабатывании.","Не крадёт и не останавливает восстановление Эфира."],"stats":""},"dark-waltz":{"description":"Каждый раз, когда вы пробиваете блок противника лёгкой атакой или критической атакой, вы крадёте половину его текущего Темпа (Tempo). Также накладывает Ether Sunder на PvE-противников.","info":["Статус Ether Sunder даёт вам 30% снижения урона от стихийных атак поражённых врагов."],"stats":""},"night-terror":{"description":"Ваши лёгкие атаки теперь активируют Fear the Dark.","info":["Вопреки описанию, талант накладывает статус Fear the Dark на 1 секунду без перезарядки (им не нужно убегать от вас).","Срабатывание Fear the Dark от Night Terror полностью обходит Absolute Radiance у Dawnwalker.","Также срабатывает на критические атаки оружием. Критическая атака не обязана иметь тег M1."],"stats":""},"overwhelming-drain":{"description":"Если ваш Shadow Eruption поражает нескольких врагов, они оглушаются (Dazed) на 0,7 с.","info":[],"stats":""},"shadow-overflow":{"description":"Лишний Эфир, украденный мантрами, выплёскивается тёмной энергией, нанося урон и поглощая Эфир у находящихся рядом.","info":["Перезарядка 4 секунды.","Наносит 5 урона Shadowcast вокруг вас по небольшой области от цели, в которую вы попали."],"stats":""},"blackhole":{"description":"Ваша сингулярность затягивает всех поблизости.","info":["Затягивает всех поблизости в области среднего размера к ближайшему противнику, по которому вы попали мантрой Shadow."],"stats":""},"energy-siphon":{"description":"Ваша сингулярность теперь вытягивает Эфир и из дополнительных игроков, попавших под Blackhole.","info":["Забирает около 15 Эфира у поражённых противников при срабатывании."],"stats":""},"frozen-web":{"description":"Критическая атака Static Link по противнику накладывает Chilled.","info":["Накладывает охлаждение (Chill) на 7 секунд и Bottom Freeze. Для этого эффекта не нужен талант Bottom Freeze.","При использовании Crystallization Path создаются визуальные эффекты и звуки кристаллов, но сами кристаллы не накладываются.","Перезарядка 3 секунды."],"stats":""},"concussion":{"description":"У врагов, которых вы отбросили Flourish-атакой в стену, на короткое время меняется зрение, и они оглушены дольше обычного. PvE-враги после Flourish получают Stagger на несколько секунд.","info":["Статус Stagger заставляет противника получать на 33% больше урона по Стойке (Posture)."],"stats":""},"concussive-force":{"description":"Враги, которых вы нокаутировали, остаются поверженными дольше обычного.","info":["Враги остаются без сознания (Unconscious) 15 секунд вместо 10."],"stats":""},"precise-swing":{"description":"После попадания критической атакой ваша следующая обычная атака получает 25% урона сквозь блок противника (chip).","info":["Если ваша критическая атака попала, была парирована или заблокирована, вы получаете статус Precise Swing на 30 секунд.","Статус Precise Swing расходуется, если вы бьёте M1 в чей-то блок, попадаете M1 или ваш M1 парируют.","Если M1 промахивается или в него уклоняются, статус не расходуется.","Поскольку статус накладывается на вас, а не на противника, вы можете попасть критической атакой по игроку A, затем ударить в блок игрока B и всё равно нанести урон сквозь блок.","Precise Swing складывается с chip оружия, а chip выше 100% увеличивает наносимый урон."],"stats":"+1 к пассивной Ловкости"},"spine-cutter":{"description":"Удар врага в спину после отмены переката запускает вторую атаку, наносящую чистый урон вашего оружия.","info":["Перезарядка 5 секунд на каждого врага. Индикатор перезарядки может создавать впечатление, что она на тип врага, но это не так.","Наносит половину масштабированного урона вашего оружия без PEN.","На срабатывание даётся одна секунда после отмены переката.","Может срабатывать от некоторых физических мантр и критических атак с тегом M1.","Нельзя парировать.","Игроки с активными Turtle Shell или Arc Module: Guard неуязвимы для Spine Cutter."],"stats":"+2 к пассивной Ловкости"},"steady-nerves":{"description":"Вы пританцовываете с ноги на ногу: успешные уклонения восстанавливают Стойку (Posture).","info":["Восстанавливает 2 единицы Стойки при успешном уклонении."],"stats":"+2 к пассивной Ловкости"},"strong-hold":{"description":"Когда у вас больше половины здоровья и вы держите оружие двумя руками, получаемый урон по Стойке (Posture) снижается на 5%.","info":[],"stats":"+1 к пассивной Ловкости"},"strong-stern":{"description":"Длительность оглушения (Dazed) от ударов о стену сокращается вдвое. Также слегка сокращается время оглушения от пробития блока PvE-врагами.","info":[],"stats":"+5 к грузоподъёмности (Carry Load)"},"tap-dancer":{"description":"Уклонение сразу после отмены переката больше не увеличивает перезарядку уклонения.","info":["Убирает дополнительные полсекунды перезарядки, добавляемые к перекату после его отмены."],"stats":"+1 к пассивной Ловкости"},"concussive-flash":{"description":"Ваш ослепляющий свет теперь контузит врагов.","info":["Ослеплённые Flame Blind получают оглушение (Dazed) на 2 секунды."],"stats":""},"charged-return":{"description":"Под стихийным статус-эффектом ваши обычные и критические атаки наносят на 10% больше урона.","info":["Срабатывает при: горении (Burn), охлаждении (Chill), шоке (Shock), Fear the Dark (от талантов Fear the Dark и Night Terror), одышке (Winded), Fatigued Swings (от Mocking Favor) и удушье (Suffocation).","Также срабатывает, если эти статус-эффекты наложены на себя, например через Flame Within или Agitating Spark."],"stats":""},"nullifying-clarity":{"description":"Вы наносите на 10% больше урона врагам со стихийными статус-эффектами, но при ударе статус снимается.","info":["Срабатывает, если вы попали M1 по цели с одним из статус-эффектов: горение, охлаждение, шок, одышка, удушье и Fear the Dark (от Fear the Dark и Night Terror).","Применяется до Immolation в порядке срабатывания, что позволяет заново наложить горение тем же ударом.","Накладывает иммунитет к горению (Burn Immunity) при снятии горения.","Не работает с критическими атаками."],"stats":""},"cornered-fool":{"description":"Пробитие блока очарованного (Charmed) противника накладывает Taunted на 5 с, заставляя его получать и наносить больше урона.","info":["Перезарядка 15 секунд.","Вопреки описанию, накладывает провокацию (Taunt) на 6 секунд.","Каждое очко Харизмы ниже 85 уменьшает длительность этой провокации на 0,035 с; минимум 5,12 с при 60 Харизмы.","Бонус к урону от провокации применяется и к атаке, которая пробила блок.","Талант продолжает работать как обычно, даже если у вас больше нет мантры Taunt."],"stats":""},"give-and-take":{"description":"Вы наносите меньше урона соратникам и получаете меньше урона от соратников.","info":["Вы получаете на 20% меньше урона от союзников и наносите им на 20% меньше. Не действует на урон по себе.","Врождённый талант Loyalty у Аспекта Canor имеет похожий эффект, и они суммируются, давая 48% снижения урона в сумме.","Участники вашей гильдии, ваши друзья из Roblox, игроки в Vow of Mastery или в Vow of Allegiance с вами получают от вас меньше урона и наносят вам меньше."],"stats":""},"off-your-game":{"description":"Теперь вы замедляете провоцированных (Taunted) врагов, когда бьёте их.","info":[],"stats":""},"robber-baron":{"description":"Вдвое уменьшает количество предметов, которые вы роняете при смерти. Вы больше не теряете Notes при смерти.","info":["Потеря предметов при смерти снижается с 50% до 25%."],"stats":""},"ether-absorption":{"description":"Вы получаете Эфир обратно, когда получаете урон от мантр.","info":[],"stats":""},"eureka":{"description":"Вы получаете стак Inspiration каждый раз, когда попадаете мантрой или парируете мантру. Промах мантрой убирает стак Inspiration.","info":["При 3 стаках вы получаете бонус Inspired на 30 секунд или до применения мантры. Inspired увеличивает урон вашей следующей мантры на 10%.","Если вы получили Inspired парированием мантр, статус Inspired действует 30 секунд.","Если вы получили Inspired попаданием мантр, статус сразу расходуется на увеличение урона мантры, которой вы его получили.","Дополнительные стаки не даются за многократные попадания и кадры автопарирования.","Стаки Inspiration не спадают, даже если вы целиком промахиваетесь мантрами.","Этот талант объединён со старым талантом «Ether Conduit»."],"stats":""},"mantra-permanence":{"description":"Нокаут врага мантрой возвращает стоимость этой мантры.","info":[],"stats":""},"behind-you":{"description":"Обычная атака в спину врага после финта мантрой наносит эфирный удар с дополнительным уроном, зависящим от того, сколько Эфира у вас осталось.","info":["Наносит отдельный экземпляр физического урона, который можно парировать; урон растёт с текущим процентом Эфира и составляет 30 при полном Эфире.","При полном Эфире и сниженных вложениях (shrined down) наносит 15 урона независимо от вложений.","У Behind You нет перезарядки.","Может срабатывать по катящимся игрокам, если вы попали в спину.","Можно активировать Behind You и другой талант одновременно, но окно срабатывания очень узкое. Порядок зависит от того, что использовано первым.","Может срабатывать от критических атак с тегом M1.","После финта мантрой даётся окно срабатывания 3 секунды."],"stats":""},"keen-recovery":{"description":"Обычная атака после финта мантрой восстанавливает стоимость Эфира финтованной мантры.","info":["Количество восстановленного Эфира растёт с вложением в Интеллект и превышает стоимость мантры, если у вас больше 55 Интеллекта."],"stats":""},"unwavering-focus":{"description":"Когда ваши мантры парируют, вы получаете меньше урона по Стойке (растёт с Интеллектом).","info":["Даёт 0,3% сопротивления Стойке (Posture) за каждое очко Интеллекта; максимум +21% при 70 Интеллекта."],"stats":""},"reverse-leech":{"description":"Каждый раз, когда срабатывает Behind You, вы также крадёте Эфир у противника.","info":["Behind You срабатывает при обычной атаке в спину врага после финта мантрой."],"stats":""},"burnout":{"description":"Поджигание врагов снижает их урон на 4% за каждый стак Black Blood, максимум до 12%.","info":[],"stats":""},"critical-mass":{"description":"Критическая атака по врагу с Black Blood поджигает его розовым огнём.","info":["Накладывает Sanguine Burn и вызывает срабатывание поджога."],"stats":""},"exotherm-path-sanguine-blaze":{"description":"Ваша кровь густая и маслянистая, она липнет ко всему, чего касается. Мантры крови покрывают врагов Black Blood: она замедляет их и подавляет лечение, до 3 стаков. Коснитесь её пламенем, и она взорвётся. Ваш огонь горит обжигающе-розовым.","info":["Окрашивает ваши мантры Flamecharm, статус-эффекты, связанные зачарования и оружие в розовый. Мантры Bloodrend и лужи крови становятся чёрными.","Мантры Bloodrend накладывают стаки Black Blood помимо прежних эффектов Blood Poison и кровопускания. Black Blood накладывает замедление и анти-лечение (Anti-Heal).","Нанесение урона Flamecharm любым источником, кроме Burn, цели с Black Blood заставляет кровь воспламениться и взорваться, нанося урон и отбрасывание и расходуя все стаки Black Blood и горение, вызвавшее срабатывание."],"stats":""},"exothermic-finish":{"description":"Поджог врага с Black Blood теперь применяет к нему Flourish вместо отбрасывания, накладывая все таланты Flourish.","info":[],"stats":""},"pressure-bleed":{"description":"Ваши Vent становятся розовыми и разбрызгивают взрывоопасные лужи Black Blood, поджигающие врагов.","info":["Ваш Vent разбрызгивает несколько небольших луж Black Blood в случайных местах поблизости на полу. Через короткую задержку они становятся розовыми и взрываются, накладывая горение на попавших."],"stats":""},"meteor-impact":{"description":"Воздушные приёмы, в которые вы попали, продолжаются сокрушительным ударом сверху. Это возможно и тогда, когда воздушный приём попал по вам.","info":["Наносит 10 единиц урона сверх масштабированного урона вашего оружия, целиком как урон Flamecharm.","Урон Meteor Impact можно усилить модификаторами урона, но он не зависит от вложения во Flamecharm.","Meteor Impact используется лёгкой атакой после мантр, после которых и игрок, и жертва зависают в воздухе, в том числе Rising Flame, Flame Leap, Rising Frost, Rising Wind, Lightning Impact, Flashfire Sweep и Galebreathe Blade of Saints у Saintsworn. Возможно, есть и другие, но они ещё не описаны.","Rising Thunder тоже может его активировать, но только если первоначальный захват пробивает блок, что очень маловероятно.","Некоторые мантры, хотя и оставляют обоих игроков в воздухе, не могут активировать Meteor Impact, например Celestial Assault или Skyshatter Kick (Round Spark)."],"stats":""},"phoenix-impact":{"description":"Если вы применяете Meteor Slam к противнику, пока горите сами, вы восстанавливаете немного здоровья и Эфира.","info":["Лечит 4% максимального здоровья и восстанавливает 20 Эфира."],"stats":""},"fishman":{"description":"Когда ваша кровь выше 50%, вы не тонете, потеряв сознание в воде. Вы получаете дополнительное лечение за отправку других в бессознательное состояние в воде.","info":["Старый талант Scuba Drowner был объединён с этим."],"stats":""},"dancing-steps":{"description":"Мантры огня теперь двигают вас в направлении, куда вы смотрите.","info":["Применение мантры Flamecharm даёт умеренный толчок по горизонтали в направлении взгляда персонажа. Срабатывает даже при финте мантрой.","Очень полезно, чтобы сократить дистанцию и вступить в ближний бой.","Вопреки описанию другого таланта, этот талант не даёт ускорения.","Перезарядка 5 секунд. Её можно сократить до 1 секунды, надев наряд Cindergarb Outfit."],"stats":""},"graceful-steps":{"description":"Ваши Dancing Steps теперь дают более быстрое ускорение.","info":["Если у вас не хватает Эфира на мантру, ускорение всё равно срабатывает. Также срабатывает, если мантра финтована.","Ускорение длится очень недолго; чтобы извлечь выгоду из этого таланта, рекомендуется оружие с быстрым замахом и финты мантрами.","Не увеличивает дальность перемещения от Dancing Steps.","Перезарядка 5 секунд. Её можно сократить до 1 секунды, надев наряд Cindergarb Outfit."],"stats":""},"the-final-act":{"description":"Попадание мантрой огня сразу после Flourish против противника заставляет его взорваться.","info":["Перезарядки нет.","Наносит 5 урона Flamecharm.","Не срабатывает на существ в бессознательном состоянии.","Может срабатывать с Mecha Gatling."],"stats":""},"cauterized-wounds":{"description":"Потеря крови из всех источников снижается.","info":["Вопреки описанию, талант влияет только на потерю крови от прямого получения урона. Эффекты кровопускания (например, применение мантр Bloodrend или попадание ими, зелья потери крови, штраф Corrupt Resonance с потерей крови) этим талантом не затрагиваются.","Эффективность таланта снижается, если вы используете зачарование Curse of the No Life King.","Суммируется с другими талантами, снижающими потерю крови."],"stats":"+1 к пассивной Ловкости"},"flamewalker":{"description":"Пока активен Warding Radiance, при скольжении вы оставляете за собой следы пламени.","info":["Когда цели касаются огненного следа, они загораются. Если у вас есть Eruption Path, вместо этого произойдёт Eruption."],"stats":"+1 к пассивной Ловкости"},"hell-s-partisan":{"description":"После попадания огненным кинжалом по противнику ваш следующий удар по нему пронзит его божественным копьём сверху.","info":["«Огненный кинжал» это мантра Fire Forge.","Другой талант позволяет активировать Hell's Partisan любой мантрой Flamecharm, а не только Fire Forge.","Наносит 5 урона Flamecharm.","Перезарядка 5 секунд.","Можно парировать, но нельзя заблокировать или уклониться из-за оглушения от попадания."],"stats":"+4 к Рассудку"},"warding-radiance":{"description":"Каждая мантра огня накладывает один стак нимба. При 3 стаках появляется нимб, позволяющий скользить дальше. Пока он активен, Hell's Partisan также срабатывает пассивно.","info":["Позволяет активировать Hell's Partisan мантрами Flamecharm, кроме Fire Forge, пока нимб активен.","Легко активируется попаданием многократной мантрой огня.","Перезарядки нет, длится 60 с, обновить нельзя."],"stats":"+1 к пассивной Ловкости"},"azure-flames":{"description":"Многие ваши пламена становятся синими, что говорит об их возросшей силе.","info":["Меняет цвет вашего Flamecharm на синий: ваши мантры огня, горение (Burn), Eruption, зачарование Blazing и легендарное оружие становятся синими.","Увеличивает урон от горения на 12,5%.","Увеличивает радиус и урон по Стойке (Posture) ваших Eruption.","Увеличивает время действия вашего Flame of Denial на 25%: с 25 секунд до 31,25.","Увеличивает пассивное лечение таланта Graceful Flame на 20%."],"stats":""},"unyielding-inferno":{"description":"Ваше пламя горит так же сильно даже в сильнейшую бурю.","info":["Убирает врождённый штраф к урону 10%, который во время дождя получают мантры Flamecharm, критическая атака First Light и Puppets у Twisted Puppets.","Не даёт вашему горению погаснуть под дождём."],"stats":""},"temperature-shock":{"description":"Ваши мантры огня теперь взрывают наложенные кристаллы.","info":["Попадание мантрой Flamecharm взрывает кристаллы, которые вы наложили.","Перезарядка 4 секунды."],"stats":""},"exoskeleton":{"description":"У вас есть слой укреплённой природной брони (Natural Armor), которая восстанавливается во время отдыха. Пока она активна, она сопротивляется 10% физического урона.","info":["Сопротивление Exoskeleton менее эффективно, если вы не выполняете его требование по Телосложению: теряется 0,125% сопротивления за каждое очко Телосложения ниже 40; минимум 6,875% сопротивления при 15 Телосложения.","Прочность Exoskeleton составляет 315 на 1 уровне мощности и растёт до 600 на 20 уровне.","Снижение урона от Vesperian's Chitin суммируется с Exoskeleton мультипликативно.","Если есть и Exoskeleton, и Chitin, прочность Exoskeleton имеет приоритет, к ней добавляется +200 прочности, итого 800 на 20 уровне мощности.","Природная броня восстанавливается во время отдыха у костра со скоростью 2,2% за 0,2 с, то есть 11% в секунду.","На природную броню действует PEN, но его эффективность снижается на 75%. (Например, если у кого-то 100% PEN, ваша природная броня будет сопротивляться 7,5% его урона вместо нуля.)","Природная броня теряет прочность при любой полученной атаке, даже если не сопротивляется ей.","Потеря природной брони зависит от масштабированного полученного урона и обычно не может быть увеличена, но может быть уменьшена снижением урона."],"stats":""},"to-the-finish":{"description":"Вы получаете на 10% меньше урона, когда здоровья меньше 30%.","info":["За каждое очко Телосложения ниже 50 To the Finish теряет 0,166% снижения урона; минимум 5,833% снижения урона при 25 Телосложения."],"stats":""},"glacial-mobility":{"description":"Применяйте во время прыжка из скольжения, чтобы выполнить атаку на бегу ледяными саблями.","info":["Вопреки описанию, талант активируется после прыжка из скольжения, а не во время него (можно также активировать во время скольжения без прыжка, это работает немного нестабильно)."],"stats":""},"cold-front":{"description":"Ваш Vent наполнен ледяным морозом.","info":["Vent создаёт на полу ледяной участок и накладывает охлаждение (Chill) на любого врага, которого он задел.","Увеличивает урон вашего Vent на 0,5% за каждое очко Frostdraw и меняет его тип урона на Frostdraw.","Это также относится к таланту Imperator's Fury, хотя его урон иначе не модифицируется."],"stats":""},"glacial-coasting":{"description":"Скольжение при активном Orbital Ice оставляет следы льда.","info":["Создаёт ледяные участки при скольжении, увеличивая скорость скольжения."],"stats":"+1 к пассивной Ловкости"},"orbital-ice":{"description":"Когда вы парируете, стоя на льду, автоматически образуется ледяное кольцо, дающее 15% физического сопротивления. Кольцо разрушается после получения определённого количества урона, зависящего от вашего Frostdraw.","info":["Прочность Orbital Ice равна «вложение во Frostdraw + 10».","Перезарядка 90 секунд. Она начинается в момент срабатывания Orbital Ice, а не когда оно разрушено.","Длится 50 секунд, если не разрушено.","Если у вас есть талант Refreeze из Icebringer's Vestments, любое умение, активирующее Bottom Freeze, сокращает перезарядку Orbital Ice на 20 секунд. Это срабатывает независимо от перезарядки Bottom Freeze."],"stats":""},"fulgurite-formation":{"description":"Когда ваши кристаллы взрываются, бьёт молния. Когда Surge перегружается на враге, ваши кристаллы накладываются на него дважды на 8 с.","info":["Удары молнии наносят 5 безтипового урона без PvE-масштабирования и не накладывают Surge Rods.","Перезарядка ударов молнии 4 секунды.","Бонус двойного наложения кристаллов не суммируется с последующими срабатываниями Fulgurite Formation.","Удары молнии активируют Grounding Bolt."],"stats":""},"frozen-legs":{"description":"Охлаждение (Chill), наложенное мантрами, не даёт противникам перекатываться.","info":["Не работает с Crystallization.","Действует первые 0,75 секунды после срабатывания охлаждения или заморозки."],"stats":""},"after-cut":{"description":"Если атака физическая и ветряная, она накладывает после-удар, который наносит 5% от нанесённого вами урона. Если атака была мантрой, он наносит 2,5% урона.","info":["Единственные мантры Galebreathe, получающие бонус 2,5%: Wind Blade, Air Force, Tornado Kick, Tornado, Galetrap и Wind Gun.","Статус Maestro's Blade от Inhale позволяет вашим обычным атакам получать выгоду от After Cut. Оружие Galebreathe получает выгоду от After Cut и без Inhale.","After Cut не модификатор урона, а второй удар уроном Galebreathe без оглушения. Поэтому на него не действует потолок модификаторов урона.","After Cut наносит урон исходя из вашего итогового нанесённого урона, после сопротивлений и множителей.","Например, если вы наносите 100 урона M1, вы нанесёте 10 урона After Cut; но если у противника 50% физического сопротивления, ваш M1 наносит 50, и After Cut снижается до 5 (10% от 50). С другой стороны, если вы наносите 100 урона M1 и имеете +50% урона от модификаторов, After Cut наносит урон от модифицированного значения: 15 (10% от 150).","After Cut наносит урон Galebreathe, поэтому его можно сопротивлять дважды."],"stats":""},"breathing-impact":{"description":"Отбрасывание врагов ветряными заклинаниями в объекты наносит дополнительный дробящий урон в зависимости от силы удара.","info":["Следующие мантры Galebreathe имеют отбрасывание и могут получить выгоду от этого таланта: Air Force, Champion's Whirlthrow, Tornado Kick, Gale Punch, Rising Wind и Wind Gun.","Дополнительный урон зависит от начального урона атаки и ускорения вашего противника.","Поскольку дополнительный урон зависит от ускорения, на него сильно влияют производительность сервера и пинг."],"stats":""},"inhale":{"description":"Отмена мантры ветра сохраняет её на 5 секунд и усиливает следующую мантру ветра, применённую в это время. [перезарядка 7 с, снимается при попадании лёгкой атакой]","info":["Вдох мантры Galebreathe добавляет (уровень мантры × 2)% урона следующей мантре Galebreathe. Например, Inhale 5 уровня даст следующей мантре ветра бонус 10% к урону.","Inhale даёт ускорение на 3 секунды.","Inhale мантры также сохраняет её модификаторы и применяет их к следующей подходящей мантре.","Inhale даёт статус Maestro's Blade. Он позволяет вашим обычным атакам активировать After Cut.","Длительность Maestro's Blade равна стоимости Эфира вдохнутой мантры (до Blue Gem), делённой на 5. Например, мантра со стоимостью 50 Эфира даёт Maestro's Blade на 10 секунд.","Можно активировать на мантрах Flamecharm, если есть талант Fan the Flames. Можно активировать на мантрах Shadowcast при использовании оружия Eyes of Ethiron."],"stats":""},"neuroplasticity":{"description":"Ваш разум это пластичная, гибкая субстанция. Стоимость Эфира дополнительных модификаций ваших мантр теперь снижена на 10%.","info":["Повышение стоимости Эфира от модифицированных мантр снижается на 10% (для модификаций 1 уровня с 10 до 9 Эфира, для 2 уровня с 20 до 18).","Не применяется задним числом к ранее модифицированным мантрам, пока вы не перезайдёте."],"stats":"+1 универсальный слот мантры"},"crystal-shrapnel":{"description":"Взрывы ваших кристаллов теперь имеют область действия и накладывают кристаллы на всех, кого задели.","info":["Не задевает союзников и цель, на которой сработало.","Радиус 10 студов от цели, на которой сработало."],"stats":""},"glass-path-crystallization":{"description":"Ваши ледяные умения больше не дают замедление и возможность заморозки, а вместо этого заставляют ледяные кристаллы расти на противнике.","info":["Наложение охлаждения или заморозки накладывает на врага красные ледяные кристаллы вместо замедления. 6 накопленных кристаллов или пробитие блока противника с кристаллами заставляют их взорваться.","3 базового урона Frostdraw на кристалл с масштабированием 5 от Frostdraw. Формула урона кристаллов: (3 + (1 + 0,005 × вложение во Frostdraw)) × количество кристаллов.","Множитель урона в PvE 4,45x.","Перезарядка срабатывания взрыва 1 с.","Позволяет получить Crystal Impale, Crystal Knee и Ice Lasers.","Увеличивает урон Crystal Impale и Crystal Knee (они наносят меньше урона, если убрать этот талант).","Chilling теперь накладывает 1 кристалл при попадании.","Меняет цвет ваших мантр Frostdraw, Gran Sudaruska, Kyrswynter, Hero's Blade of Frost и зачарования Chilling на розовато-красный."],"stats":""},"reclaimed-glass":{"description":"Взрывы вашего Crystal Shrapnel теперь дают вам и союзникам, попавшим под них, 10% стихийного сопротивления на 10 секунд.","info":["У целей с Reclaimed Glass появляется розовый треугольный визуальный эффект, который суммируется при последующих срабатываниях.","Хотя визуальный эффект суммируется, стихийное сопротивление не суммируется.","Повторное срабатывание обновляет длительность."],"stats":""},"bodkin-arrow":{"description":"Ваши заряженные выстрелы теперь наносят дополнительный урон броне бронированных врагов и дополнительный урон небронированным.","info":["Заряженные выстрелы из лука полностью игнорируют броню и без этого таланта, поэтому первый эффект ничего не даёт."],"stats":""},"hard-stop":{"description":"Попадание заряженным выстрелом отбрасывает противника назад.","info":[],"stats":""},"precision-crusher":{"description":"Попадание заряженным выстрелом сбивает противника с ног вместо отбрасывания назад.","info":["Заряженные выстрелы из лука теперь накладывают Knockdown."],"stats":""},"armor-piercing":{"description":"Ваши атаки из огнестрельного оружия теперь игнорируют 10% дробящей брони противника. Применяется мультипликативно до применения PEN.","info":["Действует на атаки оружием всего огнестрельного оружия: пистолетов и винтовок.","С математической точки зрения Armor Piercing это мультипликативное увеличение вашего PEN против дробящей брони на 10%, применяемое после всех остальных источников PEN, поэтому у него сильно убывающая отдача в зависимости от вашего PEN.","Но учтите: игра не считает этот эффект PEN ни при каких обстоятельствах, поэтому сопротивление PEN на него не действует.","При 0% PEN это фактически даёт +10% PEN против дробящей брони, но это значение уменьшается на 1% за каждые 10% вашего PEN. Формула: 1 - ((1 - текущий PEN%) × (1 - 10%)) = эффективный PEN против дробящей брони.","Например: 20% PEN + Armor Piercing равно 28% PEN против дробящей брони (+8).","Некоторые винтовки получают меньше выгоды от Armor Piercing из-за типа их урона.","Для Rifle Spear это сработает только на критической атаке, так как Rifle Spear это оружие с рубящим уроном.","Для Stormseye и Rosen's Hellflame выгода от Armor Piercing лишь частичная из-за их стихийного урона.","В некоторых случаях Armor Piercing может повысить вес стихийных сопротивлений противника, снижая его дробящее сопротивление, и он будет сопротивляться вашему урону по стихийному сопротивлению. Если же у него стихийное сопротивление выше дробящего, Armor Piercing вообще ничего не даст.","Хотя талант можно получить на Greatcannon, на этом типе оружия он не работает.","Примечание: если вы встанете на сторону Asius и добавите Bulletproof в свой пул талантов, а затем заплатите Trig 2 000 Notes в качестве извинения, в ваш пул добавится и этот талант, позволяя получить и Bulletproof, и Armor Piercing. Это невозможно, если вы изначально встали на сторону Trig."],"stats":""},"bulletproof":{"description":"Вы не получаете урона броне от огнестрельного оружия. Вы получаете на 5% меньше урона броне из других источников.","info":["Не влияет на природную броню (Natural Armor).","Талант лишь убирает или уменьшает урон по броне; на PEN он не влияет.","Суммируется мультипликативно с другими источниками снижения потери брони (Armor Conserver, Steadfast и Armorer's Ring).","Примечание: если вы встанете на сторону Asius и добавите Bulletproof в свой пул талантов, а затем заплатите Trig 2 000 Notes в качестве извинения, в ваш пул добавится и Armor Piercing, позволяя получить оба таланта. Это невозможно, если вы изначально встали на сторону Trig."],"stats":""},"execution":{"description":"Атаки вашего оружия во второй руке теперь считаются Flourish и наносят фиксированные 20 дополнительного урона при использовании без пуль.","info":["Работает с парным огнестрельным оружием, добавляя 5 фиксированного урона к каждому второму выстрелу.","Однако часть таланта про Flourish с парным оружием не работает.","Дополнительный урон это чистый урон (true damage).","Не работает с Unnecessary Theatrics и Dazing Finisher."],"stats":""},"gunpowder-blast":{"description":"Выстрелы из пистолета без пуль наносят 2 дополнительного урона по Стойке (Posture). [Парное оружие]","info":["Увеличивает урон по Стойке (Posture) ваших пороховых выстрелов на 2, если в инвентаре нет физических пуль."],"stats":""},"hip-shooter":{"description":"Когда вы держите среднее или тяжёлое оружие, ваше боковое оружие теперь может выпускать пулю-снаряд.","info":["Для этого нужны пули в инвентаре.","Перезарядка 5 секунд."],"stats":""},"parting-gift":{"description":"После Flourish вы получаете возможность стрелять пулями в течение 5 секунд. [Парное оружие]","info":["При срабатывании все M1 парного оружия в следующие 5 секунд имеют снаряды.","Срабатывает, даже если ваш Flourish парирован или заблокирован.","Снарядные M1 от этого таланта могут активировать другой талант."],"stats":""},"quick-swap":{"description":"Сильно сокращает перезарядку смены пуль. [Парное оружие]","info":["Менять тип гильз можно сменой стойки (Y)."],"stats":""},"quickdraw":{"description":"Позволяет стрелять из оружия во второй руке сразу после замаха. [Не нужен для парного огнестрельного оружия]","info":["Позволяет игроку мгновенно начать атаковать оружием во второй руке после атаки основным оружием."],"stats":""},"taste-the-rainbow":{"description":"Каждый раз, когда вы стреляете, тип боеприпасов меняется. [Парное оружие]","info":["Каждый M1 меняет тип пуль."],"stats":""},"true-ether-bullets":{"description":"Использование Ether Bullets наносит стихийный урон вашей самой развитой школы.","info":["Попав 2 раза, вы заставите 3-й выстрел нанести стихийный урон и наложить стихийный статус-эффект вашей наиболее развитой школы (Attunement). Если у вас нет школы, талант не работает.","Flamecharm: пули поджигают / создают Eruption (Lava Serpent) / призывают Puppets (Twisted Puppets)","Frostdraw: пули накладывают охлаждение / 1 кристалл (Crystallization)","Thundercall: пули накладывают шок / 1 Surge Rod (Surge Path)","Galebreathe: пули наносят After Cut и ненадолго накладывают одышку (Winded)","Shadowcast: пули ослепляют врага / накладывают горение (Twisted Puppets)","Ironsing: пули накладывают Metal Rods","Bloodrend: пули накладывают отравление кровью (Blood Poisoning)","Если у игрока несколько школ с одинаковым вложением, используется самая левая в списке приоритета: Thundercall > Bloodrend > Ironsing > Shadowcast > Flamecharm > Galebreathe > Frostdraw","Талант не заставляет оружие масштабироваться от атрибутов школ, он только превращает физический урон в стихийный.","Хотя его можно получить на Greatcannon, на них талант ничего не делает."],"stats":""},"brain-rattler":{"description":"Пробитие блока противника вашей критической атакой встряхивает мозг в его черепе, вызывая повышенную потерю крови, накладывает Stagger на PvE-врагов и размывает им зрение.","info":["Талант работает с ошибкой и срабатывает на ВСЕ пробития блока, в том числе от мантр, некритических атак и совсем другого оружия.","При пробитии блока накладывает визуальное затемнение и потерю крови. В PvE также накладывает Staggered.","Статус Stagger заставляет противника получать на 33% больше урона по Стойке (Posture)."],"stats":""},"dispatch":{"description":"Цели в Bear Trapped наносят на 20% меньше урона по Стойке. Оглушённые (Dazed) цели наносят на 20% меньше урона по Стойке. Эффекты суммируются.","info":[],"stats":""},"hammerfall":{"description":"Воздушные атаки наносят на 25% больше урона по Стойке (Posture), когда блокируются.","info":[],"stats":""},"fan-the-flames":{"description":"Ваши сохранённые мантры ветра теперь могут усиливать мантры огня.","info":["Эффекты Inhale (перенос модификаторов мантр между мантрами Galebreathe) и бонус к урону, который он даёт ((уровень вдохнутой мантры) × 2)%, теперь действуют и на мантры Flamecharm. Но сами мантры Flamecharm вдохнуть нельзя."],"stats":""},"all-the-dead-gods":{"description":"Ваши обычные атаки теперь накладывают анти-лечение (Anti-Heal) и 5% Heal Boost против PvE на 8 секунд.","info":["Каждый раз, когда вы попадаете M1 или критической атакой с тегом M1, накладывается Anti-Heal на 8 секунд.","Эффективность анти-лечения All the Dead Gods против источников активного лечения зависит от суммарного вложения в Силу воли и Интеллект. Минимум 70% при 55 суммарных очках Интеллекта и Силы воли, максимум 100% при 105 суммарных очках.","All the Dead Gods теряет 0,6% анти-лечения за каждое суммарное очко Интеллекта и Силы воли ниже 105. Например, при 80 суммарных очках анти-лечение составит 85%.","Эффективность анти-лечения All the Dead Gods против источников пассивного лечения всегда 100% независимо от вложений. Источники пассивного лечения: костры, Curse of the No Life King и естественная регенерация здоровья.","Ring of Pestilence увеличивает длительность анти-лечения All the Dead Gods на 4 секунды: с 8 до 12.","Этот талант увеличивает длительность всех других эффектов Anti-Heal, которые вы накладываете, на 2 секунды.","Анти-лечение нельзя наложить на союзников, и оно не влияет на аптечки.","Статус Heal Boost увеличивает всё наступательное лечение (например, от Bloodless Gems) при атаке PvE-врагов, на которых сейчас действует ваш Anti-Heal. Все источники Heal Boost складываются между собой и действуют, пока цель страдает от любого вида Anti-Heal. Этот талант даёт +5% Heal Boost."],"stats":"+7 к Рассудку"},"sin-stacker":{"description":"Длительность вашего All The Dead Gods теперь зависит от того, сколько стаков анти-лечения уже на противнике; ваш Heal Boost против PvE повышается до 10%.","info":["Влияет на все источники Anti-Heal, а не только на All the Dead Gods.","Накладывая дополнительные экземпляры Anti-Heal на цель, уже находящуюся под ним, вы можете увеличить длительность последующих стаков Anti-Heal на 1 секунду за каждый наложенный стак.","На примере All the Dead Gods: при 1 стаке Anti-Heal длится 8 секунд. Наложение второго стака сделает второй стак 9 секунд, третьего 10 секунд и так далее.","Когда стаки Anti-Heal спадают, дополнительная длительность, которую они дают будущим стакам, обнуляется. Например, если вы наложили стак 1 на 8 секунд и стак 2 на 9 секунд, а затем подождали, пока стак 1 закончится, и нанесли ещё удар, Anti-Heal от третьего удара продлится только 9 секунд.","Статус Heal Boost увеличивает всё наступательное лечение (например, от Bloodless Gems) при атаке PvE-врагов, на которых сейчас действует ваш Anti-Heal. Все источники Heal Boost складываются между собой и действуют, пока цель страдает от любого вида Anti-Heal. Этот талант даёт +10% Heal Boost."],"stats":"+8 к Рассудку"},"mythic-stability":{"description":"Игроки и обычные мобы не могут мгновенно казнить вас, пока вы стоите на ногах. Защищает от одного мгновенного добивания в бессознательном состоянии. Перезарядка 60 с.","info":["Работает против атак вроде Sudden Ambush и Luminant Beam от The Doom of Caeranthil, которые обычно сразу хватают вас. Но НЕ защищает от Blood Scourge или его испорченного варианта."],"stats":""},"peripheral-vision":{"description":"Ваш Glare теперь игнорирует, смотрит ли противник на вас.","info":["Обычно Glare не может попасть по целям, которые не смотрят на вас. Этот талант убирает ограничение."],"stats":"+5 к Рассудку"},"bottom-freeze":{"description":"Попадание ледяными снарядами по охлаждённым врагам, стоящим на льду, примораживает их к земле.","info":["Не даёт им поворачивать персонажа и вообще двигаться.","Bottom Freeze прерывается досрочно, если получен урон из любого источника."],"stats":""},"cryonis":{"description":"Все ледяные заклинания, применённые на льду, стоят меньше Эфира.","info":["Мантры Frostdraw стоят на 20% меньше Эфира, если применять их, стоя на льду."],"stats":""},"frost-buster":{"description":"Критические атаки Greatsword и Greathammer теперь оставляют лёд под прочерченным путём.","info":["При критической атаке создаёт три довольно больших ледяных участка по линии перед вами. Участки держатся 1 минуту 30 секунд.","Вопреки описанию, Greathammer не активирует Frost Buster, а Greataxe активирует. Greatcannon тоже не активирует Frost Buster.","Frost Buster срабатывает только один раз за критическую атаку.","Также даёт возможность замораживать и повреждать лодки критическими атаками Greatsword и Greataxe.","Frost Buster срабатывает на любую критическую атаку с Greatsword или Greataxe, включая странные случаи: зачарования, заменяющие критическую атаку (Curse of the Unbidden, Nemesis и Stormbreaker), и все критические атаки стилей кулачного боя на Markor's Inheritor.","Поскольку у Frost Buster нет перезарядки и очень большая площадь покрытия, это один из лучших способов создавать лёд в игре."],"stats":""},"frostbite":{"description":"Враги больше не могут лечиться, пока охлаждены (Chilled) вами. Против PvE-врагов вы также получаете на 5% больше Heal Boost, пока они охлаждены.","info":["Этот эффект ненадолго накладывается после наложения кристалла.","Статус Heal Boost увеличивает всё наступательное лечение (например, от Bloodless Gems) при атаке PvE-врагов, на которых сейчас действует ваш Anti-Heal. Все источники Heal Boost складываются между собой и действуют, пока цель страдает от любого вида Anti-Heal. Этот талант даёт +5% Heal Boost."],"stats":""},"frozen-anchor":{"description":"Накладывайте Bottom Freeze и охлаждение на противника при каждом Flourish, аперкоте или критической атаке. Перезарядка 10 с.","info":["Работает похоже на Meteor Impact, срабатывая на любую мантру, считающуюся аперкотом или Flourish.","Bottom Freeze снимается, если цель получает урон из любого источника. Из-за этого талант крайне неэффективен на критических атаках с множественными попаданиями.","Охлаждение от этого таланта длится 12 секунд, что делает его сильным вариантом для гибридных билдов, у которых мало возможностей наложить охлаждение.","Наносит (0) урона Frostdraw как регистрацию попадания для охлаждения. Это позволяет активировать некоторые таланты, например Flashboil, без других источников урона Frostdraw.","Сейчас работает с ошибкой и срабатывает даже при блоке, парировании или уклонении."],"stats":""},"frozen-pin-cushion":{"description":"Ваши Ice Daggers теперь накладывают Frozen.","info":["С Crystal Path мгновенно активирует Crystallization при попадании в цель, отбрасывая её назад и нанося больше урона."],"stats":""},"saint-jay":{"description":"Когда охлаждённый (Chilled) враг получает лечение, оно аннулируется, и 60% лечения перенаправляется вам. Пока это действует и враг на льду, скорость вашего лечения повышена; также ваш Heal Boost против PvE повышается до 10%.","info":["Не срабатывает, если лечение наложили вы сами: нельзя лечить себя, лечя противника.","Срабатывает только на непассивное лечение. Например (список не исчерпывающий): Flame Wisp, плевки или Bloodless Gem активируют этот эффект, а костры, Conditioned Runner или Curse of the No Life King нет.","При Glass Path: Crystallization каждое попадание мантрой Frostdraw активирует Saint Jay на 2 секунды. (Не суммируется)","Эффект «на льду» у Saint Jay работает с ошибкой и не действует.","Статус Heal Boost увеличивает всё наступательное лечение (например, от Bloodless Gems) при атаке PvE-врагов, на которых сейчас действует ваш Anti-Heal. Все источники Heal Boost складываются между собой и действуют, пока цель страдает от любого вида Anti-Heal. Этот талант даёт +10% Heal Boost."],"stats":""},"stasis-strike":{"description":"Взрывы ваших кристаллов наносят больше урона, если противник ещё и примёрз к земле (bottom frozen).","info":["Ваши детонации кристаллов наносят на 67% больше урона по целям, примёрзшим к земле.","Большинство умений, накладывающих Bottom Freeze, при этом пути вместо этого мгновенно взрывают кристаллы. Поэтому для стабильного срабатывания этого таланта рекомендуется Frozen Anchor."],"stats":""},"agitating-spark":{"description":"Наложение горения на врагов распространяет его на всех поблизости, включая вас самих.","info":["При срабатывании небольшая оранжевая частица тянется от горящей цели, в которую вы попали, к другим целям поблизости и поджигает их.","При распространении горения накладывается либо обычное Burn, либо вид горения от одного из ваших Attunement Path или Azure Flames, так как они глобально влияют на все горения. Для Twisted Puppets накладывается Puppet Burn, позволяющее призывать Puppets.","Не может вызывать Eruption и всегда накладывает горение.","Agitating Spark обходит блок и парирование.","Визуальный эффект срабатывает, а талант уходит на перезарядку, когда вы получаете урон по себе, пока горите, но горение не распространяется. Flame Within, однако, распространяет накладываемое на вас горение при применении.","Перезарядка 1 секунда.","Может распространяться на союзников. Талант Controlled Combustion не даёт Agitating Spark распространять горение на вас и ваших союзников."],"stats":""},"immolation":{"description":"Мантры огня стоят на 70% дешевле, пока вы горите. Если вы бьёте кого-то, пока горите, накладывается огненный урон. Вы получаете на 50% меньше урона от пламени, причинённого вами самими.","info":["«Пламя, причинённое вами самими» включает Flame Within, Agitating Spark, распространённый вами, и поджоги окружения, созданные вами.","«Накладывается огненный урон» накладывает статус горения, а не добавляет урон Flamecharm. Горение накладывается, даже если у вас Eruption Path: Lava Serpent.","Не все атаки активируют этот эффект, вопреки описанию. Вместо этого горение накладывают все экземпляры физического урона, даже если атака не наносит чистый физический урон (например, Clutching Shadow). И все атаки с визуальным эффектом рубящего удара (частицы крови) при попадании, такие как Ice Daggers или Gale Lunge, тоже активируют Immolation и накладывают горение."],"stats":"+8 к Рассудку"},"corpse-explosion":{"description":"Тела, которые вы сожгли насмерть, сразу взрываются, нанося огромный урон. Ваш огонь сжигает бессознательные цели гораздо быстрее.","info":["Время сжигания бессознательных целей сокращается вдвое: с 7 до 3,5 секунд.","Время, за которое горение казнит цель, сильно зависит от производительности сервера и может быть дольше указанного.","Взрыв не работает: вы сожжёте цель насмерть без взрыва."],"stats":""},"pleeksty-s-faith":{"description":"Когда вы горите, пламя автоматически гасится за некоторое количество Эфира.","info":["Стоит 20 Эфира.","Не срабатывает на пламя, причинённое вами самими.","Также требуется для боя с Aska в Firfire. Без этого таланта, Pleeksty's Will или Flame Worshipper Armor его пламя вас сметёт."],"stats":""},"critical-engine":{"description":"Вы получаете возможность использовать Deep Gems на своей критической атаке. Держите Deep Gem, который хотите применить к крит. атаке, затем используйте инструмент, чтобы усилить критическую атаку.","info":["Экипируйте Deep Gem, держа предмет и кликая, так же как при экипировке Deep Gem на мантру.","Экипировка Deep Gem на критическую атаку не расходует Deep Gem.","Попытка экипировать другой Deep Gem на критическую атаку заменит старый новым.","Срабатывание этого таланта ставит соответствующий Deep Gem на перезарядку, если она у него есть.","Mantle of Enmity может активировать Critical Engine. Если вы используете Blessed Gem, воздушная атака Mantle уменьшит вдвое перезарядку вашей критической атаки, а не Mantle.","Это относится ко всем эффектам ниже.","Aegis Gem даёт вам 10% снижения урона на 10 секунд при попадании.","Blessed Gem вдвое сокращает перезарядку вашей критической атаки при попадании.","Сокращение перезарядки критической атаки от Warmaster's Medallion применяется до этого эффекта, позволяя в сумме сократить перезарядку на 60% (55% в Chime of Conflict).","Bloodless Gem снижает урон вашей критической атаки на 20%, но даёт лечение, равное 30% нанесённого урона.","Blue Gem возвращает вам Эфир при попадании. Восстановление Эфира 1:1 с масштабированным нанесённым уроном; его нельзя ни увеличить, ни уменьшить модификаторами или сопротивлениями. Эффект не имеет PvE-масштабирования.","Insignia Gem сокращает подготовку вашей следующей мантры на 15% при попадании.","Kyrsan Gem накладывает суммирующееся замедление при попадании.","Might Gem увеличивает урон вашей критической атаки по Стойке (Posture) на 10%. Кроме того, его можно использовать для активации талантов экипировки Ascended Outlaw Set.","Бонус к урону по Стойке можно увеличить талантом Ascended Outlaw Hat, он растёт с числом Might Gems, экипированных на ваши мантры.","Nocturnal Gem наносит дополнительные 10 рубящего урона после задержки в 1 секунду.","Warped Blue Gem даёт статус Etherguard при попадании, если вы носите Bluestone Set.","Wayward Gem телепортирует вас к противнику после попадания критической атакой. Между попаданием и телепортацией задержка 1 секунда.","Wind Gem даёт вам ускорение на 10 секунд при попадании.","Wrath Gem накладывает статус Wrath на 9 секунд, увеличивая урон вашей критической атаки на 7,5% за каждую вашу боевую метку игрока. Этот бонус не действует на удар, активировавший Wrath Gem, и подчиняется потолку модификаторов урона. Кроме того, его можно использовать для активации талантов экипировки Reinforced War Set."],"stats":""},"heavy-shoulders":{"description":"Если на противнике 3 или больше стержней, его уклонения медленнее.","info":["Снижает дальность переката на 10%."],"stats":""},"ironclad-punishment":{"description":"Ваши мантры Ironsing наносят больше урона по Стойке (Posture) врагам, чем больше у них прочности брони.","info":["Мантры Ironsing получают +0,15% урона по Стойке за каждый 1% текущей прочности брони противника; максимум +15% при полной броне противника.","Ограниченно полезно в PvE, потому что большинство нечеловекоподобных монстров не могут блокировать."],"stats":""},"laced-traps":{"description":"Люди, задетые вашими «Caltrops», замедляются и получают Grounded на небольшое время, а PvE-враги ещё и получают Sluggish на несколько секунд.","info":["Попадание Caltrop замедляет противника и отключает его способность прыгать на 1,1 секунды. Эффект обновляется, если жертва попадает под другой Caltrop.","После получения таланта ваши Caltrops получают фиолетовый визуальный эффект.","Статус Sluggish снижает урон поражённых целей на 15%."],"stats":""},"metal-shackles":{"description":"Пробитие блока противника не даёт ему получать ускорение на 5 секунд, а PvE-противники получают Sluggish на 12 секунд.","info":["При срабатывании на ногах цели визуально появляются металлические кандалы.","Статус Sluggish снижает урон поражённых целей на 15%."],"stats":""},"oh-the-irony":{"description":"Противники под «Taunt» получают двойное количество железных стержней, пока эффект действует.","info":["Влияет на все источники наложения стержней.","Работает любой источник статус-эффекта Taunt, а не только сама мантра."],"stats":""},"piercing-metal":{"description":"Наносите дополнительный урон броне врагов за каждый металлический стержень на них.","info":["Увеличивает урон броне на 5% за каждый наложенный стержень: до 25% при 5 стержнях или 50% при 10.","Отлично работает в PvE, так как оглушение (stagger) мобов связано с пробитием их брони.","Не влияет на эффекты высасывания брони, такие как Metal."],"stats":""},"thornmail":{"description":"Если вас бьют Flourish-атакой, на нападающего накладывается металлический стержень.","info":[],"stats":""},"grand-skewer":{"description":"Ваш Grand Javelin теперь несёт противников по воздуху.","info":["Нажмите парирование во время подготовки Grand Javelin, чтобы активировать этот эффект.","Не работает в базах гильдий и на 1 слое Глубин."],"stats":""},"amplified-rage":{"description":"Amped теперь даёт дополнительные +10% урона оружием. Также урон по себе и перезарядка увеличиваются в 3 раза.","info":["Увеличивает бонус к урону оружием от Amped с +10% до +20%.","Последнее предложение в описании таланта лжёт: он не увеличивает ни перезарядку Electrify, ни урон по себе.","Раньше назывался Raging Static."],"stats":""},"amplified-reflexes":{"description":"Amped теперь даёт повышенную скорость и паркур.","info":["Пока действует Amped, талант увеличивает скорость ходьбы на 50%, даёт очень небольшое увеличение скорости бега и 20% к высоте лазания. Все остальные виды паркура и движения Amplified Reflexes не затрагивает.","Раньше назывался Jumpstart."],"stats":""},"electrify":{"description":"Ударьте себя током и получите Amped на 15 с. Можно использовать, когда вас несут, чтобы вырваться.","info":["Не путайте с несвязанным статус-эффектом Electrified из категории талантов Authority Interrogator.","Перезарядка Electrify 1 минута.","Amped даёт вашим атакам оружием бонус к урону 10% и позволяет им накладывать шок (Shock) или Surge Rods при попадании.","Пока вы под Amped, вы получаете на 10% больше урона из всех источников.","Если использовать, когда вас несут, наносит урон игроку, который вас несёт, заставляя его бросить вас.","Если использовать без переноски, наносит вам 5% текущего здоровья уроном Thundercall по себе с оглушением от попадания и накладывает на вас Shock/Surge Rods при применении.","Урон по себе можно смягчить с помощью Deepscorn Casque или сопротивления Thundercall/общего сопротивления. Stormchanter's Raiments полностью убирают урон по себе и накладывание на себя Shock/Surge Rods. Если надеть и Deepscorn Casque, и Stormchanter's Raiments, вы будете лечиться на 12 единиц здоровья при применении.","Раньше назывался Static Withdraw."],"stats":""},"flying-swiftkick":{"description":"Попадание критической атакой Jus Karita при активном Swiftkick Prodigy сильно замедляет врага и расходует ваше ускорение.","info":[],"stats":""},"justicar-s-prowess":{"description":"Jus Karita получает +30% урона по Стойке (Posture) против других стилей кулачного боя.","info":["Вы получаете +30% урона по Стойке атаками оружием против противников, использующих Way of Navae, Fang and Coil, Imperium Kata, Untrained Fist или Legion Kata."],"stats":""},"justicar-s-renewal":{"description":"Попадание критической атакой Jus Karita по противнику сбрасывает перезарядку.","info":["Каждый раз, когда вы попадаете критической атакой Jus Karita, её можно сразу использовать снова без задержки.","Жёстко прописано, что работает только на стандартную критическую атаку Jus Karita и критическую атаку Vanguard от происхождения Justicar.","Перезарядка 10 секунд.","Вопреки описанию «попадание», эффект срабатывает и при блоке, парировании и уклонении."],"stats":""},"swiftkick-prodigy":{"description":"Последовательные обычные атаки Jus Karita дают временное ускорение.","info":["Три попадания M1 по противнику дают вам ускорение."],"stats":""},"kickstart":{"description":"Сыграйте роль воскресителя. Используйте свою молнию, чтобы дефибриллировать союзников на поле боя.","info":["Используйте Kickstart на бессознательной цели, чтобы поднять её и вылечить на 10% максимального здоровья.","При использовании тратит 5% вашего Эфира и ещё 20% при успешном применении.","Анимация Kickstart длится 3 секунды, в течение которых вы не можете выполнять никаких действий.","Перезарядка Kickstart 10 секунд.","Вопреки описанию «союзники», можно использовать на не-союзниках и даже на человекоподобных NPC.","Можно использовать на людях, парализованных Cap Artist или Paralytic Dust."],"stats":""},"blade-s-edge":{"description":"Урон, нанесённый остриём копья, увеличивается на 10%.","info":["Бонус применяется, если атака копьём попадает в самый край дальности оружия, что поощряет игру на удержание дистанции."],"stats":"+2 к пассивной Ловкости"},"defensive-sweep":{"description":"Пробитие Стойки (Posture) противника даёт вам +50% PEN на 3 секунды.","info":["Бонус к PEN действует только на M1.","Перезарядка 14 секунд."],"stats":""},"driving-impact":{"description":"Первый удар критической атаки вашего копья наносит сильно увеличенный урон по Стойке (Posture). Последующие удары наносят сниженный урон по Стойке.","info":["Работает только на стандартную критическую атаку копья.","Удваивает урон по Стойке первого удара критической атаки копья ценой обнуления урона по Стойке второго. Фактически весь урон по Стойке критической атаки консолидируется в первом ударе."],"stats":""},"hoplite":{"description":"Урон по Стойке (Posture) снижается на 15%, когда вы держите копьё и стоите на месте.","info":["Снижает получаемый, а не наносимый урон по Стойке."],"stats":"+2 к пассивной Ловкости"},"lancer-s-impale":{"description":"Попадание по врагу после идеального уклонения заставляет вашу следующую атаку наносить урон кровотечением. Если эта атака и так вызывала бы кровотечение, она добавляет +10% урона сквозь блок (chip).","info":[],"stats":"+4 к пассивной Ловкости"},"empowered-eruption":{"description":"Ваш следующий Eruption после критической атаки становится усиленным: +50% к радиусу и урону.","info":["Бонус Empowered Eruption действует бессрочно и расходуется только при срабатывании Eruption.","Перезарядка 10 секунд."],"stats":""},"eruption-path-lava-serpent":{"description":"Ваши огненные умения больше не накладывают горение, а вместо этого вызывают извержение под ногами врагов.","info":["Вместо поджога цели при применении умений, накладывающих Burn, создаётся извержение (Eruption) с задержкой 1,25 секунды и перезарядкой 3 секунды. Урон извержения растёт с вложением во Flamecharm.","Извержения имеют базовый урон Flamecharm 15 с масштабированием 5 от Flamecharm. Формула урона: «15 × (1 + 0,005 × вложение во Flamecharm)».","Deepfire Ring сокращает задержку извержения на 20%: с 1,25 с до 1 с.","Талант Azure Flames меняет цвет извержений на синий, увеличивая их размер и урон по Стойке. На лаву от другого таланта смена цвета не влияет.","Вопреки описанию, горение с Eruption Path всё ещё можно накладывать.","Горение всё ещё можно наложить через: Agitating Spark (но горение должно уже быть), Flame Within (на себя), Flash Point, Immolation и попадание мантрами Flamecharm или Thundercall по горючей местности. Все остальные источники наложения горения вместо этого создадут извержение.","Из-за очень малого числа источников горения с Eruption Path использование талантов, требующих горения, особенно Emperor Flame, с этим путём не рекомендуется. Но они будут работать как обычно, если вы всё же их активируете."],"stats":""},"flash-point":{"description":"Пробитие блока противника усиливает ваши Eruptions на следующие 10 с. Перезарядка 45 с. Пробитие блока противника мантрой огня накладывает горение (Burning).","info":["Усиленные извержения имеют +50% к радиусу и урону."],"stats":""},"callout":{"description":"Вы можете отмечать объекты или врагов нажатием Z, и они отметятся для всех ближайших союзников.","info":["Временно показывает метку на местоположении объекта или персонажа; эта информация отображается и вашим союзникам."],"stats":""},"spotter":{"description":"Отметка врагов в Rhythm теперь показывает ваши союзникам состояние их здоровья.","info":["Активируется использованием Callout (по умолчанию Z) в Rhythm.","Отключено у игроков с соответствующим талантом.","Этот талант не нужен, чтобы вы сами видели индикаторы здоровья противников в Rhythm: он только передаёт эту информацию союзникам. Если у вас есть другие способы сообщать её союзникам, талант не нужен."],"stats":""},"observation":{"description":"Кадры уклонения больше, если вы сразу отменяете перекат.","info":["Быстрая отмена переката даст кадры уклонения, равные длине обычного переката. По сути это даёт дополнительные 0,1 с кадров уклонения."],"stats":"+1 к пассивной Ловкости"},"safety-dance":{"description":"Ваши базовые кадры уклонения увеличиваются на 0,05 с.","info":["Вы получаете больше кадров неуязвимости при уклонении, а значит дольше защищены от урона.","Кадры неуязвимости уклонения увеличиваются с 0,3 с до 0,35 с.","Влияет только на полные перекаты уклонения, а не на отмены уклонения."],"stats":"+1 к пассивной Ловкости"},"air-pressure":{"description":"Уклонение от атаки или попадание по блоку врага превращает ваш следующий рывок в Gale Dash. Gale Dash уносит вас дальше обычных рывков и имеет увеличенные кадры неуязвимости, но сразу сбрасывается, если вы начинаете атаку.","info":["Перезарядка 8 секунд."],"stats":"+1 к пассивной Ловкости"},"cyclone-blade":{"description":"После успешного Gale Dash вы окутываете оружие ветром, из-за чего ваша следующая лёгкая атака наносит +15% урона кровотечением и получает +10% урона сквозь блок (chip).","info":["Перезарядки нет, длится 3 с.","Также срабатывает от рывков Phantom Step.","Вопреки описанию «лёгкая атака», бонусы получают и критические атаки оружием."],"stats":"+2 к пассивной Ловкости"},"pressure-break":{"description":"Пробитие Стойки (Posture) врага заставляет его принять сильное давление ветра, увеличивая урон атаки на +15% и отбрасывая врага назад.","info":[],"stats":"+2 к пассивной Ловкости"},"wind-step":{"description":"Создаёт под вами ступень ветра при прыжке в воздухе. Прыжок при скольжении по склону или с обрыва бросает вас вперёд.","info":["Нажмите пробел в воздухе для двойного прыжка. Он оставляет небольшой торнадо, в который может прыгнуть кто-то другой, чтобы тоже сделать двойной прыжок.","В бою это умение стоит Эфира.","Прыгните при скольжении по склону или у края обрыва, чтобы выполнить ветряной прыжок вперёд. Перезарядка 1 с."],"stats":""},"stay-of-execution":{"description":"Увеличивает время вашей казни на 20%. Спасение других от казни даёт вам обоим 10 временного здоровья (перезарядка 20 с).","info":["«Спасение» означает прерывание попытки казни.","Таланты The Savior, Defiant Until the End и Last Second Negotiations были объединены с этим."],"stats":"+6 к Рассудку"},"scorched-peak":{"description":"Пробитие блока врага, который горит или поражён мантрой огня, заставляет его поразить молнией.","info":["«Горит» означает горит в данный момент.","Наносит 10 урона Thundercall.","Активирует Grounding Bolt."],"stats":""},"comeback-kid":{"description":"Когда вы приходите в себя после бессознательного состояния, вас нельзя сбить с ног в течение 5 секунд. (перезарядка 120 секунд)","info":["Вы получаете полный иммунитет к нокауту при пробуждении. Вас всё ещё можно ранить, но не нокаутировать даже на 0%."],"stats":""},"last-resort":{"description":"Вы наносите на 5% больше урона, когда здоровья меньше 25%.","info":["Пока талант активен, вокруг ваших плеч появляются красные частицы."],"stats":"+10 к Рассудку"},"the-eleventh-hour":{"description":"Когда здоровья меньше 15%, ваши мантры не требуют Эфира в течение 11 секунд.","info":["Вопреки описанию, длится 30 секунд с перезарядкой 90 секунд."],"stats":"+10 к Рассудку"},"silencer-s-song":{"description":"Silencer's Blade теперь срабатывает и на ваши мантры.","info":["Срабатывает на все мантры, а не только Galebreathe.","Ускорение от Silencer's Blade может суммироваться, давая очень значительную скорость, если вы попадаете многократной мантрой по удушаемой цели."],"stats":""},"old-habits-die-hard":{"description":"Блок атаки в затянувшихся кадрах блока после неудачного парирования заставляет атаку наносить на 15% меньше урона по Стойке (Posture).","info":[],"stats":"+5 к здоровью"},"thresher-claws":{"description":"Даёт +5% PEN оружия.","info":[],"stats":"+5% PEN оружия"},"leg-shot":{"description":"[Винтовки] Попадание критической атакой ненадолго замедляет врага, делает PvE-врагов Sluggish и отключает любые ускорения, которые они получают, на следующие 10 секунд.","info":["Статус Sluggish снижает урон поражённых целей на 15%."],"stats":""},"stock-bash":{"description":"Ваши атаки на бегу теперь накладывают краткое оглушение (daze) и Stagger на PvE-врагов.","info":["Накладывает оглушение на одну секунду.","Статус Stagger заставляет противника получать на 33% больше урона по Стойке (Posture)."],"stats":""},"tactical-reload":{"description":"Активируйте, чтобы ваша винтовка стреляла пулями в течение 15 секунд.","info":["Перезарядка 90 секунд.","При активации инструмента таланта ваша винтовка получает возможность стрелять пулями на 15 секунд, затем простой 75 секунд.","Физические пули в инвентаре для этого не нужны.","Если вы держите Rosen's Peacemaker, перезарядка составляет 45 секунд, то есть простой всего 30 секунд.","Талант не действует на Rifle Spear."],"stats":""},"impervious-slumber":{"description":"Получение удара в бессознательном состоянии больше не сбрасывает время, которое вы проводите без сознания.","info":[],"stats":""},"breathing-exercise":{"description":"Ваш Рассудок восстанавливается быстрее, когда вы выходите из пугающих ситуаций.","info":["Ваше пассивное восстановление Рассудка увеличивается на 50%.","Рассудок не восстанавливается, пока что-то активно его истощает, например нахождение в Глубинах.","Увеличивает пассивную регенерацию Рассудка: с 0,25/с до 0,375/с днём, с 0,05/с до 0,075/с ночью и с 0,5/с до 0,75/с при отдыхе у костра."],"stats":"+5 к здоровью"},"conquer-your-fears":{"description":"Убийство обитателей глубин немного восстанавливает ваш Рассудок. Когда союзник хватает врага поблизости от вас, вы восстанавливаете Рассудок.","info":["Восстанавливает Рассудок при убийстве монстров в Глубинах; количество зависит от силы монстра.","Вы восстанавливаете Рассудок, когда союзники казнят человекоподобного противника рядом с вами (игрока или моба)."],"stats":"+3 к Рассудку"},"disbelief":{"description":"Сокращает на 30% длительность иллюзий, наложенных на вас. Вдвое сокращает длительность статуса Charmed на вас.","info":["Клонам Visionshaper, которые целятся в вас, длительность сокращается на 30%.","Вдвое сокращает длительность статус-эффекта Charmed.","Tough Love: 2 с -> 1 с","Обычные атаки Overcharm и критическая атака Kyrsieger: 5 с -> 2,5 с","Unnecessary Theatrics (при требованиях): 7 с -> 3,5 с","Dread Whisper и Sing: 7,5 с -> 3,25 с","Самоочарование от Overcharm: 8 с -> 4 с","Charismatic Cast, Allure: 10 с -> 5 с","Chaotic Charm, Charming Spray у Fadetrimmer: 15 с -> 7,5 с","Lasting Charisma (при требованиях): 20 с -> 10 с"],"stats":"+5 к Рассудку"},"intuitive-repairs":{"description":"Ваш «Iron Skin» восстанавливает броню, пока активен.","info":["Iron Skin также восстанавливает природную броню (Natural Armor) от Аспекта и другого таланта."],"stats":""},"metal-absorption":{"description":"Ваш «Iron Hug» также поглощает броню врага.","info":["Iron Hug высасывает 10% текущей прочности брони противника и переносит её вам."],"stats":""},"metal-eater":{"description":"Когда у вас нет Эфира, вы расходуете прочность брони, чтобы применять мантры Ironsing.","info":["Расходует 30% вашей максимальной брони при срабатывании независимо от стоимости Эфира мантры."],"stats":""},"metal-thief":{"description":"Притягивание противника поглощает часть его текущей прочности брони.","info":["Крадёт 2% текущей прочности брони противника за каждый стержень."],"stats":""},"polished-armor":{"description":"Вы получаете на 5% меньше урона, когда ваша броня защищает вас от атаки и её прочность выше 90%. Эти 5% растут до 10% меньшего урона при 100 MTL.","info":["Снижение урона от Polished Armor увеличивается на 0,05% за каждое очко вложения в Ironsing; при требованиях даёт 8,75% снижения урона."],"stats":""},"echoing-lunatic":{"description":"Ваш Ardour Scream теперь вызывает безумие.","info":["Убирает около 10 единиц Рассудка.","Эффект таланта может быть отменён, если Ardour Scream заблокирован."],"stats":"+3 к Рассудку"},"lose-your-mind":{"description":"Чем безумнее вы, тем больше урона наносите. Даёт +15% урона при максимальном безумии.","info":["Бонус к урону начинается при 70% Рассудка (Безумие 1 уровня) и нелинейно растёт с потерей Рассудка, пока не достигнет максимума +15% урона при 0% Рассудка (Безумие 3 уровня).","Точная формула: f(x) = 15 - 15 × (x/0,7)^1,2 {0,7 ≥ x ≥ 0} (x = текущий Рассудок / максимальный Рассудок).","Например, 175 текущего Рассудка при максимуме 321 даст увеличение на 3,89%.","Калькулятор: https://www.desmos.com/calculator/q9hbw3enrw","Прирост Рассудка у Deepbound от убийств мобов в Глубинах снижается."],"stats":"+5 к Рассудку"},"piercing-will":{"description":"Когда ваш Рассудок ниже 35%, вы получаете до +15% PEN к своим атакам. Начиная с 5% PEN, чем ниже Рассудок, тем выше PEN.","info":["Вопреки описанию, даёт бонус PEN 10% при полном безумии.","Бонус к PEN начинает действовать с 35% Рассудка.","Зависит от вашего текущего процента Рассудка, как и Lose Your Mind."],"stats":""},"shared-misery":{"description":"Использование M1 или критической атаки по врагу, пока вы теряете Рассудок, заставляет его терять Рассудок.","info":["Активируется, когда вы активно теряете Рассудок или в течение 15 секунд после использования квестового таланта.","При срабатывании убирает 3% максимального Рассудка цели. Перезарядки у эффекта нет.","Количество урона по Рассудку за удар уменьшается, если у вас меньше 85 Силы воли."],"stats":"+5 к Рассудку"},"brassneck":{"description":"Нокаут врага даёт вам 20% сопротивления урону на 15 секунд.","info":["В PvE срабатывает и при убийстве нечеловекоподобных монстров.","Ранее назывался «Berserker»."],"stats":""},"dragon-s-song":{"description":"Использование мантры после аперкота даёт Эфир.","info":["Даёт +20 Эфира при срабатывании.","Перезарядка 2 секунды."],"stats":""},"full-reset":{"description":"Нокаут врага сбрасывает перезарядки ваших резонансов (Resonance). У эффекта перезарядка 60 секунд.","info":[],"stats":""},"gourmand":{"description":"Сытость и утоление жажды от еды увеличиваются.","info":["Увеличивает прирост сытости и утоления жажды на 20%.","Вместе с бонусом Gourmet Boon увеличивает прирост сытости и утоления жажды от еды на 80%."],"stats":"+5 к грузоподъёмности (Carry Load), +1 к Стойке"},"heavy-haul":{"description":"Враги, которые несут вас, двигаются значительно медленнее. Вы получаете немного меньше урона по Стойке (Posture) от крупных врагов. Своего поймёт свой.","info":[],"stats":""},"martyr":{"description":"Когда вас нокаутируют, враги получают меньше здоровья и Стойки, а союзники вокруг вас получают Martyrdom на 20 с.","info":["Martyrdom даёт +20% урона и снижения урона на 20 секунд.","Martyrdom нельзя выдать игроку, который вас нокаутировал, даже если он ваш союзник. Кроме того, Martyr не считает вас самого союзником, поэтому бонусы на вас не применяются.","Враги, нокаутировавшие вас, восстанавливают лишь половину Стойки и здоровья, которые получили бы обычно (50% -> 25%).","Если у врага есть талант Replenishing Knockout, оба таланта нейтрализуют друг друга, и получается обычная аптечка."],"stats":""},"polite-awakening":{"description":"При выходе из бессознательного состояния ваше здоровье восстанавливается минимум до 15% максимального.","info":[],"stats":"+1 к пассивной Ловкости"},"ready-or-not":{"description":"Первая атака, попавшая по вам вне боя, наносит вдвое меньше урона.","info":[],"stats":""},"replenishing-knockout":{"description":"Вы получаете больше здоровья и Стойки (Posture) за повержение врагов.","info":["Нокаут врагов восстанавливает в 1,5 раза больше вашего здоровья и Стойки (50% -> 75%).","Если у цели есть талант Martyr, оба таланта нейтрализуют друг друга, и получается обычная аптечка."],"stats":""},"ardour-scream":{"description":"Усильте свой крик до вопля с помощью Ardour, подавляя более слабых врагов. Жертвы получают на 12,5% больше урона и на 50% больше урона по Стойке (Posture) на 10 с.","info":["Активируется инструментом Ardour Scream в инвентаре или удержанием и отпусканием горячей клавиши Ardour (H). Перезарядка 15 секунд.","Расходует весь ваш Эфир и требует 100% Эфира для применения. Талант Soulbreaker снижает минимальный Эфир до 40%, но всё равно опустошает всю шкалу Эфира при применении.","Ardour Scream имеет базовый радиус 95 студов, накладывает боевую метку (Combat Tag) и ослабляет всех, кого задел. Радиус можно увеличить на 105 студов талантом Soulbreaker и ещё на 100 студов талантом Destructive Yell от Ascended Outlaw Mask, итого максимум 300 студов.","Вместо того чтобы ослаблять задетых игроков и заставлять их получать больше урона, талант даёт бонус при ударе по противнику под Ardour Scream: эта атака получает бонус к урону 12,5%. Поэтому на Ardour Scream действует потолок модификаторов урона.","Как и все другие инструменты, его можно совмещать (movestack) с любой атакой, не являющейся мантрой, выполняя атаки во время подготовки Ardour Scream.","Шлем Broodplate Helmet заставляет Ardour Scream накладывать 100% анти-лечения (Anti-Heal) на всю длительность через талант Broodlord's Scream.","Комплект Broodplate Set даёт Ardour Scream бесплатно, минуя требования. Кроме того, комплект даёт талант Second Nature, который делает Ardour Scream полностью бесплатным ценой увеличения его перезарядки на 10 секунд."],"stats":"+9 к Рассудку"},"murmur-ardour":{"description":"Применение вашего Soul Murmur, позволяющее направить шёпот (murmur) в чистую силу. Нажмите H.","info":["Пока активно, след от взмаха вашего оружия становится фиолетовым, а оружие издаёт тихий гул.","Если у вас есть Soulbreaker, ваше оружие пассивно излучает фиолетовые молнии. Цвет можно изменить, покрасив косметику вашей Клятвы.","Увеличивает исходящий урон по Стойке (Posture) от M1 на 20% и снижает входящий урон по Стойке на 15%. Бонус к урону по Стойке действует и на критические атаки с тегом M1.","Даёт бонус к урону +2,5% (+5% с Soulbreaker) для M1 и критических атак с тегом M1. Дополнительно даёт +15% урона для M1 и критических атак с тегом M1, пробивающих блок.","Тратит Эфир, пока активно. Расход Эфира обратно пропорционален вашему уровню и полностью исчезает на уровне мощности 20.","Ardour автоматически отключается, если у вас нет Эфира."],"stats":""},"murmur-rhythm":{"description":"Применение вашего Soul Murmur, позволяющее воспринимать тонкий шёпот (murmur), исходящий от всего вокруг. Нажмите G в приседе.","info":["Отмечает цветным кругом расположение всех ближайших монстров, NPC и игроков, даже сквозь стены. Пока активно, экран становится чёрно-белым.","Цвет указывает диапазон здоровья цели: красный = ≤33%, жёлтый = от 34% до 66%, серый = ≥67%.","Отображение цвета отключено у игроков с соответствующим талантом: они всегда отображаются серыми независимо от здоровья.","Rhythm прекращается досрочно, если вы встаёте (без таланта Soulbreaker) или получаете урон."],"stats":""},"murmur-tacet":{"description":"Применение вашего Soul Murmur, позволяющее заглушить собственный шёпот (murmur). Нажмите T в приседе.","info":["При использовании вокруг вашего персонажа создаётся сфера, обычно называемая «пузырём Tacet». Для всех вне пузыря вы невидимы.","Размер пузыря Tacet обратно пропорционален вашему уровню и стату скрытности: чем выше уровень и больше скрытности, тем он меньше.","В Tacet даётся 400 единиц скрытности, что делает вас фактически невидимым для PvE-врагов; иногда даже физическое касание NPC не вызывает агро. Однако радиус потери агро всё ещё довольно велик, даже в Tacet, так что, возможно, придётся убежать, прежде чем снова включать Tacet.","Tacet отключается во время Hell Mode, Diluvian и Depths Trials.","Если 1 секунду не приседать, Tacet отключится. После ~0,5 с бега Tacet отключится. Атака, получение удара или использование Formless у Soulbreaker мгновенно отключают Tacet."],"stats":""},"armor-conserver":{"description":"Вы теряете на 15% меньше брони при получении удара.","info":["Суммируется мультипликативно с другими источниками того же эффекта.","Не влияет на природную броню от Exoskeleton и Chitin."],"stats":""},"lightweight":{"description":"Вы двигаетесь быстрее, когда у вашей брони заканчивается прочность.","info":["Когда прочность брони 0% или вы носите наряд Stranded, скорость передвижения увеличивается на 25%.","Это бонус к мобильности, а НЕ ускорение (Speed Boost)."],"stats":"+3 к пассивной Ловкости"},"padded-armor":{"description":"Пока ваша броня сломана (или у вас нет брони), вы получаете на 5% меньше урона.","info":["Выдаваемая дробящая броня это показатель сопротивления брони, и он суммируется мультипликативно с другими источниками дробящей брони.","Активируется безусловно, если вы используете Stranded."],"stats":"+3% дробящей брони"},"steel-scales":{"description":"Вы получаете дополнительно на 5% меньше урона, когда ваша броня сломана.","info":["Выдаваемая рубящая броня это показатель сопротивления брони, и он суммируется мультипликативно с другими источниками рубящей брони.","Активируется безусловно, если вы используете Stranded."],"stats":"+3% рубящей брони"},"captain-etrea":{"description":"Движение при блоке щитом больше не замедляет вас.","info":["Работает с Jus Karita.","Вопреки описанию «со щитом», талант работает и при блоке без экипированного щита, полностью убирая замедление от блока."],"stats":""},"fists-of-fortitude":{"description":"Каждые 6 попаданий кулаками создают щит стойкости, снижающий входящий урон на 15%.","info":["При срабатывании вокруг персонажа на 10 с появляется жёлтый пузырь, затем перезарядка 70 с после окончания эффекта.","Срабатывает только от попаданий M1 и критических атак с тегом M1 кулачным оружием.","Нейтральная критическая атака Wraithclaw отлично подходит для этого таланта, потому что она многократная."],"stats":""},"defensive-stance":{"description":"Чем ниже ваше здоровье, тем больше кадров парирования вы получаете.","info":[],"stats":""},"duelist-s-lunge":{"description":"Атаки на бегу наносят увеличенный урон по Стойке (Posture). После попадания критической атакой ваша следующая атака на бегу получает увеличенную дальность.","info":["Атаки на бегу рапирами наносят на 35% больше урона по Стойке.","После попадания критической атакой следующая атака рапирой на бегу получает +2 студа дальности."],"stats":""},"frenzied-dance":{"description":"Чем больше у вас текущей Стойки (Posture), тем больше вы наносите урона сквозь блок (chip) и урона по Стойке.","info":["Если ваша текущая Стойка 70% или выше, ваш урон по Стойке увеличивается на 33%, а урон сквозь блок на 20%.","Ничего не делает, если ваша текущая Стойка ниже 70%."],"stats":""},"pressure-skewer":{"description":"Flourish против врага заставляет ваши M1 наносить дополнительный урон сквозь блок (chip), кровопотерю и 3 дополнительных единицы чистого урона, пока вы не получите урон.","info":["Пока активно, к лёгким атакам рапирой и критическим атакам с тегом M1 применяются бонусы: потеря крови +50%, +25% урона сквозь блок и +3 чистого урона."],"stats":""},"fast-blade":{"description":"Продлевает ускорение, получаемое за успешное парирование атаки.","info":["Увеличивает эффективность ускорения при парировании с 12,5% до 27,5%, а длительность с 0,5 с до 1,5 с."],"stats":"+1 к пассивной Ловкости"},"lightspeed-reflexes":{"description":"Когда вы парируете атаку после финта атаки, вы получаете ускорение на 5 с.","info":["Даёт ускорение 60% на 5 секунд при срабатывании. Не суммируется с врождённым ускорением от парирования и ускорением от Fast Blade."],"stats":"+1 к пассивной Ловкости"},"speed-emission":{"description":"Вы получаете ускорение на 5 с и накладываете на противника замедление на 3 с.","info":["Даёт ускорение 30% и накладывает замедление 15%.","Перезарядка 5 секунд."],"stats":""},"all-knowing":{"description":"Ваш Prediction теперь игнорирует требование по дальности для отражения атак.","info":[],"stats":""},"successive-prediction":{"description":"Предсказание атаки ненадолго позволяет предсказать ещё одну.","info":["После успешного Prediction все последующие попадания в очень короткое окно тоже будут отражены.","Позволяет отразить целиком быстрые атаки с множественными попаданиями."],"stats":""},"twelve-steps-ahead":{"description":"Успешный Prediction вдвое сокращает перезарядку до минимума 2 с. Промах вдвое увеличивает перезарядку до максимума 30 с. Эффект суммируется до 30 секунд.","info":["Пояснение к описанию: успешный Prediction (успешное отражение атаки) вдвое сокращает текущую перезарядку (минимум 2 с), а промах Prediction (неудачное отражение) вдвое увеличивает текущую перезарядку (максимум 30 с и больше). В обоих случаях новая перезарядка (после успеха или промаха) становится новой базой для следующего срабатывания. Перезарядка Prediction возвращается к базовой, если 30 секунд им не пользоваться.","Эффект требует, чтобы противник был в пределах 90 студов от вас.","За каждое очко Интеллекта ниже 80 максимальная перезарядка Prediction увеличивается на 0,125 с; максимум 33,125 с при 55 Интеллекта."],"stats":""},"christmas-miracle":{"description":"Награда магазина рождественского мода. Восстанавливает сытость и утоляет жажду. «Огромное спасибо, K1!» Хех, не за что, ребята. Всё в рабочий день.","info":[],"stats":""},"arc-module-dash":{"description":"Ваши рывки становятся реактивными (Jet Dashes), позволяя атаковать во время рывка.","info":["Реактивные рывки уносят гораздо дальше обычных.","Также позволяет игроку бить M1 во время рывка, досрочно завершая его."],"stats":""},"arc-module-eject":{"description":"При пробитии блока вы катапультируетесь из костюма.","info":["Если ваша Стойка (Posture) в Arc Suit дошла бы до 100%, вы мгновенно катапультируетесь вместо пробития блока, отлетая назад и избегая оглушения.","После катапультирования из Arc Suit ваша Стойка устанавливается на 50%."],"stats":""},"arc-module-enhance":{"description":"Ваши мантры Arcwarder наносят увеличенный урон.","info":["Увеличивает базовый урон Arc Wave на 25%.","Увеличивает базовый урон Arc Beam на 50%.","Поскольку Enhance увеличивает базовый урон мантры, он обходит потолок модификаторов урона и повышает эффективность ваших обычных модификаторов, давая им более высокий базовый урон."],"stats":""},"arc-module-guard":{"description":"Вы можете блокировать атаки с любого направления, и вас нельзя ударить в спину.","info":[],"stats":""},"arc-module-leap":{"description":"Удержание пробела после двойного прыжка подбрасывает вас вверх на короткое время.","info":["Позволяет делать двойной прыжок в Arc Suit.","Перезарядка 10 секунд. В бою перезарядка увеличивается до 15 секунд."],"stats":""},"arc-module-null":{"description":"Исходящие и входящие эффекты зачарований аннулируются. Можно переключать клавишей N.","info":["Переключение Null вкл/выкл имеет перезарядку 5 секунд.","Переключение сопровождается звуком.","Нельзя понять, активен ли он, пока вы не попытаетесь применить зачарование или не получите его удар.","Влияет только на зачарования оружия."],"stats":""},"oath-arcwarder":{"description":"Вы клянётесь быть щитом для своих товарищей, с гордостью носить своё облачение и служить общему делу. От каждого по способностям, каждому по потребностям.","info":["См. Oath: Arcwarder."],"stats":"+1 универсальный слот мантры, +2 боевых слота мантр, +5% PEN"},"float-like-a-butterfly":{"description":"Пока активна True Strength, отмените воздушный рывок, чтобы войти в неистовство ударов.","info":["Перезарядка 5 секунд."],"stats":""},"lithe-step":{"description":"При спринте отмените перекат и мгновенно исчезните, рванув с непревзойдённой скоростью.","info":["Делает игрока ненадолго невидимым, как Rush of Ancients у Jetstriker.","Lithe Step не даёт кадров неуязвимости вашему уклонению, но даёт заметное ускорение во время него.","Перезарядка Lithe Step 3 секунды. В True Strength перезарядка сокращается до 1 секунды."],"stats":""},"oath-bladeharper":{"description":"Вы клянётесь носить свои клинки как инструмент, отдаваясь любому делу, к которому они приведут. Сведите бесконечное число возможностей перед собой к единственной. Клинок хранит вас так же, как вы храните его.","info":["См. Oath: Bladeharper."],"stats":"+3 боевых слота мантр, +5% PEN"},"reveal":{"description":"Откройте душу и явите свою истинную силу.","info":["Даёт инструмент таланта. При использовании вы вонзаете оружие в себя, включая True Strength. Повторное использование инструмента выключает True Strength.","Пока активно состояние True Strength от Reveal, вы пассивно накапливаете на себе увядание (Wither).","Если здоровье опускается ниже 10%, Reveal автоматически выключается и не может быть включён снова, пока здоровье не станет выше 10%.","Как ни странно, Reveal активирует эффекты, требующие получения урона, например Prediction, хотя Reveal на деле не наносит урон. Для этого не нужно, чтобы текущее здоровье заменялось увяданием; другие источники наложения Wither/True Strength так не делают."],"stats":""},"soaring-storm":{"description":"Усильте свои аперкоты путём клинка после Lithe Step, Flourish или применения умения Клятвы.","info":["В True Strength условие срабатывания снимается, а урон увеличивается.","Применимо ко всем видам аперкотов, включая мантры вроде Rising Flame, Round Spark Skyshatter Kick или некоторые критические атаки оружия, например Wraithclaw."],"stats":""},"untouchable":{"description":"Наносите подряд удары по противнику, не получая урона, и на короткое время явите свою True Strength.","info":["При срабатывании Untouchable вы входите в состояние True Strength на 15 секунд.","Untouchable требует 10 «стаков Untouchable». Попадание любого источника урона, кроме урона по себе, сбрасывает все стаки Untouchable. Нельзя набирать стаки, пока активна True Strength.","Попадание атаками оружия даёт по 2 стака.","Попадание не-оружейными атаками (горение, мантры, извержения и т. д.) даёт по 1 стаку. Кровотечение стаки не накапливает."],"stats":""},"anchor-shock":{"description":"Ваш Blightshock не даёт целям использовать мантры мобильности.","info":["Ставит мантры мобильности противника на перезарядку 3 секунды каждый раз, когда Blightshock накладывается мантрой Blightsurger.","Не срабатывает на Blightshock от оружия Sovereign Bangle."],"stats":""},"blight-pierce":{"description":"Ваши атаки Blightshock пробивают гиперброню врагов и получают больше проникновения.","info":["Blightshock теперь работает как обычный шок (Shock), отменяя гиперброню (Hyperarmor).","Sovereign Bangle (эксклюзивное оружие Blightsurger) и мантры Blightsurge получают +15% PEN.","Поскольку мантры Blightsurger наносят чистый урон Клятвы, PEN у ваших мантр важен только в особых случаях, например против игрока без Клятвы или того, кто использует Reinforce."],"stats":""},"blighted-touch":{"description":"Попадание обычными атаками во время Sovereign State теперь накладывает Blightshock.","info":["Это позволяет вашему Sovereign Bangle накладывать увядание (Wither) при попадании."],"stats":""},"blightlash":{"description":"Дальность ваших взмахов увеличивается во время Sovereign State.","info":["Увеличивает дальность Sovereign Bangle с 6 до 7."],"stats":""},"oath-blightsurger":{"description":"Кулаки и буря. Владейте священной молнией, разрывайте врагов и оставляйте их увядшими.","info":["См. Oath: Blightsurger."],"stats":"+2 боевых слота мантр, +1 универсальный слот мантры, +5% PEN"},"sovereign-state":{"description":"Физические попадания наполняют вашу шкалу Blight. При полной шкале вы входите в состояние Blight, которое меняет вашу критическую атаку и усиливает умения Blightsurge.","info":["У набора шкалы Blight нет перезарядки. Попадание мантрами Blightsurger даёт 15% шкалы Blight, обычными атаками 10%, критическими атаками оружием, мантрами Thundercall или Galebreathe 5% за попадание.","При полной шкале Blight Sovereign State длится 12,5 секунд.","У Sovereign State перезарядка активации 10 секунд после окончания действия.","Нажмите X при шкале Blight не менее 30%, чтобы активировать Sovereign State. В Sovereign State шкала Blight пассивно убывает, и состояние нельзя отключить.","В Sovereign State ваше оружие заменяется на Sovereign Bangle.","В этом состоянии Skycrash автоматически используется дважды подряд.","Увеличивает урон увяданием от Sovereign Drive и Warp Kick."],"stats":""},"all-seeing-eye":{"description":"Мистический глаз, через который вы теперь видите мир, воспринимает невоспринимаемое. Невидимые враги подсвечиваются.","info":["Невидимые игроки и монстры выдаются значком Blindseer Eye, показывающим их текущее положение.","В частности, раскрывает игроков под эффектами Static Flash Clone, Tacet, анимации применения Illusory Servants, Beast Burrow, порталов и других эффектов невидимости.","Умения с захватом цели (например, Ice Daggers) могут целиться в невидимых существ, пока у вас есть этот талант.","Работает на любого невидимого, включая вас и монстров.","Поскольку ваше тело отрисовывается в виде от первого лица, All-Seeing Eye срабатывает и на вас. Вихревой эффект можно увидеть, посмотрев вниз."],"stats":""},"oath-blindseer":{"description":"Вы клянётесь не позволить ужасам мира пронзить вашу туго завязанную повязку на глазах. Всё лишь таково, каким мы выбираем это воспринимать.","info":["См. Oath: Blindseer.","Примечание: после получения этой Клятвы вы можете убрать таланты-предпосылки."],"stats":"+1 боевой слот мантры, +1 слот мантры поддержки, +1 универсальный слот мантры, +5% PEN, +10 к Рассудку"},"adept-bloodrender":{"description":"Теперь вы можете получать мантры Bloodrender с 1 звездой.","info":["Этот талант будет снят, если вы перестанете соответствовать его требованиям."],"stats":""},"bloodrender":{"description":"Даёт вам способность повелевать кровью как Bloodrender. Ваши мантры Bloodrend восстанавливают вашу кровь, крадут кровь и накладывают «Blood Poisoning».","info":["Blood Poison это эффект, накладываемый поверх шкалы крови противника. При достижении определённых порогов Blood Poison (доля шкалы крови, покрытая ядом) вы накладываете на цель ослабления и можете активировать некоторые условные таланты.","Blood poison пассивно убывает со временем, поэтому для поддержания ослаблений нужно постоянно давить на противника.","Подробнее см. Bloodrend."],"stats":""},"expert-bloodrender":{"description":"Теперь вы можете получать мантры Bloodrender с 2 звёздами.","info":["Этот талант будет снят, если вы перестанете соответствовать его требованиям."],"stats":""},"master-bloodrender":{"description":"Теперь вы можете получать мантры Bloodrender с 3 звёздами. Ваша максимальная ёмкость крови на 25% больше, чем у обычного человека. Вы быстрее восстанавливаете кровь.","info":["Этот талант будет снят, если вы перестанете соответствовать его требованиям."],"stats":"+5 к здоровью"},"chainlash":{"description":"После Flourish вы получаете возможность на 5 секунд призвать цепь на врага правой кнопкой мыши. Это позволяет хлестнуть цепью, схватить врагов и притянуть их к себе для сокрушительного пинка.","info":["Нажатие M2 после Flourish накладывает на противника Enchained и притягивает его к вам. M1 после притягивания выполняет Crushing Kick с высоким уроном.","Притягивание возвращает цели в место, где вы применили Flourish, и на время лишает их возможности двигаться.","Chainlash работает только на целях в цепи; если цель достаточно быстро разорвёт цепь, Chainlash отменится.","Работает с другими талантами «при Flourish».","Пинок сбивает цели в ragdoll и отбрасывает их в направлении вашего взгляда, но не может бить сквозь стены (wallbang).","Не срабатывает на нечеловекоподобных целей."],"stats":""},"oath-chainwarden":{"description":"Вы клянётесь быть цепью, что сковывает нечестивых и тащит их обратно туда, где им место. В этом мире есть те, кто не должен быть свободен.","info":["См. Oath: Chainwarden."],"stats":"+2 боевых слота мантр, +1 универсальный слот мантры, +5% PEN"},"perpetual-wrath":{"description":"Раскройте истинную силу Restrain. Каждое последующее попадание увеличивает его урон.","info":["Сковывание целей и попадание Restrain по скованным целям добавляет 1 стак Perpetual Wrath.","Каждый стак Perpetual Wrath увеличивает урон Restrain (мантры) на 8; максимум 4 стака, +32 урона. При максимуме стаков Restrain получает дополнительный визуальный и звуковой эффект.","Все стаки Perpetual Wrath сбрасываются, если цепь рвётся."],"stats":""},"hidden-tendril":{"description":"Попадание любой физической мантрой накладывает на противника Hidden Tendril.","info":["Hidden Tendril накладывают физические критические атаки, аперкоты, Flourish и большинство мантр без школы."],"stats":"+10 к Эфиру"},"oath-contractor":{"description":"Ваше сердце отныне навеки связано с Zi'eer, 4-м Пророком Министерства. Вы клянётесь служить его воле, чего бы это ни стоило.","info":["См. Oath: Contractor."],"stats":"+2 боевых слота мантр, +1 универсальный слот мантры, +5% PEN"},"string-trick":{"description":"Стягивает вместе любых двух противников, на которых вы наложили Hidden Tendril.","info":["Не срабатывает на нечеловекоподобных. При срабатывании наносит небольшой урон."],"stats":""},"absolute-radiance":{"description":"Нанесение урона мантрами Dawnwalker ненадолго делает вас неуязвимым ко всем стихийным эффектам.","info":["Во время Absolute Radiance на вас нельзя наложить стихийные статус-эффекты.","Это включает: горение, охлаждение, шок, одышку, удушье, Metal Rods и Fear the Dark (однако Fear the Dark, вызванный Night Terror, обходит этот эффект)."],"stats":""},"luminous-flash":{"description":"После нанесения определённого количества урона в Absolute Radiance вы получаете шанс усилить свои удары чистым светом.","info":["Во время Absolute Radiance ваши M1 имеют небольшой шанс вызвать Luminous Flash, увеличивая урон на 50% в PvP или 75% в PvE (потолок модификаторов урона)."],"stats":""},"oath-dawnwalker":{"description":"Вы клянётесь вечно тянуться к сияющему Свету. Нет тени, которую не изгнало бы ваше сияние.","info":["См. Oath: Dawnwalker."],"stats":"+3 боевых слота мантр, +5% PEN"},"protagonist-syndrome":{"description":"Хватка тьмы бессмысленна перед вашим ослепляющим светом. Ваши мантры Dawnwalker усиливаются после попадания по вам Shadowcast.","info":["Увеличивает урон ваших мантр Dawnwalker на 30% после получения урона Shadowcast.","Урон по себе от Shade Devour безтиповой, поэтому этот эффект не активирует."],"stats":""},"barber-s-skillset":{"description":"Какую причёску делаем сегодня?","info":["Даёт инструмент таланта, открывающий устаревшую версию интерфейса парикмахера. Из-за устаревшего варианта интерфейса в нём всего 4 слота причёсок.","При выборе других: меняет причёску, которую накладывают при попадании ваши мантры Fadetrimmer.","При выборе себя: меняет вашу собственную причёску.","Не используйте ID причёсок, которые можно счесть оскорбительными. За это можно получить бан. Вы отвечаете за то, какие причёски выдаёте."],"stats":""},"hair-products":{"description":"Что в этих штуках?","info":["Даёт инструмент таланта, показывающий всплывающее меню, где можно выбрать лак для волос: горючий (Flammable), очаровывающий (Charming) или восстанавливающий (Revitalizing). Ваш другой талант изменится на выбранный эффект."],"stats":""},"hair-spray":{"description":"Нанесите ваши средства для волос.","info":["Даёт инструмент таланта Hair Spray, применяющий лак, выбранный во всплывающем меню.","Горючий (Flammable):","Поджигает противника или вызывает Eruption при попадании. Перезарядка 10 с.","Не наносит урон напрямую, не наносит урон по Стойке и не восстанавливает Стойку при парировании.","Можно парировать и блокировать, но горение накладывается на первом тике, то есть если вы не парируете с точностью до кадра, парирование ничего не даст.","Очаровывающий (Charming):","Очаровывает противника на 15 секунд при попадании. Перезарядка 10 с.","Не наносит урон, не наносит урон по Стойке и не восстанавливает Стойку при парировании.","Можно парировать и блокировать, но очарование накладывается на первом тике, то есть если вы не парируете с точностью до кадра, парирование ничего не даст.","Может заменить талант Lasting Charisma в билдах с малой или нулевой Харизмой.","Восстанавливающий (Revitalizing):","Лечит на фиксированные 10% здоровья любые задетые цели. Перезарядка 10 с.","Может лечить не-союзников и даже мобов.","Нельзя парировать и блокировать.","Может стать уронным инструментом с талантом Bloodrend."],"stats":""},"oath-fadetrimmer":{"description":"Вы клянётесь вечно оттачивать точность с ножницами. Больше никогда не будет инцидентов с чёлкой.","info":["См. Oath: Fadetrimmer."],"stats":"+2 боевых слота мантр, +1 универсальный слот мантры, +5% PEN"},"adept-flamecharmer":{"description":"Теперь вы можете получать мантры Flamecharmer с 1 звездой.","info":["Этот талант будет снят, если вы перестанете соответствовать его требованиям."],"stats":""},"expert-flamecharmer":{"description":"Теперь вы можете получать мантры Flamecharmer с 2 звёздами.","info":["Этот талант будет снят, если вы перестанете соответствовать его требованиям."],"stats":""},"flamecharmer":{"description":"Даёт вам способность повелевать огнём как Flamecharmer.","info":[],"stats":""},"master-flamecharmer":{"description":"Теперь вы можете получать мантры Flamecharmer с 3 звёздами.","info":["Этот талант будет снят, если вы перестанете соответствовать его требованиям."],"stats":"+5 к здоровью"},"adept-frostdrawer":{"description":"Теперь вы можете получать мантры Frostdrawer с 1 звездой.","info":["Этот талант будет снят, если вы перестанете соответствовать его требованиям."],"stats":""},"expert-frostdrawer":{"description":"Теперь вы можете получать мантры Frostdraw с 2 звёздами.","info":["Этот талант будет снят, если вы перестанете соответствовать его требованиям."],"stats":""},"frostdrawer":{"description":"Даёт вам способность повелевать льдом как Frostdrawer.","info":[],"stats":""},"master-frostdrawer":{"description":"Теперь вы можете получать мантры Frostdraw с 3 звёздами.","info":["Этот талант будет снят, если вы перестанете соответствовать его требованиям."],"stats":"+5 к здоровью"},"adept-galebreather":{"description":"Теперь вы можете получать мантры Galebreathe с 1 звездой.","info":["Этот талант будет снят, если вы перестанете соответствовать его требованиям."],"stats":""},"expert-galebreather":{"description":"Теперь вы можете получать мантры Galebreathe с 2 звёздами.","info":["Этот талант будет снят, если вы перестанете соответствовать его требованиям."],"stats":""},"galebreather":{"description":"Даёт вам способность повелевать ветром как Galebreather.","info":[],"stats":""},"neural-overload":{"description":"Вы можете вставлять до 4 копий каждого ингредиента мантры вместо лимита в 3.","info":["Лимит модификаторов мантры (количество копий одного модификатора) увеличивается с 3 до 4 (например, максимум 3 Crystal Lens -> максимум 4 Crystal Lens).","Если убрать этот талант после модификации мантр, уже установленные модификаторы не изменятся, и выгода сохранится.","Не увеличивает жёсткий максимальный лимит модификаций мантры."],"stats":""},"conditioned-runner":{"description":"Вы получаете на 5-15% меньше урона. Размер снижения урона зависит от вашей Ловкости и от того, как долго вы бежите.","info":["Эффект действует только во время спринта.","Сейчас работает с ошибкой и не действует."],"stats":"+1 к пассивной Ловкости"},"fisher-s-lure":{"description":"Рыба быстрее клюёт на вашу леску.","info":["Сокращает время до поклёвки."],"stats":""},"hook-line-and-sinker":{"description":"Когда кто-то попался на вашу леску, ему гораздо труднее сорваться.","info":["Увеличивает время на прохождение мини-игры рыбалки."],"stats":""},"proficient-baiting":{"description":"Заброс удочки будоражит морскую жизнь, снижая шанс вытащить мусор.","info":["Резко повышает шанс поймать рыбу вместо мусорных предметов.","Это невольно снижает шанс выловить сундуки, так как рыба становится более частой."],"stats":""},"collapsed-lung":{"description":"Пробитие блока противника перекрывает ему возможность использовать Vent на 8 с; длительность зависит от Силы. PvE-враги вместо этого получают Collapsed.","info":["Длительность блокировки Vent растёт с вложением вплоть до требования: эффект длится 8 секунд при 100 Силы и теряет 0,04 с за каждое очко вложения ниже 100.","При 75 Силы Collapsed Lung длится 7 секунд.","Статус Collapsed снижает урон по Стойке (Posture), который поражённые цели наносят вам, на 40%."],"stats":""},"devastating-power":{"description":"Вы получаете дополнительный Эфир за каждую мантру в вашем арсенале.","info":["Вы получаете 10 Эфира за каждую имеющуюся у вас мантру. Неэкипированные мантры тоже дают Эфир."],"stats":""},"horn-of-authority":{"description":"Отмечайте убегающих заключённых.","info":["Даёт инструмент таланта, который трубит в рог, накладывая боевую метку (Combat Tag) и подсвечивая убегающих заключённых."],"stats":""},"authority-ensign":{"description":"Вы член Authority, направленный в Eastern Luminant. У вас могут возникнуть проблемы с местными фракциями, и вы должны становиться сильнее, укрепляя позиции Authority.","info":[],"stats":""},"reinforced-armor":{"description":"Входящий PEN снижается на 30%.","info":["Эффект Reinforced Armor ослабевает, если вы не выполняете требования таланта: теряется 0,8% сопротивления PEN за каждое очко ниже 90 Телосложения; минимум 10% сопротивления PEN при 65 Телосложения.","Иначе можно сказать так: 10 + 0,8 × (Телосложение - 65) = эффективность RA, при этом значение не может быть ниже 10% или выше 30%.","Расчёт PEN: входящий PEN × (1 - эффективность Reinforced Armor %) = сниженный входящий PEN.","Например, 50% PEN против 30% Reinforced Armor и 50% физической брони:","База: 50% PEN против 50% физической брони; 50 × (1 - 50%) = 25% сопротивления после PEN.","Reinforced Armor: 50% PEN против 30% RA; 50 × (1 - 30%) = 35% PEN. 35% PEN против 50% физической брони = 50 × (1 - 35%) = 32,5% сопротивления после PEN."],"stats":""},"armored-plating":{"description":"Наденьте на броню дополнительные пластины, которые дают вам 50 временного здоровья каждый раз, когда вы вступаете в бой. Из-за веса этих пластин ваша скорость постоянно снижена.","info":["Вы получаете 50 временного здоровья при начале боя ценой пассивного штрафа к скорости передвижения даже вне боя."],"stats":""},"crossguard":{"description":"Если вы используете меч, вы получаете 10% урона сквозь блок (chip) против других противников с мечами.","info":[],"stats":""},"oppressive-force":{"description":"При использовании оружия из Merit Armory вы получаете уникальный двухударный Flourish, который не отбрасывает противников и оглушает их.","info":["Первый удар наносит ваш обычный урон M1 и урон по Стойке, второй удар наносит 80% масштабированного урона оружия и 7 урона по Стойке.","Урон и урон по Стойке второго удара усилить нельзя.","Второй удар происходит только если попал первый. То есть он не продолжается при блоке.","Второй удар не считается ударом оружия, поэтому игнорирует показатель Chip у оружия и не может активировать зачарования или таланты «при Flourish».","Второй удар не срабатывает на нечеловекоподобных целей.","Этот эффект могут активировать следующие виды оружия: Adretian Axe, Big Brother, Cavalry Saber, Central Dirk, Duskguard Axe, Halberd, Inquisitor's Greatsword, Inquisitor's Thorn, Markor's Inheritor, Officer Saber, Rifle Spear, Rite of Authority, Sovereign's Punishment и Warden Ceremonial Sword. Кроме того, его активируют и сплавные (Alloyed) версии всего этого оружия.","Несмотря на то, что их можно найти в оружейной, Battleaxe, Stiletto и Sword не активируют этот эффект."],"stats":""},"riot-shield":{"description":"Пока вы сражаетесь с двумя или более противниками и используете щит, общий получаемый вами урон сквозь блок (chip) снижается на 40%.","info":["Даёт 40% снижения урона сквозь блок; не уменьшает процент chip противника на 40."],"stats":""},"steel-tread":{"description":"Вы получаете небольшое сопротивление отбрасыванию, а также сопротивление урону от атак, сбивающих вас в ragdoll.","info":[],"stats":""},"agility-unbounded":{"description":"Вы обрели способность превзойти свои пределы и развить Ловкость до максимума.","info":["Получение этого таланта в любой момент убирает квестовую часть его получения у всех последующих персонажей: вы сразу получаете талант при достижении требования по атрибуту.","Если выбранный вами Аспект (Aspect) по умолчанию даёт повышенную Ловкость, а у вас нет Multifaceted, требование по Ловкости для получения этого таланта увеличивается на 2-3."],"stats":""},"bloodrend-unbounded":{"description":"Вы обрели способность превзойти свои пределы и развить Bloodrend до максимума.","info":["Этот талант будет потерян, если вы перестанете соответствовать его требованиям."],"stats":"+10 к здоровью"},"charisma-unbounded":{"description":"Вы обрели способность превзойти свои пределы и развить Харизму до максимума.","info":["Получение этого таланта в любой момент убирает квестовую часть его получения у всех последующих персонажей: вы сразу получаете талант при достижении требования по атрибуту.","Если выбранный вами Аспект (Aspect) по умолчанию даёт повышенную Харизму, а у вас нет Multifaceted, требование по Харизме для получения этого таланта увеличивается на 2-3."],"stats":""},"flamecharm-unbounded":{"description":"Вы обрели способность превзойти свои пределы и развить Flamecharm до максимума.","info":["Этот талант будет потерян, если вы перестанете соответствовать его требованиям."],"stats":"+10 к здоровью"},"fortitude-unbounded":{"description":"Вы обрели способность превзойти свои пределы и развить Телосложение до максимума.","info":["Получение этого таланта в любой момент убирает квестовую часть его получения у всех последующих персонажей: вы сразу получаете талант при достижении требования по атрибуту.","Если выбранный вами Аспект (Aspect) по умолчанию даёт повышенное Телосложение, а у вас нет Multifaceted, требование по Телосложению для получения этого таланта увеличивается на 2-3."],"stats":""},"frostdraw-unbounded":{"description":"Вы обрели способность превзойти свои пределы и развить Frostdraw до максимума.","info":["Этот талант будет потерян, если вы перестанете соответствовать его требованиям."],"stats":"+10 к здоровью"},"galebreathe-unbounded":{"description":"Вы обрели способность превзойти свои пределы и развить Galebreathe до максимума.","info":["Этот талант будет потерян, если вы перестанете соответствовать его требованиям."],"stats":"+10 к здоровью"},"heavy-weapons-unbounded":{"description":"Вы обрели способность превзойти свои пределы и развить атрибут «тяжёлое оружие» до максимума.","info":[],"stats":""},"intelligence-unbounded":{"description":"Вы обрели способность превзойти свои пределы и развить Интеллект до максимума.","info":["Получение этого таланта в любой момент убирает квестовую часть его получения у всех последующих персонажей: вы сразу получаете талант при достижении требования по атрибуту.","Если выбранный вами Аспект (Aspect) по умолчанию даёт повышенный Интеллект, а у вас нет Multifaceted, требование по Интеллекту для получения этого таланта увеличивается на 2-3."],"stats":""},"ironsing-unbounded":{"description":"Вы обрели способность превзойти свои пределы и развить Ironsing до максимума.","info":["Этот талант будет потерян, если вы перестанете соответствовать его требованиям."],"stats":"+10 к здоровью"},"light-weapons-unbounded":{"description":"Вы обрели способность превзойти свои пределы и развить атрибут «лёгкое оружие» до максимума.","info":[],"stats":""},"medium-weapons-unbounded":{"description":"Вы обрели способность превзойти свои пределы и развить атрибут «среднее оружие» до максимума.","info":[],"stats":""},"shadowcast-unbounded":{"description":"Вы обрели способность превзойти свои пределы и развить Shadowcast до максимума.","info":["Этот талант будет потерян, если вы перестанете соответствовать его требованиям."],"stats":"+10 к здоровью"},"strength-unbounded":{"description":"Вы обрели способность превзойти свои пределы и развить Силу до максимума.","info":["Получение этого таланта в любой момент убирает квестовую часть его получения у всех последующих персонажей: вы сразу получаете талант при достижении требования по атрибуту.","Если выбранный вами Аспект (Aspect) по умолчанию даёт повышенную Силу, а у вас нет Multifaceted, требование по Силе для получения этого таланта увеличивается на 2-3."],"stats":""},"thundercall-unbounded":{"description":"Вы обрели способность превзойти свои пределы и развить Thundercall до максимума.","info":["Этот талант будет потерян, если вы перестанете соответствовать его требованиям."],"stats":"+10 к здоровью"},"willpower-unbounded":{"description":"Вы обрели способность превзойти свои пределы и развить Силу воли до максимума.","info":["Получение этого таланта в любой момент убирает квестовую часть его получения у всех последующих персонажей: вы сразу получаете талант при достижении требования по атрибуту.","Если выбранный вами Аспект (Aspect) по умолчанию даёт повышенную Силу воли, а у вас нет Multifaceted, требование по Силе воли для получения этого таланта увеличивается на 2-3."],"stats":""},"corrosive-touch":{"description":"Успешная критическая атака или Flourish разъедает часть брони противника.","info":["Высасывает 5% брони противника при срабатывании. Перезарядка 10 секунд, срабатывает только один раз за критическую атаку."],"stats":""},"ghost":{"description":"Уклонение от приёма ненадолго делает вас невидимым; эффект прерывается, если вы атакуете.","info":["Даёт кадры неуязвимости на время невидимости.","Длительность невидимости и кадров неуязвимости 1,2 секунды при 40 и более Ловкости.","Длительность Ghost уменьшается на 0,0133 секунды за каждое очко Ловкости ниже 40; минимум 0,866 секунды при 15 Ловкости.","Перезарядка 20 секунд.","Во время невидимости нельзя парировать атаки."],"stats":"+5 к пассивной Ловкости"},"dazing-finisher":{"description":"Flourish против врагов, очарованных вами, не отбрасывает их назад, а вместо этого оглушает (Dazed).","info":["Накладывает оглушение (Daze) на 3,35 секунды при срабатывании.","Эта длительность уменьшается на 0,02 секунды за каждое очко Харизмы ниже 55; минимум 2,85 секунды при 30 Харизмы.","Не даёт отбрасывать очарованных игроков Flourish, вместо этого оглушая их."],"stats":""},"call-of-the-deep":{"description":"Погрузитесь под волны и вернитесь в Глубины.","info":["Когда инструмент используется в Overworld, проигрывается анимация, и вы погружаетесь в Первый слой. Это не считается утоплением.","Когда инструмент используется в Первом слое, вы телепортируетесь в Castle Light с перезарядкой 1 минута."],"stats":""},"deepbound-contract":{"description":"Вы развиваетесь гораздо быстрее в Глубинах и медленнее в Overworld. Вы можете восстанавливать Рассудок в Castle Light, но на своём испытании всегда будете сталкиваться с самыми сильными врагами.","info":["Вы всегда можете войти в Castle Light и Chariot's Spire, даже если вы тонули или являетесь Contractor.","Турель у Castle Light всё ещё может атаковать вас, если у вас плохая репутация и/или вы Contractor.","Ваше испытание Глубин всегда будет не легче Enforcer.","Вы получаете пассивное восстановление Рассудка в Castle Light.","Вы получаете больше опыта в Глубинах, но в других местах прирост опыта снижен."],"stats":""},"spell-shout":{"description":"Теперь вы выкрикиваете название мантры при применении.","info":["Игрок произносит название применённой мантры в пузыре чата. Например, применение Fire Blade заставит игрока сказать «Fire Blade!».","Переименованные мантры используют новое название. Применение Adrenaline Surge, переименованного в Speed Boost, скажет «Speed Boost!». Переименовать мантры можно, кликнув по названию в меню Mantra Lectern.","Названия мантр автоматически форматируются: заглавные буквы ставятся в начале каждого слова и не могут быть в других местах. Цифры тоже использовать нельзя. Применение мантры «64 palms» скажет «Palms!».","Если название мантры блокируется автоматической модерацией чата Roblox, крик по умолчанию будет использовать исходное название мантры.","Видимость выкриков можно переключать, набрав '/e shout' в чате. Настройка действует на слот. Если видимость отключена, вы не увидите ничьи выкрики.","ВАЖНО: не используйте оскорбительные названия или ругательства для мантр. За это к вам могут быть применены меры модерации.","Оскорбительным считается упоминание расы, пола, сексуальной ориентации, религии и т. д."],"stats":""},"breakthrough-drive":{"description":"Нокаут игрока обновляет перезарядку вашего Glorious Charge и продлевает оба его эффекта на 5 секунд. [перезарядка 90 с]","info":["Нокаут игрока увеличивает на 5 секунд длительность защиты от нокаута и ускорения, которые мантра Glorious Charge даёт вашим соратникам, а также сбрасывает её перезарядку.","Талант срабатывает при каждом нокауте игрока. Если он уже на перезарядке, нокаут добавит ещё один экземпляр перезарядки, больше ничего не делая."],"stats":""},"buster-call":{"description":"Вызовите по рации флот Authority на buster call, обрушив шквал бомбардировки туда, куда посчитаете нужным.","info":["Перезарядка 1 день (24 реальных часа).","Даёт инструмент таланта, который зажигает сигнальную ракету и подсвечивает большую область на земле. После заметной задержки это место бомбят несколько раз, нанося очень высокий урон.","Накладывает горение при попадании.","Не может нокаутировать игроков прямым попаданием, но горение может."],"stats":""},"officer-s-slash":{"description":"Теперь вы получаете дополнительную критическую атаку с оружием из оружейной Authority, пока ваша обычная критическая атака на перезарядке.","info":["Перезарядка 20 секунд.","Эта критическая атака имеет тег M1.","Наносит 35 фиксированного урона без масштабирования, но его можно усилить модификаторами урона.","Работает со следующим оружием: Adretian Axe, Central Dirk, Halberd, Inquisitor's Greatsword, Inquisitor's Thorn, Markor's Inheritor, Officer Saber, Rifle Spear, Sovereign's Punishment и Warden Ceremonial Sword.","Сплавные (Alloyed) версии всего перечисленного оружия тоже активируют этот эффект."],"stats":""},"officer-s-training":{"description":"При использовании меча или рапиры вы получаете на 30% меньше урона по Стойке (Posture) от критических атак.","info":[],"stats":""},"target-focus":{"description":"Враги, которых вы очаровали, получают больше урона от ваших соратников по отряду.","info":["Из-за механики принадлежности Charm настоятельно рекомендуется Lasting Charisma для долгого очарования. Подробнее см. Status Effects."],"stats":""},"ethiron-s-gaze":{"description":"Ваши глаза открылись пустоши. Теперь вы чётче видите сквозь суровый туман бури Eternal Gale.","info":["Значительно уменьшает туман во Втором слое и во время снежных бурь."],"stats":""},"actions-speak-louder":{"description":"Перезарядка вашей критической атаки на 20% короче, но перезарядка вашего резонанса (Resonance) на 20% длиннее. В местах, где ваш Resonance подавлен, вместо этого перезарядка сокращается на 10%.","info":["Перезарядка вашей критической атаки сокращается на 20%, но перезарядка Resonance становится на 20% длиннее.","В Chime of Conflict 1v1 перезарядка критической атаки сокращается вместо этого на 10%.","Этот эффект применяется до Blessed Gem из Critical Engine, что позволяет сократить перезарядку критической атаки на 60% (55% в Chime of Conflict)."],"stats":""},"alloyed-soles":{"description":"Сокращает длительность Knockdown, наложенного на вас.","info":["Сокращает длительность Knockdown на 75%.","Не работает на Knockdown, наложенный на себя, например при парировании вашего Eclipse Kick или заряженных выстрелов из лука."],"stats":""},"angel-s-guise":{"description":"Вы похожи на одного из Sworn Angels.","info":["Даёт иммунитет к атаке Watcher Gaze у Watcher, предотвращая потерю Рассудка, искажение зрения и появление Hollow Angel.","Даёт уникальные диалоги с Watchers: без этого таланта вы не можете с ними говорить.","Ангелы всё равно будут агриться на вас, пока у вас есть этот талант."],"stats":""},"ardenstar-rage":{"description":"Когда здоровья меньше 50%, перезарядки всех мантр сокращаются на 50%. Когда здоровья меньше 20%, все мантры поджигают противника проклятым огнём. Вы постоянно теряете здоровье, пока носите этот нимб в бою.","info":["Сокращение перезарядки суммируется с Blessed Gems, давая 75% сокращения перезарядки.","Cursed Burn это уникальный модификатор горения, увеличивающий урон горения на 75% и делающий пламя фиолетовым.","Получаемый по себе урон можно смягчить источниками лечения, например Curse of the No Life King."],"stats":""},"blind-spot":{"description":"Накладывает слепоту (Blinded) на 5 секунд.","info":["Перезарядка 15 секунд.","Может активироваться Mantle of Enmity."],"stats":""},"blood-convergence":{"description":"Вы получаете на 10% больше лечения из всех источников, когда у вас есть временное здоровье.","info":[],"stats":""},"blood-necrosis":{"description":"Ваши Bloodless Gems лечат на 33% меньше обычного.","info":["Теперь вам нужно 94 масштабированного урона (вместо 63), чтобы вылечить 15 здоровья, и 187 масштабированного урона для 30 лечения.","Про другой талант The No-Life King см. No Limits."],"stats":""},"blood-pact":{"description":"Вы получаете 50 бонусного временного здоровья каждый раз, когда нокаутируете или убиваете врага.","info":["Не даёт несколько экземпляров временного здоровья на цель, а выдаётся при нокауте или автоматической казни."],"stats":""},"blood-plague":{"description":"За каждую лёгкую атаку, нанесённую вами, на противника накладывается один стак Blood Plague. Попадание критической атакой превращает все стаки Blood Plague во временное здоровье, а промах теряет их.","info":["M1 накладывают стаки Blood Plague.","При критической атаке, если она попала, все стаки Blood Plague расходуются, давая 2 + (2 × число стаков) временного здоровья."],"stats":""},"blood-siphon":{"description":"Ваша критическая атака теперь высасывает немного здоровья, лечя вас на 10% нанесённого урона.","info":[],"stats":""},"breeze":{"description":"Вы получаете постоянный бонус +2 к скорости.","info":["Постоянно увеличивает вашу скорость передвижения на +2 студа/с."],"stats":""},"brute-strength":{"description":"Ваш Vent заменяется атакой ударом об землю, отбрасывающей врагов.","info":["Наносит 35 дробящего урона и 20 урона по Стойке (Posture).","Нельзя усилить модификаторами урона, хотя бонусы к урону Vent от Cold Front и Inky Pearls применяются к Brute Strength.","Увеличивает подготовку вашего Vent с 0,25 с до 0,5 с.","Активирует все таланты и эффекты «при Vent»."],"stats":""},"cosmic-connection":{"description":"Все небесные и астральные умения усиливаются.","info":["Увеличивает бонус к урону зачарования Astral на обычных атаках с +20% до +25%.","Вопреки описанию, умения Starkindred не получают бонус к урону."],"stats":""},"crippling-impact":{"description":"Попадание критической атакой по цели при активном Wrath Gem отключает ей Vent на несколько секунд.","info":["Срабатывает при парировании, блоке и уклонении без перезарядки.","Длительность 5 секунд + 0,02 × вложение в Силу; 7 секунд при 100 Силы.","Wrath Gems длятся 9 секунд без визуальной индикации."],"stats":""},"cruentare":{"description":"Увеличивает весь наносимый вами урон кровотечением на 50%. Ваш Whirling Blade теперь лечит вас при попадании.","info":["Whirling Blade лечит вас на 25% нанесённого урона. Попадание по союзникам или призывам игроков всё равно даёт это лечение."],"stats":""},"cursed-pumpkin":{"description":"Удваивает урон ваших тыкв от мантры Pumpkin Pitch. Это увеличивает её перезарядку до 10 секунд.","info":[],"stats":""},"cursed-thorns":{"description":"Монстры, которые бьют вас, получают 20% урона, который наносят вам, но вы также получаете на 10% больше урона от монстров. Попадание Pumpkin Pitch по игроку делает его восприимчивым к этому эффекту на несколько секунд.","info":[],"stats":""},"dancing-steps-of-war":{"description":"При попадании Flourish-атакой вы получаете ускорение и сильно сокращаете перезарядку уклонений на 2 секунды.","info":["Даёт ускорение 35%.","Пока активно, снижает перезарядку уклонения до 0,5 с. Влияет на оба типа уклонения.","Длительность эффекта можно увеличить на 0,5 с активацией таланта Traditional Execution от Etrean Sashimono."],"stats":""},"destructive-yell":{"description":"Ваши Ardour Scream теперь ломают костры вокруг вас и имеют большую область действия.","info":["Ваш Ardour Scream теперь уничтожает все костры в радиусе действия.","Добавляет 100 студов к дальности Ardour Scream (с 95 до 195). Суммируется с +105 студов от другого таланта, итого 300 студов."],"stats":""},"drop-dead":{"description":"Вы получаете меньше урона в приседе.","info":[],"stats":""},"enforcer-s-strength":{"description":"Ваши враги восстанавливают на 20% меньше Стойки (Posture) при парировании.","info":["Враги восстанавливают на 20% меньше Стойки, когда парируют ваши атаки."],"stats":""},"enforcer-s-technique":{"description":"Ваши Flourish наносят на 35% больше урона.","info":["Не работает на выстрелы из оружия во второй руке другого таланта."],"stats":""},"ether-adeptness":{"description":"Ваши мантры теперь наносят дополнительный урон сквозь блок (chip).","info":["Даёт 5% chip мантрам."],"stats":""},"ether-emergency":{"description":"Когда вас бьют и здоровье падает ниже 25%, вы расходуете весь свой Эфир, чтобы получить фиксированный прирост здоровья (лечение зависит от максимального Эфира). Вы ненадолго не можете применять мантры. Перезарядка 5 мин.","info":["Мгновенно восстанавливает 15% вашего максимального Эфира в виде фиксированного здоровья ценой всего вашего Эфира и невозможности применять мантры на короткое время."],"stats":""},"ether-pinpoint":{"description":"Мантры с Might Gem теперь полностью игнорируют бонус к Стойке (Posture) от щитов.","info":["Работает похоже на Shield Breaker, но не требует, чтобы мантра наносила дробящий урон."],"stats":""},"ether-tension":{"description":"Наносите бонусный чистый урон каждый раз, когда пробиваете блок противника мантрой.","info":["Наносит 10 чистого урона."],"stats":""},"fatal-strike":{"description":"Пробитие блока мантрой силы с Wrath Gem сокрушает противника, замедляя его.","info":["Накладывает замедление 50% на 5,5 секунды при срабатывании.","Перезарядка 10 секунд.","Если у вас полный комплект Reinforced War Set, при срабатывании наносит дополнительные 15 чистого урона."],"stats":""},"flashwind":{"description":"Каждый раз, когда срабатывает Air Pressure или Overcharge, вы снова получаете возможность на несколько секунд делать усиленные рывки.","info":["После использования рывка Lightning или Gale все рывки в следующие 3 секунды становятся усиленными. Эти рывки имеют ту же эффективность, что и рывки Lightning и Gale.","Хотя это похоже на рывки Lightning/Gale, это отдельный эффект, игнорирующий их перезарядки."],"stats":""},"focused-strikes":{"description":"Все критические атаки наносят на 15% больше урона по Стойке (Posture).","info":[],"stats":""},"footwork-mastery":{"description":"Попадание критической атакой даёт вам огромное ускорение на 10 секунд.","info":["Перезарядка 45 секунд.","Вопреки описанию, ускорение длится 15 секунд."],"stats":""},"good-luck-charm":{"description":"Заставляет вас чувствовать себя чуть лучше, наверное.","info":["У этого таланта нет эффектов, так что, скорее всего, лучше вы себя не почувствуете."],"stats":""},"gut-rot":{"description":"Flourish усиливает ваш следующий экземпляр анти-лечения (Anti-Heal), удваивая его длительность на всё время действия.","info":[],"stats":""},"i-m-blue":{"description":"Повышает эффективность ваших Blue Gems. Blue это самоцветы, которыми вы пользуетесь.","info":["Увеличивает эффективность Blue Gems на 20% (аддитивно).","С I'm Blue Blue Gems снижают общую стоимость Эфира мантр на 45%."],"stats":""},"inky-pearls":{"description":"Эфир, который вы выбрасываете, покрыт чернильной тенью. Ваш Vent теперь крадёт небольшое количество Эфира.","info":["Окрашивает ваш Vent в чёрный и заставляет его высасывать 47,5 Эфира при попадании.","Увеличивает стоимость Эфира вашего Vent при успешном попадании с 22,5 до 47,5.","Увеличивает урон вашего Vent на 0,5% за каждое очко Shadowcast.","Ваш Vent может активировать таланты Shadowcast при попадании, например пламя Shadowcast у Twisted Puppet и Sightless Still."],"stats":""},"instant-nucleation":{"description":"Вы получаете меньше урона несколько секунд после пробития вашего блока.","info":[],"stats":""},"iron-body":{"description":"Снижает получаемый урон сквозь блок (chip) на фиксированные 10%. Позволяет использовать действия, требующие протез руки.","info":["Необходимо для использования таланта Grapple.","Даёт 10% сопротивления урону сквозь блок, но не уменьшает процент chip входящих атак на 10."],"stats":""},"jester-s-ruse":{"description":"Каждый раз, когда вы получаете урон, есть 10% шанс, что он будет полностью аннулирован. Каждый раз, когда вы наносите урон, есть 10% шанс, что он тоже будет полностью аннулирован.","info":["При срабатывании проигрывается визуальный эффект Cheap Trick от Visionshaper.","Может сработать, если атака заблокирована, парирована или от неё уклонились. Тогда проиграется визуальный эффект, но ничего не произойдёт."],"stats":""},"laminated-armor":{"description":"Снижает весь входящий урон на 2/3 (применяется после множителей урона).","info":["Снижает получаемый урон на фиксированные 2 (3 в Vow of Iron), а не на 66%.","Применяется после модификаторов урона, но до сопротивлений.","Не может снизить урон атаки ниже 1. Атаки, наносящие урон меньше 1, этим талантом не затрагиваются."],"stats":""},"revitalizing-pumpkin":{"description":"Тыквы от Pumpkin Pitch, попавшие в противника, лечат вас на 1% максимального здоровья.","info":[],"stats":""},"fang-and-coil":{"description":"Встаньте на путь змеи.","info":["Позволяет использовать стиль кулачного боя Fang and Coil. См. Fang and Coil."],"stats":""},"landshark":{"description":"Убийство мегалодонта даёт вампиризм вашим атакам на 30 секунд.","info":["Вампиризм не работает в PvP.","Срабатывает при убийстве любого варианта Megalodaunt.","Этот талант получить нельзя."],"stats":""},"intrepid-flame":{"description":"Пламя на вас гаснет вдвое быстрее. Пламя от вашего Flame Within наносит вам гораздо меньше урона.","info":["Вдвое сокращает максимальную длительность любого горения, наложенного на вас. Эффект не действует на Flame Within.","Про другой талант Flame Worshipper Armor см. One With Flame."],"stats":""},"hunter-s-reflexes":{"description":"У вас чуть больше окно уклонения.","info":["Ваше окно уклонения увеличивается на 0,05 с."],"stats":""},"sclerosteosis":{"description":"Каждый раз, когда вы теряете 10% здоровья за один удар, следующий полученный вами урон снижается на 99%. [перезарядка 5 с]","info":["Чтобы эффект сработал, вам нужно потерять 10% здоровья от одного экземпляра урона после смягчения. Поэтому при использовании зачарования Viscosity этот талант никогда не сработает.","Сопротивление урону срабатывает только при получении урона от атак оружием или мантр.","Талант значительно менее эффективен против многократных ударов, так как урон от каждого удара вряд ли составит 10% максимального здоровья, а сопротивление в любом случае повлияет только на первый экземпляр урона.","Хотя снятие других источников сопротивления урону повысило бы вероятность срабатывания, это не гарантировано и не рекомендуется, так как большинство атак не наносят достаточно урона, чтобы преодолеть порог в 10% максимального здоровья. Аналогично, хотя урон по себе может активировать талант, намеренно получать урон по себе для этого не рекомендуется.","При срабатывании сопротивления ненадолго накладывается визуальный эффект, похожий на Reinforce."],"stats":""},"imperium-kata":{"description":"Овладейте продвинутой формой боевых искусств Legion.","info":["Позволяет использовать Imperium Kata, стиль кулачного боя. См. Imperium Kata."],"stats":"+1 к пассивной Ловкости"},"legion-kata":{"description":"Получите возможность использовать боевые искусства Legion.","info":["Позволяет использовать Legion Kata, стиль кулачного боя. См. Legion Kata."],"stats":""},"master-galebreather":{"description":"Теперь вы можете получать мантры Galebreathe с 3 звёздами.","info":["Этот талант будет снят, если вы перестанете соответствовать его требованиям."],"stats":"+5 к здоровью"},"legendary":{"description":"Парирование и попадание вашим оружием возвращают вам Эфир.","info":["Суммируется с врождённым приростом Эфира от лёгкой атаки."],"stats":""},"prime-ether-bullets":{"description":"Вашим пулям нужно на одно попадание меньше для срабатывания стихийных эффектов, и они теперь немного масштабируются от Интеллекта. [Парное оружие]","info":["True Ether Bullets теперь срабатывает за 2 попадания вместо 3.","Добавляет вашим пистолетам масштабирование 1,2 от Интеллекта. Суммируется с Rosen's Ring."],"stats":""},"all-above-gods-below":{"description":"Любое лечение, которое получил бы ваш противник, пока на нём активен All The Dead Gods, крадётся и отдаётся вам; ваш Heal Boost против PvE повышается до 15%.","info":["Влияет на все источники Anti-Heal, а не только на All The Dead Gods.","Хотя это не отображается визуально, длительность этого эффекта отделена от вашего анти-лечения.","Длительность All Above, Gods Below зависит от суммарного вложения в Силу воли и Интеллект. При 200 суммарных очках он длится всю длительность вашего Anti-Heal. За каждое очко ниже 200 длительность сокращается на 1% (относительно длительности Anti-Heal), до минимума 50% длительности вашего Anti-Heal при 150 суммарных очках.","Не срабатывает, если лечение наложили вы сами: нельзя лечить себя, лечя противника.","Срабатывает только на непассивное лечение. Например (список не исчерпывающий): Flame Wisp, плевки или Bloodless Gem активируют этот эффект, а костры, Conditioned Runner или Curse of the No Life King нет.","Статус Heal Boost увеличивает всё наступательное лечение (например, от Bloodless Gems) при атаке PvE-врагов, на которых сейчас действует ваш Anti-Heal. Все источники Heal Boost складываются между собой и действуют, пока цель страдает от любого вида Anti-Heal. Этот талант даёт +15% Heal Boost."],"stats":"+20 к Рассудку"},"heretic-s-sutra":{"description":"Песнопение, которое на 20 секунд погружает вас в состояние безумия.","info":["При использовании снижает ваш Рассудок. Если Рассудок на уровне 80% или выше, он устанавливается на 65%. Если Рассудок ниже 80%, вы теряете 15% Рассудка.","Автоматически активирует Shared Misery и другой талант на 15 секунд. Тот талант также начинает масштабироваться, так как ваш Рассудок ниже 70%.","При использовании появляется облачко речи с цитатой из заданного списка. Оно зелёное, с жёлтым текстом и уникальным шрифтом. Этот эффект можно воспроизвести с любым сообщением, написав «££» в начале.","Базовая подготовка Heretic's Sutra 0,4 с, базовая перезарядка 24 секунды при 30 Силы воли. За каждое очко Силы воли выше 30 подготовка сокращается на 0,00429 секунды.","Подготовка 0,186 с при 80 Силы воли, максимум 0,293 с при 55 Силы воли и минимум 0,1 с при 100 Силы воли.","Базовая перезарядка Heretic's Sutra 24 секунды при 30 Силы воли. За каждое очко Силы воли выше 30 перезарядка сокращается на 0,085 с.","Перезарядка 19,71 с при 80 Силы воли, максимум 21,86 с при 55 Силы воли и минимум 18 с при 100 Силы воли."],"stats":""},"brick-wall":{"description":"Вы отказываетесь падать. Вас нельзя сбить с ног, пока вы полностью не потеряете сознание. Также сокращает длительность Knockdown.","info":["Сокращение длительности Knockdown зависит от суммарного вложения в Силу воли и Телосложение и полностью устраняется при 100 очках в обоих.","Вы получаете полный иммунитет к ragdoll: от приёмов, которые обычно бы сбили вас в ragdoll, вас лишь отталкивает.","Как следствие, вы становитесь устойчивее к отбрасыванию в целом, так как отсутствие ragdoll сохраняет сопротивление воздуха.","Делает вас устойчивым к ветрам Eternal Gale: вместо ragdoll вы получаете лишь мгновенное оглушение.","Cap Artist отключается этим талантом.","Хотя при полном вложении талант даёт иммунитет к Knockdown, он не даёт эффект Knockdown Immunity и, следовательно, не защищает от статус-эффекта Dazed."],"stats":"+5 к здоровью, +2 к Стойке"},"not-a-scratch":{"description":"На вас нет следов урона.","info":["Ваш персонаж больше не показывает визуально никаких следов урона, как бы мало у него ни было здоровья. Никаких порезов, царапин, анимаций низкого здоровья, рваной одежды и т. д.","Заговоры Bloodrend и Ironsing имеют похожий эффект: визуально скрывают пятна крови и порывы брони при низком здоровье или прочности брони соответственно.","Spotter (для союзников противника) / Rhythm больше не показывает, сколько здоровья у вашего персонажа.","Другой талант, Primal Rage и ещё один талант игнорируют эффекты этого таланта и продолжают показывать противнику соответствующие проценты вашего персонажа.","Если у вас меньше 100 Силы воли, при получении урона ваш персонаж с некоторым шансом вскрикивает от боли. Это чисто визуальный эффект.","Среди криков: «HEEAAAAUUUUURRGHHH!!», «HEEAAAARRGH!!», «OHHHHH GODS THE AGONY!!», «YEAARURUGHH!!», «UUUURURGHHH!!» и «SWEET MEEEEEERRRRRCCCCCYYYY!!». Довольно драматично."],"stats":"+2 к Стойке"},"unyielding-frost":{"description":"Ваше охлаждение (Chilled) может срабатывать сквозь блок; сработавшее через блок охлаждение длится 80% от длительности.","info":["Если у вас меньше 100 Frostdraw, длительность охлаждения (при наложении сквозь блок) сокращается до 25% от исходной.","Не активирует другой талант."],"stats":""},"ignition-card":{"description":"Карта, подтверждающая ваше членство в Ignition Union. Даёт право на более быстрый прирост опыта в подземельях и на работах, хотя взносы немного снизят прирост опыта вне их.","info":["Вы получаете повышенный прирост опыта от работ и подземелий, но сниженный от любого другого контента.","Позволяет пассивно восстанавливать Рассудок в Chariot's Spire."],"stats":""},"union-pager":{"description":"Проверяйте списки работ дистанционно.","info":["Даёт инструмент таланта, работающий как удалённая доска работ: позволяет брать работы из любого места.","Не работает на консолях."],"stats":""},"force-your-way":{"description":"Вы можете парировать непарируемые атаки гигантских монстров ценой прочности брони.","info":["Это не позволяет парировать все непарируемые атаки монстров.","Атаки монстров, которые можно парировать с Force Your Way, отмечены на их страницах.","Потеря прочности брони зависит от урона, который вы получили бы обычно.","При парировании атак, которые избегаются только прыжком или приседом, штраф к потере брони сильно увеличивается."],"stats":""},"union-hook":{"description":"Теперь вы можете использовать крюки Ignition Union для подъёма или спуска.","info":["Нажмите «взаимодействие» внизу Union Hook, чтобы быстро подняться, или наверху, чтобы безопасно спуститься."],"stats":""},"phoenix-flames":{"description":"Каждый раз, когда вы должны сгореть насмерть, вы вместо этого воскресаете с 50% здоровья. Перезарядка 60 секунд.","info":["Лечение зависит от вашего вложения во Flamecharm: лечит 25% максимального здоровья при 0 Flamecharm и получает +0,33% за каждое очко Flamecharm, затем ограничивается 50% здоровья при вложении ≥75.","Если вы использовали Flame Within в бессознательном состоянии, чтобы активировать Phoenix Flames, полученное лечение уменьшается вдвое. Но если вы активировали Flame Within до нокаута, лечение будет полным.","Сочетается с Corpse Explosion, так как он вдвое сокращает время сжигания бессознательных целей (с 8 до 4 с), включая вас самих."],"stats":""},"ad-astra":{"description":"Возвращение домой","info":["Даёт инструмент таланта, который при использовании телепортирует вас в The Floating Keep.","Использование внутри Floating Keep вернёт вас туда, где вы впервые его применили."],"stats":""},"chitin":{"description":"У вас есть слой природной брони (Natural Armor), которая восстанавливается во время отдыха.","info":["Даёт 5% снижения урона в виде природной брони.","Прочность Chitin 215 на 1 уровне мощности и растёт до 500 на 20 уровне.","Снижение урона от Chitin суммируется мультипликативно с талантом Exoskeleton, давая 14,5% снижения урона при не менее 40 Телосложения.","Если есть и Exoskeleton, и Chitin, прочность Exoskeleton имеет приоритет, к ней добавляется +200 прочности, итого 800 на 20 уровне мощности.","Подробнее о природной броне см. другой талант."],"stats":""},"deepfolk":{"description":"Тайны Глубин вам легче разгадать. Ваш разум крепче против их влияния, а в обменах на Знания вы тратите меньше Knowledge.","info":["Даёт множитель прироста Рассудка 1,2x, влияющий на все источники увеличения максимального Рассудка.","Сделки Deep Shrine стоят на 1 Knowledge меньше (минимум 1)."],"stats":""},"echolocator":{"description":"Ваш тонко настроенный слух помогает ориентироваться: вы лучше видите в темноте и чувствуете потенциальные угрозы.","info":["Визуально отмечает текущее местоположение ближайших игроков, обнажающих оружие (даже сквозь Tacet и Lowstride), и появление событий. Игнорирует стены и другие препятствия.","После первой отметки идёт слегка задержанная вторая. По ней можно оценить скорость, с которой движутся отмеченные игроки.","Дальность, на которой что-то может быть отмечено, очень велика.","Слегка увеличивает видимость в тёмных местах."],"stats":""},"feathered-glider":{"description":"В знак независимости по достижении совершеннолетия Тираны отправляются в самостоятельную жизнь с одним лишь планёром собственной работы, спускаясь с горных пиков, где находятся их дома. Вы получаете на 10% меньше урона от падения.","info":["Tiran получает Feathered Glider, более эффективный по высоте планёр с бесконечной прочностью. Эффективность по высоте можно дополнительно улучшить другим талантом.","Цвет планёра зависит от варианта Аспекта (Aspect) и его можно красить.","При использовании горячей клавиши планёра обычный планёр и Sharkscale Glider обычно имеют приоритет над Feathered Glider. Чтобы развернуть Feathered Glider горячей клавишей, нужно полностью израсходовать прочность других планёров."],"stats":""},"loyalty":{"description":"Ваша связь с союзниками достаточно крепка, чтобы снижать урон между вами.","info":["Союзники получают от вас на 35% меньше урона и наносят вам на 35% меньше. Суммируется с талантом Give and Take, давая 48% снижения урона в сумме.","Не действует на урон по себе."],"stats":""},"mark-of-jurik":{"description":"Mark of Jurik, Moonseye. Маяк спокойствия: те, кто рядом с вами, устойчивы к безумию.","info":["Даёт инструмент, дающий ближайшим игрокам восстановление Рассудка. Также усиливает восстановление здоровья у этих игроков и слегка усиливает восполнение еды и жажды от употребления еды и восстановление их крови.","Перезарядка 4 минуты.","Эти бонусы длятся 1 минуту, восстановление здоровья составляет 15% их общего здоровья за эту минуту, лечение 0,25% здоровья в секунду.","Также усиливает не-союзников. Не требует отдыха у костра."],"stats":""},"mark-of-ku":{"description":"Mark of Ku, Мать. Улучшает отдых тех, кто рядом с вами.","info":["Даёт инструмент, усиливающий восстановление крови у ближайших игроков. Также усиливает восстановление здоровья у этих игроков, слегка усиливает восполнение еды и жажды от употребления еды и даёт небольшое восстановление Рассудка.","Перезарядка 3 минуты 30 секунд.","Эти бонусы длятся 1 минуту, восстановление здоровья составляет 15% их общего здоровья за эту минуту, лечение 0,25% здоровья в секунду.","Также усиливает не-союзников. Можно использовать только во время отдыха у костра."],"stats":""},"mark-of-nemit":{"description":"Mark of Nemit, Первый Зверь. Еда, съеденная в вашем присутствии, питательнее.","info":["Даёт инструмент, усиливающий восполнение еды и жажды у ближайших игроков. Также усиливает восстановление здоровья у этих игроков, слегка усиливает восстановление их крови и даёт небольшое восстановление Рассудка.","Перезарядка 3 минуты 30 секунд.","Эти бонусы длятся 1 минуту, восстановление здоровья составляет 15% их общего здоровья за эту минуту, лечение 0,25% здоровья в секунду.","Также усиливает не-союзников. Можно использовать только во время отдыха у костра."],"stats":""},"maudet":{"description":"Ваше понимание своей судьбы таково, что новое часто даётся вам само собой. Люди ценят вашу дипломатичную манеру речи.","info":["Пассивно даёт преимущества Autodidact Boon: 3 бесплатных очка тренировки атрибутов на каждом уровне. Эффект суммируется с этим Boon.","Увеличивает прирост репутации у фракций и вашу начальную репутацию у всех фракций."],"stats":""},"molt":{"description":"Недуги и благословения проходят быстрее.","info":["Охлаждение (Chilled), эффекты зелий и удушье имеют сниженную длительность.","Не работает на другие статус-эффекты."],"stats":""},"mothwing-dust":{"description":"Когда кто-то бьёт первым, вы выпускаете Mothwing Dust, позволяя увидеть нападающего. Ваши усики улучшают периферийные чувства, сужая угол, под которым вас можно ударить в спину.","info":["Когда вас бьют в начале боя, ударивший игрок подсвечивается полупрозрачным красным контуром. Эффект длится 10 секунд.","Угол, под которым вас можно ударить в спину (активируя эффекты «при ударе в спину»), сильно уменьшается."],"stats":""},"navae-s-guidance":{"description":"Звезда Navae направляет ваш путь, показывая дорогу вперёд. Щелчок правой кнопкой по картам ставит маркер (Waymarker), за которым можно следовать. Вы менее подвержены голоду.","info":["Вы получаете компас вверху экрана, указывающий на восток.","Щелчок правой кнопкой по карте ставит путевую точку и в физическом мире, и на самой карте. Если путевая точка уже стоит, щелчок по карте изменит её положение, а не поставит новую.","Снижает пассивную потерю сытости.","Если у вас есть недостаток Blind, вы получаете область зрения вокруг персонажа."],"stats":""},"nightchild":{"description":"Полагаясь на инстинкты, вы от природы более скрытны. Вы проворнее на деревянных поверхностях.","info":["Вы начинаете с 20% дополнительной скрытности и получаете множитель прироста скрытности 1,2x.","Этот множитель не действует на скрытность от приседания, Lowstride, Tacet, другого таланта фракции и 20% скрытности от самого Felinor.","Множитель скрытности влияет на -20% скрытности от недостатка Obvious и +15% скрытности от Sly Boon; первый уменьшает вашу начальную скрытность на 24.","Вы получаете бонус к высоте лазания на поверхностях любого вида, а не только деревянных."],"stats":""},"seaborne":{"description":"Вы хорошо разбираетесь в кораблях и их обслуживании.","info":["Корабли стоят на 20% меньше Notes на постройку и ремонт, поворачивают на 20% быстрее и имеют на 10% больше здоровья."],"stats":""},"teachings-of-the-edenkite":{"description":"Найдите свой центр.","info":["Позволяет медитировать: вы излучаете белую ауру, а над головой кружатся два белых шара.","Очень сильно снижает расход сытости и жажды, пока вы пассивно получаете общий опыт, опыт атрибутов и восстанавливаете здоровье в посредственном темпе, слегка сниженном в бою."],"stats":""},"versatile":{"description":"Вы учитесь пользоваться новым снаряжением быстрее других. Вы можете экипировать вещи при значениях на 3 ниже требования.","info":["Работает как для требований снаряжения, так и оружия, но не для требований мощности (Power) предметов.","Также снижает требования по атрибутам для сплавления предметов.","Versatile снижает все требования у вещей, где их несколько, поэтому, например, Curved Blade of Winds с 72 Galebreathe и 37 среднего оружия был бы возможен для Khan. Кроме того, Versatile суммируется со снижением требований по оружию у Silentheart.","Базовое снижение урона от невыполнения требований вашего оружия учитывает Versatile: оно мягче для Khan и не применяется, если вы в пределах 3 очков вложения от обычных требований оружия."],"stats":""},"backstabber":{"description":"Попадание лёгкой атакой в спину заставляет вас схватить противника и ударить его ещё раз, нанеся дополнительные 15 урона. [перезарядка 15 с]","info":["Стоя позади врага, вы поднимаете оружие вверх обратным хватом. По M1 вы бьёте вниз с бонусом 10% к скорости замаха, закалываете цель, затем отпрыгиваете.","Наносит 20 урона, а не 15.","Помимо перезарядки 15 с, есть перезарядка 3 секунды на цель.","Срабатывает на M1, умения Silentheart и критические атаки с тегом M1.","У этого таланта нет ограничения по дальности.","Накладывает оглушение и ragdoll."],"stats":"+1 к пассивной Ловкости"},"executioner-s-frenzy":{"description":"Попадание лёгкой атакой, пока Стойка противника приостановлена, сокращает перезарядку его убийства из тени на 5 секунд.","info":["Статус Paused Posture даёт талант фракции и Maiming Claws."],"stats":""},"fatal-stealth":{"description":"Вы наносите увеличенный урон в спину противникам в зависимости от вашего текущего показателя скрытности.","info":["Даёт +0,2% урона за каждую 1 скрытности атакам, попадающим в спину противника, как модификатор урона. Влияет на все источники урона, получающие модификаторы урона.","Скрытность, полученная не от снаряжения или нарядов, этим талантом не учитывается. Множители скрытности (Felinor, приседание, Lowstride) тоже не применяются.","Как ни странно, недостаток Obvious является исключением: он снижает ваш урон в спину на 4%.","Следующие источники скрытности не учитываются для бонуса к урону этого таланта: врождённая скрытность Felinor и множитель её прироста, вложение в Ловкость, Sly Boon, приседание, Lowstride, Murmur: Tacet и талант фракции.","Не усиливает убийства из тени.","О том, где можно получить скрытность, см. страницу Stealth.","Максимальная скрытность, которую можно получить только от снаряжения, 30% (+6% урона).","В частности, Inquisition Light Outfit даёт 50% скрытности (+10% урона)."],"stats":""},"flanking-maneuvers":{"description":"Враги, которых вы убили из тени (assassinate), получают больше PEN от ваших соратников по отряду.","info":[],"stats":""},"stature-break":{"description":"Удар в спину любого рода отключает Стойку (Posture) на 4 секунды. [перезарядка 8 с]","info":["Накладывает статус-эффект Paused Posture, не давая восстанавливаться Стойке от большинства источников.","Во время Paused Posture нельзя восстанавливать Стойку: пассивной регенерацией, парированием или талантом Steady Nerves. Все остальные способы восстановления Стойки этот статус-эффект полностью игнорируют."],"stats":""},"tacet-minimization":{"description":"Сфокусируйте свой Tacet ещё сильнее, временно уменьшив радиус, в котором вас замечают.","info":["Даёт инструмент, уменьшающий размер пузыря Tacet до минимального и дающий 400% фиксированной скрытности на 10 секунд. Перезарядка 1 минута.","Для использования требуется максимальный Эфир, хотя Эфир не расходуется."],"stats":""},"adept-ironsinger":{"description":"Теперь вы можете получать мантры Ironsinger с 1 звездой.","info":["Этот талант будет снят, если вы перестанете соответствовать его требованиям."],"stats":""},"expert-ironsinger":{"description":"Теперь вы можете получать мантры Ironsinger с 2 звёздами.","info":["Этот талант будет снят, если вы перестанете соответствовать его требованиям."],"stats":""},"iron-veins":{"description":"Вы кровоточите не так, как другие. Урон от кровотечения снижен на 30%. Потеря крови снижена на 75%.","info":["При 100 Ironsing урон кровотечением снижается с 15% масштабированного урона до 10,5%. Кровотечение от Speed Demon снижается с 7,5% масштабированного урона до 5,25%.","Снижение потери крови менее эффективно, если вы используете зачарование Curse of the No Life King.","Снижение потери крови суммируется мультипликативно с Cauterized Wounds.","Эффекты Iron Veins линейно растут с вложением в Ironsing до требования, теряя 0,3% снижения урона кровотечением и 0,75% снижения потери крови за каждое очко Ironsing ниже 100.","Делает вашу кровь светло-серой при атаке с визуальным эффектом рубящего урона.","Раньше назывался «Alloyblood»."],"stats":""},"ironsinger":{"description":"Даёт вам способность повелевать металлом как Ironsinger. Нажмите X, чтобы притянуть Metal Rods.","info":["Мантры Ironsing накладывают на цели стаки Metal Rods. Нажатие X притягивает поражённых к вам, сила притяжения зависит от количества Metal Rods.","На одну цель нельзя наложить больше 5 Metal Rods, если у вас нет соответствующих талантов.","Клавишу притягивания стержней можно настроить в настройках."],"stats":""},"master-ironsinger":{"description":"Теперь вы можете получать мантры Ironsinger с 3 звёздами.","info":["Этот талант будет снят, если вы перестанете соответствовать его требованиям."],"stats":"+5 к здоровью"},"acceleration-points":{"description":"Удар в спину противника мантрами мобильности или обычными атаками теперь крадёт и даёт дополнительный импульс.","info":["Этот эффект может активировать любая мантра, экипированная в слоты мобильности."],"stats":"+5 к пассивной Ловкости"},"decisive-winds":{"description":"Когда вы получаете урон при здоровье ниже 50%, вы облачаетесь в ауру Decisive Winds на 10 с.","info":["Decisive Winds даёт ускорение 25%, пока вы в пределах 20 студов от цели, запустившей этот эффект.","Перезарядка 30 секунд.","Срабатывает при блоке/парировании/уклонении, вопреки описанию, но не срабатывает на урон по себе.","Вопреки описанию, у Decisive Winds нет «ауры», нет ни звуковых, ни визуальных эффектов, а единственный признак активации это индикатор перезарядки."],"stats":"+5 к Эфиру"},"jetstream-pursuit":{"description":"После успешного Flourish телепортируйтесь к противнику, когда он перестанет двигаться. Вы получаете значительный импульс.","info":["При срабатывании на нечеловекоподобных NPC переносит вас в центр хитбокса NPC."],"stats":""},"oath-jetstriker":{"description":"Вы клянётесь течь вместе с самой Песней, дрейфуя туда, куда вас приведут следы. Если Песня пронизывает всё, пусть она станет вашим проводником, а вы её господином.","info":["Подробнее см. Oath: Jetstriker."],"stats":"+1 слот мантры мобильности, +1 универсальный слот мантры, +5% PEN"},"rush-of-ancients":{"description":"Рывок на максимальном импульсе спринта делает вас одним целым с самим ветром.","info":["Увеличивает дальность рывка и делает вас невидимым на очень короткое время при рывке.","Перезарядка 8 секунд в бою."],"stats":"+4 к пассивной Ловкости"},"stratos-step":{"description":"Удержание пробела при лазании теперь позволяет делать Stratos Steps и подниматься ещё выше.","info":["Stratos Steps срабатывает только дважды, затем уходит на перезарядку. Перезарядка относится к отдельным шагам. Кроме того, Stratos Step тратит Эфир на каждый шаг."],"stats":"+5 к здоровью, +3 к пассивной Ловкости"},"jus-karita":{"description":"Примите стиль боя Justicars, основанный на ударах ногами.","info":["Позволяет использовать стиль кулачного боя Jus Karita."],"stats":""},"the-floor-is-lava":{"description":"Ваши Eruptions оставляют под собой смертоносные лужи лавы. Не упадите в них.","info":["Урон имеет небольшое масштабирование от Flamecharm.","Длительность луж лавы растёт с вложением во Flamecharm."],"stats":""},"entropy-link":{"description":"Мир разбит, связан хрупкими нитями. Пройдите путь, назвав место назначения среди пламени.","info":["Вы можете быстро перемещаться в определённые места, отдыхая у костра. Места открываются взаимодействием с особыми метеоритами, разбросанными по карте. Сев у костра и напечатав название нужного метеорита, вы будете перенесены прямо к нему.","Во время телепортации можно нести предметы и людей. Если вы несёте игрока, будьте осторожны: высокий шанс неудачи (из-за общей глючности).","По Overworld можно найти шесть метеоритов:","Etrean Luminant:","Ceres (с видом на путь к заброшенной хижине ниже Etris, на чёрном скалистом выступе)","Europa (на верхней части скал с видом на вход в Valley of Heroes, справа)","Fortuna (над церковью Erisor)","Eastern Luminant:","Hygiea (около Songseeker Wilds Sea Highway)","Eunomia (над Sibex)","Pallas (на небольшом участке суши у Sea Highway в Miner's Landing)"],"stats":""},"oath-linkstrider":{"description":"Вы клянётесь отдать собственную жизнь ради других. Выйдя из гущи боя, вы становитесь основой силы ваших союзников.","info":[],"stats":"+2 слота мантр поддержки, +1 универсальный слот мантры, +5% PEN"},"symbiotic-link":{"description":"Нажмите X, наведя курсор на союзника, чтобы усилить его, или на противника, чтобы ослабить. Созданные вами связи разрушаются, когда вы получаете урон от врага.","info":["Синие нити (союзники) получают ускорение, 20% сопротивления урону и 5% к урону.","Красные нити (враги) получают небольшой штраф к скорости.","Одновременно может быть только по одной активной связи каждого типа.","Умение можно использовать только на человекоподобных NPC и игроков.","Связи также разрываются, если вы слишком далеко от цели. При разрыве из-за дальности есть льготный период 3 секунды, в течение которого они не рвутся.","Удары союзников по вам не разрывают ваши связи.","Позволяет пассивно видеть полосу здоровья союзников, даже когда умение не активно."],"stats":""},"mark-of-the-lone-warrior":{"description":"Вы развиваетесь гораздо быстрее, когда действуете в одиночку. Вы получаете бонус к урону, сталкиваясь с угрозами в одиночку, а также когда врагов больше.","info":["Даёт множитель опыта, если никакой другой игрок не получил зачёт за убийство моба или завершение события.","Наносите на 5% больше урона противникам, которых вы пометили боевой меткой (combat tag), или противникам, которые пометили вас, но только если у них меньше или столько же боевых меток, сколько у вас. Получайте дополнительный бонус к урону 5% за каждую боевую метку выше 1.","Бонус к урону работает, даже если на сервере есть ваши союзники. Это не задуманное поведение (баг).","Для первого бонуса 5% боевая метка на вас не нужна: он активен при попадании, на котором вы метите противника, но чтобы бонус превысил 5%, на вас должно быть больше 1 боевой метки.","Работает в PvE-бою, где каждый моб считается отдельной боевой меткой."],"stats":""},"art-of-the-deal":{"description":"Ваш контакт с торговцами даёт вам более низкие цены!","info":["Снижает цену покупки предметов на 10%."],"stats":""},"chain-of-perfection":{"description":"Вы получаете стаки Perfection при попадании по мобам атаками оружием или мантрами. Мантры стоят только половину стака.","info":["Вы получаете бонус к урону 5% против PvE-врагов за каждый стак Perfection выше 5, максимум +100% урона при 25 стаках.","Perfection действует как итоговый множитель урона, обходящий потолки модификаторов урона.","Источники урона, которые не получают модификаторы урона (например, горение), не получают выгоды от Chain of Perfection.","За одну атаку нельзя получить больше 3 стаков.","При получении урона из любого источника, кроме урона по себе (исключая урон от падения), все стаки теряются."],"stats":""},"already-dead":{"description":"Вы получаете сниженный урон от умений, стоящих здоровья.","info":["Убирает урон по себе от бегущей критической атаки Deepspindle.","Снижает урон по себе от Shade Devour, Flame Within (при применении, а НЕ тики горения), Rush Hour, Shadow Travel и Electrify.","В сочетании с талантом Circuit Breaker от Stormchanter's Raiments использование Electrify будет лечить вас на 12 здоровья вместо урона.","Снижает урон по себе от недостатка Poison (потеря здоровья) у Corrupted Resonance примерно на 1%.","Снижает наложение увядания (Wither) от недостатка Wither у Corrupted Resonance примерно на 2%."],"stats":""},"crippling-darkness":{"description":"Ваши необычные атаки имеют 20% PEN.","info":["Даёт +20% PEN всему, что не является атакой оружием.","В первую очередь это просто 20% PEN мантр, но он также действует на источники урона, не являющиеся мантрами или оружием, такие как детонации кристаллов, Eruptions, перегрузки Surge и другие.","На общее сопротивление Reinforce влияет PEN, поэтому Crippling Darkness заставит такие вещи, как кровотечение или Steam, которые обычно обходят броню, наносить против Reinforce больше урона, чем иначе."],"stats":""},"blinded":{"description":"Ваше зрение чем-то затуманено. Почему-то вы чувствуете себя безопаснее. Вы вспоминаете тепло своей юности.","info":["Накладывает на вашего персонажа эффект Blinded, делая всё темнее и создавая туман на больших расстояниях.","Клятва Blindseer даёт полное зрение, пока вы ослеплены.","Даёт иммунитет к мантрам Flame Blind и Gaze."],"stats":""},"brunt":{"description":"При хвате двумя руками вы получаете меньше урона по Стойке (Posture).","info":["Снижает получаемый урон по Стойке на 10% при удержании оружия двумя руками (недоступно для лёгкого оружия)."],"stats":""},"careful-handling":{"description":"Снижает шанс выронить ингредиенты при смерти.","info":[],"stats":""},"centurion-s-resolve":{"description":"Ваши атаки Legion Kata/Imperium Kata наносят на 4% больше урона.","info":["Считается модификатором урона, поэтому накапливается до потолка модификаторов урона и подчиняется ему."],"stats":""},"coldseep-reactor":{"description":"Культивируя местные хемосинтетические микроорганизмы Глубин и используя их как источник энергии, ваш шлем гудит защитным полем статического электричества и тепла.","info":["Даёт полный иммунитет к паразитам Второго слоя."],"stats":""},"diver-s-resilience":{"description":"Вы можете парировать непарируемые атаки гигантских монстров, но из-за тяжести пластин ваша скорость слегка снижена.","info":["Перезарядка 20 секунд.","Нельзя парировать ВСЕ типы атак, как и с Hunter's Brace и Force Your Way. Кроме того, ваша скорость передвижения снижена."],"stats":""},"elegy-of-light":{"description":"Невысказанная клятва Waking God откликается в вас, пусть и ненадолго. Защищает вас от эффектов Deep Gems на 3 минуты и даёт Gem Enhancement. Остаётся бездействующим, пока вы не отнимете жизнь равного.","info":["Даёт умение-инструмент таланта. При активации ваше тело излучает свет, и Deep Gems не могут сработать на вас. Эффект длится 3 минуты.","Gem Enhancement увеличивает эффективность ваших Deep Gems в PvE.","После окончания действия, чтобы перезарядить его, нужно убить другого игрока равной мощности или босса."],"stats":""},"featherfall":{"description":"Не даёт падениям наносить вам урон. После того как будет поглощено достаточно урона, подвеска становится неактивной и требует времени для перезарядки.","info":["Поглощает до 255 урона от падения, затем уходит на перезарядку 2 минуты.","Поглощённый урон от падения до ухода на перезарядку не сбрасывается и сохраняется между серверами."],"stats":""},"ferryman-s-curse":{"description":"Ношение этого даёт 20% шанс превратить входящий стихийный урон в урон молнией.","info":["Сочетается с суммарным 51% сопротивления Thundercall этого наряда."],"stats":""},"fleetfoot":{"description":"Вы получаете начальное ускорение при прыжке из скольжения.","info":[],"stats":""},"grotesque-resilience":{"description":"Вы получаете сниженный урон от эффектов «урон со временем» (Damage over Time).","info":["Снижает урон от горения на 50%.","Если вы используете Flame Within, снижение урона со временем уменьшается до 25%.","Снижает урон от кровотечения на 25%.","Не работает на все эффекты урона со временем.","Не работает на: недостаток Poison (потеря здоровья) у Corrupt Resonance, яд Deep Widow, Reveal у Bladeharper, Viscosity, Deferred и другой эффект Bloodrend."],"stats":""},"immortality":{"description":"Остатки Mind Veil шлема оживают, когда вас должны вырубить, и поглощают весь урон на короткое время. Перезарядка 30 с. Viscosity отвергается.","info":["Даёт один экземпляр защиты от нокаута, оставляя вас с 1% здоровья при срабатывании.","Зачарование Viscosity отключается, пока вы носите это снаряжение."],"stats":""},"knack":{"description":"С деревьев при рубке получается больше дерева. Скорость вашего ремонта увеличена.","info":["Увеличивает скорость ремонта лодки."],"stats":""},"looter":{"description":"Вы получаете дополнительную добычу с предметов, которые сдаёте за награды.","info":["Влияет на сдачу: Artifact, Strange Egg, Pure Ore и Sack. Также влияет на сдачу взрывных ящиков Scope."],"stats":""},"pleeksty-s-will":{"description":"Вы получаете значительно больше Эфира от употребления стихийных ингредиентов.","info":["Употребление Gale Stones, Heartstars, Dying Embers, Spark Glands и Frigid Prisms даёт значительно больше Эфира.","У употребления стихийных ингредиентов перезарядка 20 секунд.","Этот талант необходим для боя с Aska в Firfire. Без этого таланта, Pleeksty's Faith или Flame Worshipper Armor его пламя вас сметёт."],"stats":""},"treefelling-blow":{"description":"Вы можете собирать древесину с деревьев, которые валите кулаками. Это естественно.","info":["Позволяет получать дерево (Wood) при уничтожении деревьев с помощью Strong Left."],"stats":""},"way-of-navae":{"description":"Получите возможность использовать кулачный бой против оружия, в том числе блокировать оружие руками с помощью Эфира.","info":["Позволяет использовать стиль кулачного боя Way of Navae.","Блок атак не тратит ваш Эфир при использовании этого стиля, вопреки тому, что подразумевает описание."],"stats":""},"chief-s-will":{"description":"Лёгкие атаки Way of Navae получают дополнительные 10% пробивания.","info":["Даёт M1 и критическим атакам с тегом M1 стиля Way of Navae на 10% больше PEN.","Также влияет на кулачное оружие с уникальными анимациями лёгкой атаки.","Не обходит потолок PEN."],"stats":""},"fists-of-navae":{"description":"Вдвое увеличивает количество Эфира, которое вы получаете за успешные лёгкие атаки.","info":["Удваивает Эфир, получаемый от попавших M1."],"stats":""},"oath-oathless":{"description":"Вы клянётесь никогда не быть связанным никакой Клятвой, жить свободно от оков. Если свобода воли иллюзия, почему бы не сделать её убедительной?","info":[],"stats":"+10 к здоровью, +5% PEN, +3 универсальных слота мантр, +20% брони от Клятвы, +20% брони от монстров"},"arachnid-surge":{"description":"Даёт короткое окно очень мощного лазания ценой изнурения ваших лодыжек.","info":["Даёт инструмент таланта, который на несколько секунд сильно увеличивает высоту лазания при использовании. После окончания эффекта вы ненадолго не сможете двигаться."],"stats":""},"bane":{"description":"Активируйте, чтобы ваши лёгкие атаки телепортировали вас к ближайшему врагу поблизости. [перезарядка 100 с]","info":["Даёт инструмент таланта, который при использовании позволяет телепортироваться к противнику при каждом M1 в течение 20 секунд.","Дальность телепортации ограничена 25 студами.","Bane также даёт ускорение на всю свою длительность."],"stats":""},"battle-hardened":{"description":"Снижает урон, получаемый от пробития блока мантрами, на 20%.","info":[],"stats":""},"broodlord-s-scream":{"description":"Использование Sing, Taunt или Ardour Scream накладывает анти-лечение (Anti-Heal) на время действия приёма.","info":["Накладывает 100% анти-лечения.","Эти атаки получают звуковой эффект от атаки-крика Mudskipper Broodlord.","Также применяется к вашим союзникам."],"stats":""},"circuit-breaker":{"description":"Electrify больше не наносит урон по себе при использовании.","info":["Инструмент таланта Electrify больше не расходует здоровье при использовании.","В сочетании с талантом Already Dead от Deepscorn Casque использование Electrify будет лечить вас на 12 здоровья."],"stats":""},"demon-step":{"description":"Активируйте, чтобы получить краткие кадры неуязвимости при движении вперёд. Для активации нужно 50 Эфира, и она повышает вашу Стойку на 2, затем на 20% при каждом использовании.","info":["При использовании вы теряете 50 Эфира, чтобы пройти короткое расстояние вперёд в кадрах неуязвимости. Кроме того, вам наносится урон по Стойке в размере 2 + 20% вашей текущей Стойки.","Перезарядка 1 секунда."],"stats":""},"focused-hematoma":{"description":"Увеличивает количество получаемого временного здоровья на 15%.","info":[],"stats":""},"grapple":{"description":"Прицельтесь мышью и выстрелите крюком из металлической руки в цель, притянув себя к ней. [Для использования требуется Familiar Prosthetic Arm]","info":["При использовании выданного инструмента вы цепляетесь за место курсора и на высокой скорости притягиваете себя к нему.","Если при использовании курсор наведён на игрока или NPC, вы также притягиваете его к себе, как мантра Lord's Slice.","Если выполнить критическую атаку Tanto, зацепившись за противника, вы поразите его независимо от дальности."],"stats":""},"hyperbody":{"description":"Накладывает на союзников вокруг вас бонус, увеличивающий скорость, защиту и регенерацию. Эффект ослабевает, чем больше союзников вы усиливаете. [перезарядка 2 мин]","info":["Даёт инструмент таланта, который накладывает усиления на вас и союзников.","Hyperbody длится 30 секунд, но длительность сокращается на 3 секунды на каждого затронутого человека, включая вас.","Перезарядка Hyperbody 2 минуты.","Даёт ускорение +7,5 студа/с, поровну распределяемое между усиленными союзниками.","Даёт +50% пассивной регенерации здоровья, поровну распределяемой между усиленными союзниками.","Даёт 35,5% снижения урона. Оно увеличивается на 20% мультипликативно за каждого усиленного союзника.","Например, при одном союзнике даёт +42,6% снижения урона, при двух 51,12% и так далее.","Hyperbody может суммироваться, если его использует кто-то из ваших союзников, но общая эффективность составит лишь 90% от базовой."],"stats":""},"lethal-dose":{"description":"Яд от вашего скрытого клинка действует вдвое дольше.","info":["Длительность яда от Hidden Blade, усиливающего Shaky Block, увеличивается с 8 секунд до 16."],"stats":""},"life-leech":{"description":"Ваши призывы теперь лечат вас каждый раз, когда наносят урон.\n*Есть ограничение по дальности: призывы не будут лечить вас, если вы слишком далеко от них.\n*Подходящие призывы: монстры Blight от Parasol, паук-призыв The Weaving Web, клоны Visionshaper (в частности Illusory Servants, Illusory Counter и Cheap Trick), Lightning Clones и Flame Sentinel.\n*Неподходящие призывы: Metal Turret, клоны Visionshaper (от Mirror Illusion), талант You'll Need to Get Past Me и марионетки Twisted Puppets.","info":[],"stats":""},"light-piercer":{"description":"При использовании копья выпускает 3 световых копья, пронзающих противника и его блок. В Familiar Prince's Armor вся пассивная регенерация увеличивается на 10%.","info":["Даёт инструмент таланта, который можно использовать только с экипированным копьём. При использовании выпускает три снаряда-копья вперёд, каждый наносит 10 урона. Они имеют 100% урона сквозь блок (chip).","Копья пронзают цели и продолжают свой путь, даже если попали в одну цель.","Копья могут пролететь до ~160 студов, прежде чем исчезнуть.","Бонус к регенерации мультипликативен с другими источниками регенерации."],"stats":""},"lightning-drop":{"description":"В воздухе быстро упадите вниз и поразите противника там, где приземлитесь, яростной молнией.","info":["Даёт инструмент таланта, который можно использовать только на определённой высоте над землёй.","При использовании вы превращаетесь в удар молнии и обрушиваетесь на землю с ударной волной, сбивая в ragdoll и повреждая цели. Урон зависит от разницы высот."],"stats":""},"heartwing-beat":{"description":"Ваше сердце бьётся в новом ритме, а ваша воздушная атака обретает новое воплощение.","info":["Заменяет вашу воздушную атаку свистящей атакой, накладывающей увядание (Wither) и имеющей врождённое кровотечение.","Нельзя использовать Relentless Hunt у Silentheart, пока этот талант не на перезарядке.","Базовый урон Heartwing Beat 25, и он повторяет показатель масштабирования от вашего экипированного оружия. Попутно этот талант использует формулу масштабирования оружия.","Например, использование Heartwing Beat на Sword даст ему масштабирование 2,5 от среднего оружия, а на Repeater масштабирование 15 от лёгкого оружия.","Перезарядка Heartwing Beat 10 секунд."],"stats":""},"herbivore":{"description":"Вы получаете больше питательности от растительной еды.","info":[],"stats":""},"justicar-whistle":{"description":"Позовите на помощь Justicar.","info":["При использовании открывает меню, позволяющее позвать на помощь. После использования игроки-Justicar смогут использовать инструмент Justicar's Call, чтобы ответить на ваш зов, телепортировавшись на ваш сервер.","Игроков-Justicar настоятельно поощряют помогать вам с событиями и отбиваться от игроков Voidwalker.","Свисток не работает для игроков Lone Warrior или Deepbound, если они выше 16 уровня."],"stats":""},"benefactor":{"description":"Вы получаете репутацию за продажу товаров Antiquarian на территориях фракций.","info":["Даёт репутацию у фракции при продаже предметов соответствующему Antiquarian.","Продажа предметов на 100 Notes даёт 1 репутации, то есть чтобы перейти от нейтральной (0) к герою (300), потребуется продать предметов на 30 000 Notes."],"stats":""},"justicar-s-gift":{"description":"Ваши мантры поддержки Justicar теперь лечат союзников на 10 здоровья вместо 5. Длительность вашего Alsin's Aid увеличивается до 15 секунд.","info":[],"stats":""}},"glossary":{"Tempo":"Темп","Posture":"Стойка","Ether":"Эфир","Sanity":"Рассудок","Health":"Здоровье","Temporary Health":"Временное здоровье","Armor Durability":"Прочность брони","Combat Tag":"Боевая метка","M1":"обычная атака (M1)","Critical":"критический удар","Guardbreak":"пробитие блока","Parry":"парирование","Dodge":"уклонение","Block":"блок","Flourish":"Flourish","Chip Damage":"урон сквозь блок","PEN":"пробивание брони (PEN)","Backhit":"удар в спину","Vent":"Vent","Scale-down":"Scale-down","Investment Scaling":"масштабирование от вложений","Hard Requirements":"жёсткие требования","Mantra":"Мантра","Mantra Slots":"слоты мантр","Aspect":"Аспект","Oath":"Клятва","Murmur":"Murmur","Attunement":"Школа","Multi-Attunement":"несколько школ","Stealth":"скрытность","Resonance":"Резонанс","Reinforce":"Усиление","Carry Load":"грузоподъёмность","Potency":"сила (Potency)","Passive Agility":"пассивная Ловкость","Strength":"Сила","Fortitude":"Телосложение","Agility":"Ловкость","Intelligence":"Интеллект","Willpower":"Сила воли","Charisma":"Харизма","Burn":"горение","Chill":"охлаждение","Shock":"шок","Bleed":"кровотечение","Wither":"увядание","Charm":"очарование","Taunt":"провокация","Daze":"оглушение","Ragdoll":"ragdoll","Unconscious":"бессознательное состояние","Winded":"одышка","Suffocation":"удушье","Anti-Heal":"анти-лечение","Speed Boost":"ускорение","Slow":"замедление","Light Weapon":"лёгкое оружие","Medium Weapon":"среднее оружие","Heavy Weapon":"тяжёлое оружие","Fist":"кулаки","Pistol":"пистолет","Rifle":"винтовка","Spear":"копьё","Greataxe":"секира"}};
